/**
 * Hide everything except a modal surface from assistive technology.
 *
 * A focus trap keeps the Tab key inside; it does nothing for a screen reader's
 * virtual cursor, which walks the whole document. Both are needed, and they are
 * separate primitives because a non-modal popover wants neither.
 *
 * Only the siblings along the ancestor chain are marked, not every node in the
 * document: `aria-hidden` on a subtree hides its descendants too, so marking
 * O(depth) elements does the job of marking O(n). A sibling that a kept element
 * contains is never marked: a sheet's cancel and backdrop beside its content stay
 * live when the positioner is kept (R60). Nor is a sibling that contains a kept
 * element: a persistent widget portalled elsewhere keeps its container live, and
 * the walk from it does not mark the surface's own ancestors. For a target inside
 * `body`, the walk stops there and `<head>` is never touched (R65).
 *
 * Counted, not flagged: nested dialogs mark the same siblings, and the inner one
 * closing must not reveal the page to the outer one still open.
 */

const counts = new WeakMap<Element, number>();
const previous = new WeakMap<Element, string | null>();

export interface AriaHiddenOptions {
  /**
   * Also set `inert`, which takes focus and pointer events away as well.
   * Off by default: it changes behaviour, not only the accessibility tree.
   */
  readonly inert?: boolean | undefined;
  readonly layer?: string | undefined;
}

const NOOP: VoidFunction = () => {};

function shouldSkip(node: Element): boolean {
  // Live regions must keep announcing from under a modal, and a script or style
  // tag has nothing to hide.
  if (node.hasAttribute("aria-live") || node.hasAttribute("data-sui-live-region")) return true;
  const tag = node.tagName;
  return tag === "SCRIPT" || tag === "STYLE" || tag === "LINK" || tag === "TEMPLATE";
}

export function hideOthers(
  targets: readonly (HTMLElement | null | undefined)[],
  options: AriaHiddenOptions = {},
): VoidFunction {
  const kept = targets.filter((node): node is HTMLElement => node != null);
  const root = kept[0]?.ownerDocument.body;
  if (root === undefined || kept.length === 0) return NOOP;

  const marked = new Set<Element>();

  for (const target of kept) {
    let node: Element = target;
    while (node !== root) {
      const parent: Element | null = node.parentElement;
      if (parent === null) break;
      for (const sibling of parent.children) {
        if (sibling === node || marked.has(sibling) || shouldSkip(sibling)) continue;
        if (kept.some((spared) => spared.contains(sibling) || sibling.contains(spared))) continue;
        if (
          options.layer !== undefined &&
          sibling.getAttribute("data-sui-layer-parent") === options.layer
        )
          continue;

        const count = counts.get(sibling) ?? 0;
        if (count === 0) {
          previous.set(sibling, sibling.getAttribute("aria-hidden"));
          sibling.setAttribute("aria-hidden", "true");
          if (options.inert === true) sibling.setAttribute("inert", "");
        }
        counts.set(sibling, count + 1);
        marked.add(sibling);
      }
      node = parent;
    }
  }

  return () => {
    for (const sibling of marked) {
      const count = (counts.get(sibling) ?? 1) - 1;
      if (count > 0) {
        counts.set(sibling, count);
        continue;
      }
      counts.delete(sibling);
      const original = previous.get(sibling) ?? null;
      previous.delete(sibling);
      if (original === null) sibling.removeAttribute("aria-hidden");
      else sibling.setAttribute("aria-hidden", original);
      if (options.inert === true) sibling.removeAttribute("inert");
    }
    marked.clear();
  };
}

/**
 * One pair of live regions per document, shared by every component that speaks:
 * toast, clipboard, slider values, combobox result counts, editable.
 *
 * Deduplicated on purpose. A live region only announces when its content changes
 * *after* it is in the accessibility tree, so a component that creates its own
 * region and fills it in the same tick announces nothing at all — the classic
 * failure. The regions here are created once, up front and empty, and text is set
 * on a later task.
 *
 * The same mechanism is why an identical message has to be cleared first: setting
 * the same string twice is not a change, and screen readers stay silent.
 */

import { setStyle } from "../dom/attrs";
import { visuallyHiddenStyle } from "./visually-hidden";

export type Politeness = "polite" | "assertive";

export interface LiveAnnouncer {
  announce(message: string, politeness?: Politeness): void;
  destroy(): void;
}

interface AnnouncerState {
  readonly announcer: LiveAnnouncer;
  readonly regions: Map<Politeness, HTMLElement>;
}

const announcers = new WeakMap<Document, AnnouncerState>();

function createRegion(doc: Document, politeness: Politeness): HTMLElement {
  const region = doc.createElement("div");
  region.setAttribute("role", politeness === "assertive" ? "alert" : "status");
  region.setAttribute("aria-live", politeness);
  region.setAttribute("aria-atomic", "true");
  region.setAttribute("data-sui-live-region", politeness);
  setStyle(region, visuallyHiddenStyle);
  doc.body.append(region);
  return region;
}

export function getLiveAnnouncer(doc: Document): LiveAnnouncer {
  const existing = announcers.get(doc);
  if (existing !== undefined) return existing.announcer;

  const regions = new Map<Politeness, HTMLElement>([
    ["polite", createRegion(doc, "polite")],
    ["assertive", createRegion(doc, "assertive")],
  ]);
  const pending = new Map<Politeness, number>();
  const win = doc.defaultView;

  const announcer: LiveAnnouncer = {
    announce(message: string, politeness: Politeness = "polite"): void {
      const region = regions.get(politeness);
      if (region === undefined || win === null) return;

      const scheduled = pending.get(politeness);
      if (scheduled !== undefined) win.clearTimeout(scheduled);

      // Clear first, then set on the next task: an identical string is not a
      // change, and a change in the same task can land before the region is read.
      region.textContent = "";
      pending.set(
        politeness,
        win.setTimeout(() => {
          region.textContent = message;
          pending.delete(politeness);
        }, 0),
      );
    },
    destroy(): void {
      for (const timer of pending.values()) win?.clearTimeout(timer);
      pending.clear();
      for (const region of regions.values()) region.remove();
      regions.clear();
      announcers.delete(doc);
    },
  };

  announcers.set(doc, { announcer, regions });
  return announcer;
}

/**
 * Body scroll lock without the jump.
 *
 * Hiding the overflow removes the scrollbar, the viewport gets wider, and the
 * whole page shifts sideways behind the dialog. The width it took is given back
 * as padding, and published as `--sui-scrollbar-width` so a fixed header can
 * compensate too.
 *
 * Counted per document: a popover inside a dialog inside a drawer locks three
 * times and must unlock once, at the end.
 */

const counts = new WeakMap<Document, number>();
const restores = new WeakMap<Document, VoidFunction>();

const NOOP: VoidFunction = () => {};

function applyLock(doc: Document): VoidFunction {
  const win = doc.defaultView;
  const body = doc.body;
  const root = doc.documentElement;
  if (win === null) return NOOP;

  const scrollbarWidth = win.innerWidth - root.clientWidth;
  const previousOverflow = body.style.overflow;
  const previousPadding = body.style.paddingRight;
  const previousProperty = root.style.getPropertyValue("--sui-scrollbar-width");
  const paddingRight = win.getComputedStyle(body).paddingRight;

  root.style.setProperty("--sui-scrollbar-width", `${scrollbarWidth}px`);
  body.style.overflow = "hidden";
  if (scrollbarWidth > 0) {
    body.style.paddingRight = `calc(${paddingRight} + ${scrollbarWidth}px)`;
  }

  return () => {
    body.style.overflow = previousOverflow;
    body.style.paddingRight = previousPadding;
    if (previousProperty === "") root.style.removeProperty("--sui-scrollbar-width");
    else root.style.setProperty("--sui-scrollbar-width", previousProperty);
  };
}

export function lockScroll(doc: Document | null | undefined): VoidFunction {
  if (doc === null || doc === undefined) return NOOP;

  const count = counts.get(doc) ?? 0;
  if (count === 0) restores.set(doc, applyLock(doc));
  counts.set(doc, count + 1);

  let released = false;
  return () => {
    // Idempotent: an effect torn down twice must not unlock somebody else's lock.
    if (released) return;
    released = true;
    const current = (counts.get(doc) ?? 1) - 1;
    if (current > 0) {
      counts.set(doc, current);
      return;
    }
    counts.delete(doc);
    restores.get(doc)?.();
    restores.delete(doc);
  };
}

export function isScrollLocked(doc: Document): boolean {
  return (counts.get(doc) ?? 0) > 0;
}

/**
 * The clip-rect recipe: removed from sight, kept in the accessibility tree and in
 * the tab order. `display: none` and `visibility: hidden` would remove it from
 * both, which is the whole difference.
 *
 * Used for the label of a custom control and for the native `hiddenInput` every
 * form component carries so it associates with a `<form>` without any JS on the
 * consumer's side (CDC §4.5).
 */

import type { HTMLProps } from "../machine/prop-types";

export const visuallyHiddenStyle: Readonly<Record<string, string>> = {
  position: "absolute",
  width: "1px",
  height: "1px",
  padding: "0",
  margin: "-1px",
  overflow: "hidden",
  clip: "rect(0, 0, 0, 0)",
  "clip-path": "inset(50%)",
  "white-space": "nowrap",
  "border-width": "0",
};

export function getVisuallyHiddenProps(): HTMLProps {
  return { style: visuallyHiddenStyle };
}

/**
 * A collection read from the live DOM rather than held in a machine's context.
 *
 * Every transient composite in the library ends up wanting this: `menu` today,
 * `select`, `listbox`, `combobox`, `tree` and `menubar` next. Their items are
 * composition — the consumer writes them as children — so a machine that had to be
 * *told* about its own collection goes out of sync the first time one item is
 * rendered conditionally, and an array in context would additionally buy an
 * `isEqual` and a DOM-order sync for nothing. The roving focus and the typeahead
 * both work on the document anyway.
 *
 * The container selector is the half a bare `querySelectorAll` cannot do: a menu
 * drilled into a sheet, or a `select` inside a `menu`, nests one collection inside
 * another, and the outer machine must not adopt the inner items.
 */

import { getNextIndex, type RovingAction } from "../focus/roving-focus";

export function queryItems(
  container: HTMLElement | null | undefined,
  itemSelector: string,
  containerSelector: string,
): HTMLElement[] {
  if (container === null || container === undefined) return [];
  return [...container.querySelectorAll<HTMLElement>(itemSelector)].filter(
    (item) => item.closest(containerSelector) === container,
  );
}

/**
 * `aria-disabled` and not `disabled`: APG wants a disabled menu item or toolbar
 * button reachable, unlike a natively disabled form control, so these collections
 * never carry the native attribute. `data-disabled` is the styling twin and is
 * accepted so a consumer's own markup answers too.
 */
export function isItemDisabled(item: HTMLElement): boolean {
  return item.getAttribute("aria-disabled") === "true" || item.hasAttribute("data-disabled");
}

export function getItemValue(item: HTMLElement): string {
  return item.dataset.value ?? "";
}

/**
 * What a typeahead matches on. `data-label` first — a consumer who reserved the
 * width of a bolder weight has already written the text down — then the part that
 * holds the name, and only then the whole item, which would otherwise fold a
 * shortcut and a subtitle into the search string.
 */
export function getItemLabel(item: HTMLElement, textSelector: string): string {
  const declared = item.dataset.label;
  if (declared !== undefined) return declared;
  const text = item.querySelector(textSelector);
  return (text?.textContent ?? item.textContent ?? "").trim();
}

export function findItemByValue(
  items: readonly HTMLElement[],
  value: string | null,
): HTMLElement | null {
  if (value === null) return null;
  return items.find((item) => getItemValue(item) === value) ?? null;
}

/**
 * Where the highlight lands, disabled items stepped over. `null` when the
 * collection is empty — the caller decides whether that clears a highlight or
 * leaves it alone.
 */
export function getNextItem(
  items: readonly HTMLElement[],
  value: string | null,
  action: RovingAction,
  loop: boolean,
): HTMLElement | null {
  if (items.length === 0) return null;
  const current = items.findIndex((item) => getItemValue(item) === value);
  const next = getNextIndex(current, action, {
    count: items.length,
    loop,
    isDisabled: (index) => {
      const item = items[index];
      return item !== undefined && isItemDisabled(item);
    },
  });
  return items[next] ?? null;
}

/**
 * Two-dimensional navigation for anything laid out in a grid: a calendar month,
 * a data grid, a virtual keyboard, a colour swatch panel.
 *
 * Column wrapping is deliberately asymmetric with row wrapping. Moving right off
 * the last column continues on the next row — the reading order APG specifies for
 * a grid — while moving down off the last row stays put unless looping is on. A
 * grid that teleports vertically is disorienting; one that continues horizontally
 * is how a text cursor already behaves.
 *
 * `dir` inverts left/right here rather than in each component, the way
 * `getRovingKeyAction` already does it for a one-dimensional composite: the
 * arrow keys and the gamepad d-pad both arrive physical (`@standarx/nav`'s keymap), and the
 * mirror is spent once per composite instead of in every machine.
 */

import type { Direction } from "../types";

export type GridAction =
  | "up"
  | "down"
  | "left"
  | "right"
  | "rowStart"
  | "rowEnd"
  | "gridStart"
  | "gridEnd"
  | "pageUp"
  | "pageDown";

export interface GridOptions {
  readonly count: number;
  readonly columns: number;
  /** Rows moved by PageUp/PageDown. */
  readonly page?: number | undefined;
  readonly loop?: boolean | undefined;
  readonly isDisabled?: ((index: number) => boolean) | undefined;
}

export interface GridPosition {
  readonly row: number;
  readonly column: number;
}

export function getGridPosition(index: number, columns: number): GridPosition {
  return { row: Math.floor(index / columns), column: index % columns };
}

export function getGridIndex(position: GridPosition, columns: number): number {
  return position.row * columns + position.column;
}

export function getRowCount(count: number, columns: number): number {
  return Math.ceil(count / columns);
}

/** The lowest cell that exists in a column — the last row is usually ragged. */
function lastInColumn(column: number, count: number, columns: number): number {
  for (let row = getRowCount(count, columns) - 1; row >= 0; row--) {
    const index = getGridIndex({ row, column }, columns);
    if (index < count) return index;
  }
  return column;
}

function target(current: number, action: GridAction, options: GridOptions): number {
  const { count, columns } = options;
  const { row, column } = getGridPosition(current, columns);
  const loop = options.loop === true;
  const page = options.page ?? 1;

  switch (action) {
    case "left":
      // Reading order: off the first column continues at the end of the row above.
      return current > 0 ? current - 1 : loop ? count - 1 : current;
    case "right":
      return current < count - 1 ? current + 1 : loop ? 0 : current;
    case "up":
      if (row > 0) return current - columns;
      return loop ? lastInColumn(column, count, columns) : current;
    case "down": {
      const below = current + columns;
      if (below < count) return below;
      if (!loop) return current;
      return column;
    }
    case "rowStart":
      return getGridIndex({ row, column: 0 }, columns);
    case "rowEnd":
      return Math.min(getGridIndex({ row, column: columns - 1 }, columns), count - 1);
    case "gridStart":
      return 0;
    case "gridEnd":
      return count - 1;
    case "pageUp":
      return Math.max(current - columns * page, column);
    case "pageDown": {
      const jumped = current + columns * page;
      // Never change column to land on the ragged last row: fall back to the
      // lowest cell this column actually has.
      return jumped < count ? jumped : lastInColumn(column, count, columns);
    }
  }
}

/**
 * Disabled cells are stepped over along the direction of travel — a disabled date
 * in a calendar must not swallow the arrow key.
 */
export function getGridNextIndex(
  current: number,
  action: GridAction,
  options: GridOptions,
): number {
  const { count } = options;
  if (count <= 0) return -1;
  const disabled = (index: number): boolean => options.isDisabled?.(index) === true;
  const from = current < 0 || current >= count ? 0 : current;

  let candidate = target(from, action, options);
  const seen = new Set<number>([from]);
  while (disabled(candidate) && !seen.has(candidate)) {
    seen.add(candidate);
    const next = target(candidate, action, options);
    if (next === candidate) return from;
    candidate = next;
  }
  return disabled(candidate) ? from : candidate;
}

export interface GridKeyOptions {
  readonly ctrlKey?: boolean | undefined;
  readonly dir?: Direction | undefined;
}

export function getGridKeyAction(key: string, options: GridKeyOptions = {}): GridAction | null {
  const rtl = options.dir === "rtl";

  switch (key) {
    case "ArrowUp":
      return "up";
    case "ArrowDown":
      return "down";
    case "ArrowLeft":
      return rtl ? "right" : "left";
    case "ArrowRight":
      return rtl ? "left" : "right";
    // Home and End are bounds, not directions: the row is already laid out
    // right-to-left on screen, so mirroring them would send Home to the far end
    // of the week. Same answer `getRovingKeyAction` gives.
    case "Home":
      return options.ctrlKey === true ? "gridStart" : "rowStart";
    case "End":
      return options.ctrlKey === true ? "gridEnd" : "rowEnd";
    case "PageUp":
      return "pageUp";
    case "PageDown":
      return "pageDown";
    default:
      return null;
  }
}

/**
 * The item model behind listbox, select, combobox, menu and tree.
 *
 * A collection is immutable and framework-free: it maps between the consumer's
 * item objects and the string values a machine stores, and it answers navigation
 * questions ("what is after this, skipping the disabled ones") so that six
 * components cannot drift on the answer. `filter` returns a new collection rather
 * than mutating, which is what makes a combobox's filtered view a value the
 * machine can hold.
 *
 * Navigation reuses `getNextIndex` from roving focus on purpose: a listbox and a
 * toolbar must agree on where a wrap lands.
 */

import { getNextIndex, type RovingAction } from "../focus/roving-focus";

export interface ListCollectionOptions<T> {
  readonly items: readonly T[];
  /** Defaults to `item.value`, then the item itself when it is a string. */
  readonly itemToValue?: ((item: T) => string) | undefined;
  /** Defaults to `item.label`, then the value. */
  readonly itemToString?: ((item: T) => string) | undefined;
  readonly isItemDisabled?: ((item: T) => boolean) | undefined;
  readonly groupBy?: ((item: T) => string) | undefined;
}

export interface CollectionGroup<T> {
  readonly key: string;
  readonly items: readonly T[];
}

export interface ListCollection<T> {
  readonly items: readonly T[];
  readonly size: number;
  at(index: number): T | null;
  find(value: string | null | undefined): T | null;
  indexOf(value: string | null | undefined): number;
  getValue(item: T): string;
  getLabel(item: T): string;
  isDisabled(item: T): boolean;
  values(): string[];
  first(): string | null;
  last(): string | null;
  next(value: string | null, options?: { loop?: boolean | undefined }): string | null;
  prev(value: string | null, options?: { loop?: boolean | undefined }): string | null;
  move(
    value: string | null,
    action: RovingAction,
    options?: { loop?: boolean | undefined },
  ): string | null;
  groups(): CollectionGroup<T>[];
  filter(predicate: (item: T) => boolean): ListCollection<T>;
}

function defaultValue<T>(item: T): string {
  if (typeof item === "string") return item;
  const value = (item as { value?: unknown }).value;
  return typeof value === "string" ? value : String(value);
}

export function createListCollection<T>(options: ListCollectionOptions<T>): ListCollection<T> {
  const { items } = options;
  const getValue = options.itemToValue ?? defaultValue;
  const getLabel =
    options.itemToString ??
    ((item: T): string => {
      const label = (item as { label?: unknown }).label;
      return typeof label === "string" ? label : getValue(item);
    });
  const isDisabled = (item: T): boolean => options.isItemDisabled?.(item) === true;

  // Built once: a combobox re-reads this on every keystroke.
  const indexByValue = new Map<string, number>();
  items.forEach((item, index) => {
    const value = getValue(item);
    if (!indexByValue.has(value)) indexByValue.set(value, index);
  });

  const indexOf = (value: string | null | undefined): number =>
    value === null || value === undefined ? -1 : (indexByValue.get(value) ?? -1);

  const move = (
    value: string | null,
    action: RovingAction,
    moveOptions: { loop?: boolean | undefined } = {},
  ): string | null => {
    const from = indexOf(value);
    const next = getNextIndex(from, action, {
      count: items.length,
      loop: moveOptions.loop ?? false,
      isDisabled: (index) => {
        const item = items[index];
        return item !== undefined && isDisabled(item);
      },
    });
    // Roving focus stays put when it cannot move; a collection says so instead —
    // the machine needs to tell "no next item" from "the next item is this one".
    if (next < 0) return null;
    if (next === from && (action === "next" || action === "prev")) return null;
    const item = items[next];
    return item === undefined || isDisabled(item) ? null : getValue(item);
  };

  return {
    items,
    size: items.length,
    at: (index: number): T | null => items[index] ?? null,
    find: (value): T | null => items[indexOf(value)] ?? null,
    indexOf,
    getValue,
    getLabel,
    isDisabled,
    values: (): string[] => items.map(getValue),
    first: (): string | null => move(null, "first"),
    last: (): string | null => move(null, "last"),
    next: (value, moveOptions): string | null => move(value, "next", moveOptions ?? {}),
    prev: (value, moveOptions): string | null => move(value, "prev", moveOptions ?? {}),
    move,
    groups: (): CollectionGroup<T>[] => {
      const groupBy = options.groupBy;
      if (groupBy === undefined) return [{ key: "", items }];
      // Insertion-ordered: the author's item order decides the group order too,
      // rather than an alphabetical sort nobody asked for.
      const grouped = new Map<string, T[]>();
      for (const item of items) {
        const key = groupBy(item);
        const bucket = grouped.get(key);
        if (bucket === undefined) grouped.set(key, [item]);
        else bucket.push(item);
      }
      return [...grouped].map(([key, groupItems]) => ({ key, items: groupItems }));
    },
    filter: (predicate): ListCollection<T> =>
      createListCollection({ ...options, items: items.filter(predicate) }),
  };
}

/**
 * Selection as pure transitions on an immutable value.
 *
 * The state is `{ value, anchor }` and every operation returns a new one, which is
 * exactly what a `bindable` wants: the machine calls `context.set("selection", …)`
 * and the controlled/uncontrolled question is already answered upstream.
 *
 * The anchor is what makes shift-click behave. It is set by a plain selection and
 * left alone by a range extension, so extending twice from the same anchor
 * replaces the range instead of growing it — the behaviour of every file list on
 * every desktop.
 */

export type SelectionMode = "none" | "single" | "multiple";

export interface SelectionState {
  readonly value: readonly string[];
  readonly anchor: string | null;
}

export interface SelectionOptions {
  readonly mode: SelectionMode;
  /** Single mode: selecting the selected item clears it. Off by default — a radio never empties. */
  readonly deselectable?: boolean | undefined;
}

export const emptySelection: SelectionState = { value: [], anchor: null };

export function createSelection(
  value: readonly string[] = [],
  anchor: string | null = null,
): SelectionState {
  return { value, anchor };
}

export function isSelected(state: SelectionState, value: string): boolean {
  return state.value.includes(value);
}

/** A plain click: replaces in single mode, toggles in multiple. */
export function select(
  state: SelectionState,
  value: string,
  options: SelectionOptions,
): SelectionState {
  if (options.mode === "none") return state;
  if (options.mode === "single") {
    const already = isSelected(state, value);
    if (already && options.deselectable === true) return { value: [], anchor: null };
    return { value: [value], anchor: value };
  }
  return { value: [value], anchor: value };
}

/** Ctrl/Cmd-click, and the gamepad X button on a listbox (CDC §4.4). */
export function toggle(
  state: SelectionState,
  value: string,
  options: SelectionOptions,
): SelectionState {
  if (options.mode === "none") return state;
  if (options.mode === "single") return select(state, value, options);
  if (isSelected(state, value)) {
    const next = state.value.filter((entry) => entry !== value);
    return { value: next, anchor: next.at(-1) ?? null };
  }
  return { value: [...state.value, value], anchor: value };
}

/**
 * Shift-click. `ordered` is the collection's current value order, so a filtered
 * or reordered view selects the range the user can actually see.
 */
export function extend(
  state: SelectionState,
  value: string,
  ordered: readonly string[],
  options: SelectionOptions,
): SelectionState {
  if (options.mode !== "multiple") return select(state, value, options);

  const anchor = state.anchor ?? value;
  const from = ordered.indexOf(anchor);
  const to = ordered.indexOf(value);
  if (from === -1 || to === -1) return select(state, value, options);

  const range = ordered.slice(Math.min(from, to), Math.max(from, to) + 1);
  // The anchor survives, so extending again from the same anchor replaces the
  // range rather than accumulating.
  return { value: range, anchor };
}

export function selectAll(
  state: SelectionState,
  ordered: readonly string[],
  options: SelectionOptions,
): SelectionState {
  if (options.mode !== "multiple") return state;
  return { value: [...ordered], anchor: state.anchor };
}

export function clearSelection(): SelectionState {
  return emptySelection;
}

import { isDev } from "../utils/env";
import { warn } from "../utils/invariant";
import type { VirtualItem, VirtualRange } from "./virtualizer";

export interface VirtualIndexOptions {
  readonly count: number;
  readonly estimateSize: (index: number) => number;
  readonly paddingStart?: number | undefined;
  readonly gap?: number | undefined;
}

export interface VirtualIndex {
  readonly dirtyFrom: number;
  setCount(count: number): void;
  setSize(index: number, size: number): boolean;
  sizeOf(index: number): number;
  offsetOf(index: number): number;
  totalSize(): number;
  findIndex(offset: number): number;
  range(viewportSize: number, scrollOffset: number, overscan?: number): VirtualRange;
}

const DEFAULT_OVERSCAN = 3;

let warned = false;

export function createVirtualIndex(options: VirtualIndexOptions): VirtualIndex {
  function finite(value: number): number {
    if (Number.isFinite(value) && value >= 0) return value;
    warn(isDev() && !warned, `createVirtualIndex: ${value} is not a size, read as 0`);
    warned = true;
    return 0;
  }

  const estimateSize = (index: number): number => finite(options.estimateSize(index));
  const paddingStart = finite(options.paddingStart ?? 0);
  const gap = finite(options.gap ?? 0);

  let count = 0;
  const sizes: number[] = [];
  const starts: number[] = [paddingStart];
  let dirtyFrom = Number.POSITIVE_INFINITY;

  function setCount(next: number): void {
    const target = Math.floor(finite(next));
    if (target === count) return;
    if (target < count) {
      sizes.length = target;
      starts.length = target + 1;
      dirtyFrom = Math.min(dirtyFrom, target + 1);
    } else {
      for (let index = count; index < target; index++) sizes.push(estimateSize(index));
      dirtyFrom = Math.min(dirtyFrom, count + 1);
    }
    count = target;
  }

  function settle(): void {
    if (dirtyFrom > count) return;
    for (let index = dirtyFrom; index <= count; index++) {
      starts[index] = (starts[index - 1] ?? 0) + (sizes[index - 1] ?? 0) + gap;
    }
    dirtyFrom = Number.POSITIVE_INFINITY;
  }

  function totalSize(): number {
    if (count <= 0) return 0;
    settle();
    return (starts[count] ?? 0) - gap;
  }

  function findIndex(offset: number): number {
    if (count <= 0) return 0;
    settle();
    let low = 0;
    let high = count - 1;
    let result = count - 1;
    while (low <= high) {
      const middle = (low + high) >> 1;
      if ((starts[middle + 1] ?? 0) - gap > offset) {
        result = middle;
        high = middle - 1;
      } else {
        low = middle + 1;
      }
    }
    return result;
  }

  function lastStartBefore(limit: number, from: number): number {
    let low = from;
    let high = count - 1;
    let result = from;
    while (low <= high) {
      const middle = (low + high) >> 1;
      if ((starts[middle] ?? 0) < limit) {
        result = middle;
        low = middle + 1;
      } else {
        high = middle - 1;
      }
    }
    return result;
  }

  setCount(options.count);

  return {
    get dirtyFrom(): number {
      return dirtyFrom;
    },
    setCount,
    setSize(index, size) {
      const clean = finite(size);
      if (index < 0 || index >= count || sizes[index] === clean) return false;
      sizes[index] = clean;
      dirtyFrom = Math.min(dirtyFrom, index + 1);
      return true;
    },
    sizeOf(index) {
      return sizes[index] ?? 0;
    },
    offsetOf(index) {
      settle();
      return starts[Math.max(0, Math.min(index, count))] ?? paddingStart;
    },
    totalSize,
    findIndex,
    range(viewportSize, scrollOffset, overscan = DEFAULT_OVERSCAN): VirtualRange {
      if (count <= 0) return { startIndex: 0, endIndex: -1, totalSize: 0, items: [] };

      const total = totalSize();
      const clamped = Math.max(0, Math.min(scrollOffset, Math.max(0, total - viewportSize)));
      const firstVisible = findIndex(clamped);
      const lastVisible = lastStartBefore(clamped + viewportSize, firstVisible);

      const startIndex = Math.max(0, firstVisible - overscan);
      const endIndex = Math.min(count - 1, lastVisible + overscan);

      const items: VirtualItem[] = [];
      for (let index = startIndex; index <= endIndex; index++) {
        const start = starts[index] ?? 0;
        const size = sizes[index] ?? 0;
        items.push({ index, start, size, end: start + size });
      }
      return { startIndex, endIndex, totalSize: total, items };
    },
  };
}

/**
 * Windowed virtualisation as a capability of the collection, not a component
 * (research/components.md §2-9). It is a pure function of `{ count, scrollOffset,
 * viewportSize }` — no DOM, no observers, no scheduling — so a listbox, a tree and
 * a data grid all get the same answer and the maths is unit-testable.
 *
 * Measured sizes override estimates as rows are rendered, which is what keeps the
 * scrollbar honest with variable-height content. The caller owns that map: it
 * belongs in the machine's `refs`, where a mutation does not trigger a render.
 */

import { createVirtualIndex, type VirtualIndex } from "./virtual-index";

export interface VirtualizerOptions {
  readonly count: number;
  readonly viewportSize: number;
  readonly scrollOffset: number;
  readonly estimateSize: (index: number) => number;
  /** Real sizes for the rows that have been rendered and measured. */
  readonly measured?: ReadonlyMap<number, number> | undefined;
  /** Rows kept beyond each edge so a fast scroll does not show blanks. */
  readonly overscan?: number | undefined;
  readonly paddingStart?: number | undefined;
  readonly gap?: number | undefined;
}

export interface VirtualItem {
  readonly index: number;
  readonly start: number;
  readonly size: number;
  readonly end: number;
}

export interface VirtualRange {
  readonly startIndex: number;
  readonly endIndex: number;
  readonly totalSize: number;
  readonly items: readonly VirtualItem[];
}

function indexOf(options: VirtualizerOptions): VirtualIndex {
  const { measured, estimateSize } = options;
  return createVirtualIndex({
    count: options.count,
    estimateSize: (index) => measured?.get(index) ?? estimateSize(index),
    paddingStart: options.paddingStart,
    gap: options.gap,
  });
}

export function getVirtualRange(options: VirtualizerOptions): VirtualRange {
  return indexOf(options).range(options.viewportSize, options.scrollOffset, options.overscan);
}

export interface ScrollTargetOptions {
  readonly viewportSize: number;
  readonly scrollOffset: number;
  readonly align?: "start" | "center" | "end" | "nearest" | undefined;
}

/** Where to scroll so `index` is visible, read off a live index, or `null` when it already is. */
export function getScrollTarget(
  virtual: VirtualIndex,
  count: number,
  index: number,
  options: ScrollTargetOptions,
): number | null {
  const { viewportSize, scrollOffset } = options;
  if (index < 0 || index >= count) return null;

  const start = virtual.offsetOf(index);
  const end = start + virtual.sizeOf(index);
  const align = options.align ?? "nearest";

  if (align === "start") return start;
  if (align === "end") return end - viewportSize;
  if (align === "center") return start - (viewportSize - (end - start)) / 2;

  if (start < scrollOffset) return start;
  if (end > scrollOffset + viewportSize) return end - viewportSize;
  return null;
}

/** Where to scroll so `index` is visible, or `null` when it already is. */
export function getScrollToIndex(
  index: number,
  options: VirtualizerOptions & { align?: "start" | "center" | "end" | "nearest" },
): number | null {
  if (index < 0 || index >= options.count) return null;
  return getScrollTarget(indexOf(options), options.count, index, options);
}

/**
 * Writing a `connect` getter's output onto a real element.
 *
 * `connect` speaks plain DOM — HTML attribute names, camelCase handlers, a style
 * object — and every adapter translates that dialect once, at its own boundary.
 * React's translation is a dictionary, because JSX has other names for the same
 * things. This one is the identity dialect, so what it owns instead is the
 * *writing*: which keys are attributes, which are live properties the parser only
 * reads once, and how a repaint leaves alone the DOM it already wrote.
 *
 * That last part is not tidiness. Three machines learn about their own parts
 * through `observeChildren` / `observeAttributes`, and a mutation record is
 * emitted for a write even when the value is identical — so a repaint that
 * changed nothing has to write nothing, or the observers see churn that never
 * happened.
 *
 * It lives in the core rather than in `@standarui/vanilla` because the browser
 * test harness needs the same writer, and the core cannot import an adapter.
 */

import {
  type AnyProps,
  createNormalizer,
  type NormalizeProps,
  type PropTypes,
} from "../machine/prop-types";
import { toKebabCase } from "../utils/string";

/** The identity dialect: what `connect` emits is already what the DOM takes. */
export interface DomPropTypes extends PropTypes {
  element: Record<string, unknown>;
  a: Record<string, unknown>;
  button: Record<string, unknown>;
  input: Record<string, unknown>;
  label: Record<string, unknown>;
  output: Record<string, unknown>;
  select: Record<string, unknown>;
  textarea: Record<string, unknown>;
  img: Record<string, unknown>;
  svg: Record<string, unknown>;
  circle: Record<string, unknown>;
  path: Record<string, unknown>;
}

export const domNormalizer: NormalizeProps<DomPropTypes> = createNormalizer<DomPropTypes>(
  (props) => props,
);

/** `onDoubleClick` is the one handler whose event is not its name lowercased. */
const EVENT_NAMES: Readonly<Record<string, string>> = { onDoubleClick: "dblclick" };

/**
 * Props whose attribute is spelled differently. A table rather than a lowercase
 * pass, and SVG is why: `viewBox` is case-sensitive and would stop resolving,
 * while `strokeWidth` needs a dash no HTML attribute takes.
 */
const ATTRIBUTE_NAMES: Readonly<Record<string, string>> = {
  autoCapitalize: "autocapitalize",
  autoComplete: "autocomplete",
  contentEditable: "contenteditable",
  defaultChecked: "checked",
  defaultValue: "value",
  inputMode: "inputmode",
  maxLength: "maxlength",
  minLength: "minlength",
  readOnly: "readonly",
  spellCheck: "spellcheck",
  strokeDasharray: "stroke-dasharray",
  strokeDashoffset: "stroke-dashoffset",
  strokeLinecap: "stroke-linecap",
  strokeLinejoin: "stroke-linejoin",
  strokeWidth: "stroke-width",
  tabIndex: "tabindex",
};

/**
 * Attributes where `false` is a value and not an absence. Removing one is how
 * `draggable: false` quietly becomes `draggable="true"` again on a node whose
 * ancestor sets it.
 */
const ENUMERATED: ReadonlySet<string> = new Set([
  "contenteditable",
  "draggable",
  "focusable",
  "spellcheck",
  "translate",
]);

/**
 * Written as properties rather than attributes: the parser reads `value` and
 * `checked` once, to seed the field, and never again — so an attribute write on a
 * field somebody has already typed into changes nothing at all.
 */
const PROPERTIES: ReadonlySet<string> = new Set(["checked", "indeterminate", "value"]);

function isFormField(node: Element): boolean {
  const name = node.localName;
  return name === "input" || name === "textarea" || name === "select";
}

function writeProperty(node: Element, name: string, value: unknown): void {
  const field = node as unknown as Record<string, unknown>;
  const next =
    name === "value"
      ? value === undefined || value === null
        ? ""
        : String(value)
      : value === true;
  if (field[name] !== next) field[name] = next;
}

function writeStyle(node: Element, value: unknown, written: Set<string>): void {
  // A string is handed over whole; `connect` emits one only when it has no custom
  // properties to place, which is the case the object form exists for.
  if (typeof value === "string") {
    node.setAttribute("style", value);
    return;
  }
  if (typeof value !== "object" || value === null) return;
  const { style } = node as HTMLElement;
  if (style === undefined) return;
  for (const [property, declaration] of Object.entries(value)) {
    // Custom properties keep their dashes — they are how the core talks to the
    // styles layer, and kebab-casing one would rename it.
    const name = property.startsWith("--") ? property : toKebabCase(property);
    if (declaration === undefined || declaration === null) {
      style.removeProperty(name);
      continue;
    }
    const next = String(declaration);
    if (style.getPropertyValue(name) !== next) style.setProperty(name, next);
    written.add(name);
  }
}

function isHandlerKey(key: string): boolean {
  return key.startsWith("on") && key.length > 2 && key[2] === key[2]?.toUpperCase();
}

interface NodeState {
  /** The latest handler per event type; the installed listener reads it live. */
  readonly handlers: Map<string, EventListener>;
  /** One stable listener per event type, installed once and never re-added. */
  readonly installed: Map<string, EventListener>;
  attributes: Set<string>;
  styles: Set<string>;
}

export interface PropsWriter {
  /**
   * Applies one getter's output, removing whatever the previous pass wrote and
   * this one does not. What the consumer authored is never touched: only names
   * this writer has written are candidates for removal.
   */
  write(node: Element, props: AnyProps): void;
  /** Forgets a node and takes its listeners back off. */
  release(node: Element): void;
  destroy(): void;
}

export function createPropsWriter(): PropsWriter {
  const nodes = new Map<Element, NodeState>();

  const stateOf = (node: Element): NodeState => {
    let state = nodes.get(node);
    if (state === undefined) {
      state = {
        handlers: new Map(),
        installed: new Map(),
        attributes: new Set(),
        styles: new Set(),
      };
      nodes.set(node, state);
    }
    return state;
  };

  const setHandler = (node: Element, state: NodeState, key: string, value: unknown): void => {
    const type = EVENT_NAMES[key] ?? key.slice(2).toLowerCase();
    if (typeof value !== "function") {
      state.handlers.delete(type);
      return;
    }
    state.handlers.set(type, value as EventListener);
    if (state.installed.has(type)) return;
    // A stable dispatcher rather than the handler itself: `connect` allocates a
    // fresh closure on every read, so binding it directly would mean removing and
    // re-adding every listener on every repaint — and a listener re-added while
    // its own event is dispatching is a listener that runs twice.
    const listener: EventListener = (event: Event): void => {
      state.handlers.get(type)?.(event);
    };
    node.addEventListener(type, listener);
    state.installed.set(type, listener);
  };

  const release = (node: Element): void => {
    const state = nodes.get(node);
    if (state === undefined) return;
    for (const [type, listener] of state.installed) node.removeEventListener(type, listener);
    nodes.delete(node);
  };

  return {
    write(node: Element, props: AnyProps): void {
      const state = stateOf(node);
      const attributes = new Set<string>();
      const styles = new Set<string>();

      for (const [key, value] of Object.entries(props)) {
        if (key === "style") {
          writeStyle(node, value, styles);
          continue;
        }
        if (isHandlerKey(key)) {
          setHandler(node, state, key, value);
          continue;
        }

        const name = ATTRIBUTE_NAMES[key] ?? key;
        if (PROPERTIES.has(name) && isFormField(node)) {
          writeProperty(node, name, value);
          continue;
        }
        if (value === undefined || value === null) {
          node.removeAttribute(name);
          continue;
        }

        let serialised: string;
        if (typeof value === "boolean") {
          if (!value && !ENUMERATED.has(name)) {
            node.removeAttribute(name);
            continue;
          }
          serialised = ENUMERATED.has(name) ? String(value) : "";
        } else {
          serialised = String(value);
        }
        if (node.getAttribute(name) !== serialised) node.setAttribute(name, serialised);
        attributes.add(name);
      }

      for (const name of state.attributes) {
        if (!attributes.has(name)) node.removeAttribute(name);
      }
      const { style } = node as HTMLElement;
      if (style !== undefined) {
        for (const property of state.styles) {
          if (!styles.has(property)) style.removeProperty(property);
        }
      }
      state.attributes = attributes;
      state.styles = styles;
    },

    release,

    destroy(): void {
      for (const node of [...nodes.keys()]) release(node);
    },
  };
}

/**
 * State reaches the styles as data-attributes, never as class names — that is the
 * CSS ↔ core contract (architecture.md). `dataAttr` emits the empty string so the
 * attribute is present-or-absent, which is what `[data-disabled]` selects on;
 * `ariaAttr` emits a string so it serialises identically in every adapter and in
 * server-rendered HTML.
 */

export function dataAttr(condition: boolean | undefined): "" | undefined {
  return condition === true ? "" : undefined;
}

export function ariaAttr(condition: boolean | undefined): "true" | undefined {
  return condition === true ? "true" : undefined;
}

export function boolAttr(condition: boolean | undefined): "true" | "false" {
  return condition === true ? "true" : "false";
}

/** Sets an attribute and returns the restore, so an effect can hand back the DOM. */
export function setAttribute(node: Element, name: string, value: string): VoidFunction {
  const previous = node.getAttribute(name);
  node.setAttribute(name, value);
  return () => {
    if (previous === null) node.removeAttribute(name);
    else node.setAttribute(name, previous);
  };
}

export function setStyle(
  node: HTMLElement,
  style: Readonly<Record<string, string | undefined>>,
): VoidFunction {
  const previous = new Map<string, string>();
  for (const [property, value] of Object.entries(style)) {
    previous.set(property, node.style.getPropertyValue(property));
    if (value === undefined) node.style.removeProperty(property);
    else node.style.setProperty(property, value);
  }
  return () => {
    for (const [property, value] of previous) {
      if (value === "") node.style.removeProperty(property);
      else node.style.setProperty(property, value);
    }
  };
}

/**
 * Every listener the core installs comes back with its own teardown: an effect
 * that cannot be undone is a leak waiting for the first unmount. Global listeners
 * are added natively (and usually in capture) from inside effects, never through
 * an adapter's synthetic system — React's root delegation would otherwise let an
 * outside-click close a layer before the trigger's own handler has run
 * (research/core.md §5, piège 4).
 */

type DOMEventMap = DocumentEventMap & HTMLElementEventMap & WindowEventMap;

export function addDomEvent<K extends keyof DOMEventMap>(
  target: EventTarget | null | undefined,
  type: K,
  listener: (event: DOMEventMap[K]) => void,
  options?: AddEventListenerOptions,
): VoidFunction {
  if (target === null || target === undefined) return () => {};
  const handler = listener as EventListener;
  target.addEventListener(type, handler, options);
  return () => target.removeEventListener(type, handler, options);
}

/** IME composition: a keydown mid-composition must never reach a machine. */
export function isComposingEvent(event: KeyboardEvent): boolean {
  return event.isComposing || event.keyCode === 229;
}

export function isModifiedEvent(event: MouseEvent | KeyboardEvent): boolean {
  return event.ctrlKey || event.metaKey || event.altKey || event.shiftKey;
}

/** A left-button, unmodified press — the only kind that activates a control. */
export function isPrimaryPointer(event: PointerEvent | MouseEvent): boolean {
  return event.button === 0 && !event.ctrlKey;
}

/**
 * Observers are created inside state effects and destroyed by their teardown —
 * the core holds no element refs of its own (research/core.md §1.4). Each one is
 * built from the node's own window so an iframe or popup gets the right
 * constructor.
 */

function windowOf(node: Node): (Window & typeof globalThis) | null {
  return node.ownerDocument?.defaultView ?? null;
}

const NOOP: VoidFunction = () => {};

export function observeAttributes(
  node: Element | null | undefined,
  attributes: readonly string[],
  callback: (node: Element) => void,
): VoidFunction {
  if (node === null || node === undefined) return NOOP;
  const win = windowOf(node);
  if (win === null) return NOOP;

  const observer = new win.MutationObserver(() => callback(node));
  observer.observe(node, { attributes: true, attributeFilter: [...attributes] });
  return () => observer.disconnect();
}

export function observeChildren(
  node: Element | null | undefined,
  callback: (node: Element, records: readonly MutationRecord[]) => void,
  attributes?: readonly string[],
): VoidFunction {
  if (node === null || node === undefined) return NOOP;
  const win = windowOf(node);
  if (win === null) return NOOP;

  const observer = new win.MutationObserver((records) => callback(node, records));
  observer.observe(
    node,
    attributes === undefined
      ? { childList: true, subtree: true }
      : {
          childList: true,
          subtree: true,
          attributes: true,
          attributeFilter: [...attributes],
          attributeOldValue: true,
        },
  );
  return () => observer.disconnect();
}

export function observeResize(
  node: Element | null | undefined,
  callback: (rect: DOMRectReadOnly) => void,
): VoidFunction {
  if (node === null || node === undefined) return NOOP;
  const win = windowOf(node);
  if (win === null || !("ResizeObserver" in win)) return NOOP;

  const observer = new win.ResizeObserver((entries) => {
    const entry = entries[0];
    if (entry !== undefined) callback(entry.contentRect);
  });
  observer.observe(node);
  return () => observer.disconnect();
}

/**
 * Platform reads take a window, which is the point: they can only be called from
 * an effect, never from `connect` or `initialState`. A `navigator` sniff during
 * render is exactly how an SSR hydration mismatch is born (CDC §5.3).
 */

interface UserAgentData {
  readonly platform?: string;
  readonly brands?: readonly { readonly brand: string }[];
}

function platformOf(win: Window): string {
  const nav = win.navigator as Navigator & { userAgentData?: UserAgentData };
  return nav.userAgentData?.platform ?? nav.platform ?? "";
}

function userAgentOf(win: Window): string {
  return win.navigator.userAgent ?? "";
}

export function isMac(win: Window): boolean {
  return /^Mac/i.test(platformOf(win));
}

export function isIos(win: Window): boolean {
  // iPadOS reports as a Mac; the touch points are what give it away.
  return (
    /iPhone|iPad|iPod/i.test(platformOf(win)) || (isMac(win) && win.navigator.maxTouchPoints > 1)
  );
}

export function isApple(win: Window): boolean {
  return isMac(win) || isIos(win);
}

export function isFirefox(win: Window): boolean {
  return /firefox/i.test(userAgentOf(win));
}

export function isSafari(win: Window): boolean {
  const ua = userAgentOf(win);
  return /^((?!chrome|android).)*safari/i.test(ua);
}

/**
 * The same signal the tokens layer uses to pick the touch density, so the machine
 * and the stylesheet can never disagree about which one is active.
 */
export function isCoarsePointer(win: Window): boolean {
  return win.matchMedia("(pointer: coarse)").matches;
}

export function prefersReducedMotion(win: Window): boolean {
  return win.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export function supportsPointerEvents(win: Window): boolean {
  return "PointerEvent" in win;
}

/** `Node.DOCUMENT_POSITION_*`, named rather than imported: the core reads no DOM globals. */
export const DOCUMENT_POSITION_PRECEDING = 2;
export const DOCUMENT_POSITION_FOLLOWING = 4;

export function isHTMLElement(value: unknown): value is HTMLElement {
  return (
    typeof value === "object" &&
    value !== null &&
    (value as Node).nodeType === 1 &&
    typeof (value as HTMLElement).nodeName === "string"
  );
}

export function query<T extends Element = HTMLElement>(
  root: ParentNode | null | undefined,
  selector: string,
): T | null {
  return root?.querySelector<T>(selector) ?? null;
}

export function queryAll<T extends Element = HTMLElement>(
  root: ParentNode | null | undefined,
  selector: string,
): T[] {
  return root === null || root === undefined ? [] : [...root.querySelectorAll<T>(selector)];
}

/**
 * Shadow-aware containment. `Node.contains` stops at a shadow boundary, so a
 * popover rendered inside a web component would read as "outside" its own trigger
 * and dismiss itself on its first click.
 */
export function contains(parent: Node | null | undefined, child: Node | null | undefined): boolean {
  if (parent === null || parent === undefined || child === null || child === undefined)
    return false;
  if (parent === child || parent.contains(child)) return true;

  let node: Node | null = child;
  while (node !== null) {
    const root: Node = node.getRootNode();
    if (root === parent) return true;
    const host: Element | null = (root as ShadowRoot).host ?? null;
    if (host === null || host === node) return false;
    if (parent.contains(host)) return true;
    node = host;
  }
  return false;
}

/**
 * `composedPath()[0]`, never `event.target`: inside a shadow root the browser
 * retargets `target` to the host, which loses the element actually clicked
 * (research/core.md §5, piège 3).
 */
export function getEventTarget<T extends EventTarget = HTMLElement>(event: Event): T | null {
  const composed = event.composedPath?.();
  return (composed?.[0] as T | undefined) ?? (event.target as T | null) ?? null;
}

/**
 * Frame helpers take the window explicitly: the core never reaches for a global,
 * and a component mounted in an iframe or a popup schedules on the right clock.
 */

export function raf(win: Window, fn: VoidFunction): VoidFunction {
  const id = win.requestAnimationFrame(fn);
  return () => win.cancelAnimationFrame(id);
}

/**
 * Two frames, not one. An adapter can mount portalled content after `connect`
 * returns, so initial focus and first measurement have to wait for the frame
 * *after* the one that inserted the node (research/core.md §1.4).
 */
export function rafs(win: Window, fn: VoidFunction): VoidFunction {
  let cancelInner: VoidFunction | undefined;
  const cancelOuter = raf(win, () => {
    cancelInner = raf(win, fn);
  });
  return () => {
    cancelOuter();
    cancelInner?.();
  };
}

export function nextTick(fn: VoidFunction): VoidFunction {
  let cancelled = false;
  queueMicrotask(() => {
    if (!cancelled) fn();
  });
  return () => {
    cancelled = true;
  };
}

export function timeout(win: Window, fn: VoidFunction, ms: number): VoidFunction {
  const id = win.setTimeout(fn, ms);
  return () => win.clearTimeout(id);
}

import type { Direction } from "../types";

/**
 * What the page actually resolved around `node`. Computed, not the attribute —
 * `dir` inherits, and the nearest ancestor carrying it may be far up the tree.
 */
export function getComputedDir(node: Element | null | undefined): Direction {
  const win = node?.ownerDocument?.defaultView;
  if (node === null || node === undefined || win === null || win === undefined) return "ltr";
  return win.getComputedStyle(node).direction === "rtl" ? "rtl" : "ltr";
}

/**
 * The direction a behaviour should obey: the prop when the consumer named one,
 * otherwise whatever the page resolved around `node`.
 *
 * `dir` is a first-class machine prop (CDC §5.2) but it is deliberately *not*
 * defaulted any more. The machines used to default it to `"ltr"` and emit that
 * onto a real HTML `dir` attribute, which reset every miralabs.tech subtree nested in
 * an RTL region back to LTR — the attribute won over the inheritance it was
 * supposed to follow. With no default the attribute is omitted, the subtree
 * inherits, and the arrow keys and the positioner ask for the resolved value
 * here instead.
 *
 * Reads the DOM, so every call site sits in an effect or an event handler; on
 * the server `node` is `null` and the answer is `"ltr"`, which is what the
 * consumers already assumed when `dir` was `undefined`.
 */
export function resolveDir(
  dir: Direction | undefined,
  node: Element | null | undefined,
): Direction {
  return dir ?? getComputedDir(node);
}

export function isRtl(dir: Direction | undefined): boolean {
  return dir === "rtl";
}

/**
 * Left/right are logical, not physical. Every arrow-key handler resolves through
 * this so RTL is decided once instead of in every component.
 */
export function resolveDirection(direction: "start" | "end", dir: Direction): "left" | "right" {
  const rtl = isRtl(dir);
  if (direction === "start") return rtl ? "right" : "left";
  return rtl ? "left" : "right";
}

/**
 * `{ dir, locale, density, reducedMotion }` — the context that decides
 * presentation switches (research/components.md §3): a menu that hovers open on
 * desktop and only opens on tap in touch, a select that becomes a sheet.
 *
 * Attributes win over media queries, and that is the whole point. The styles
 * layer resolves density from `[data-sui-density]` first and `(pointer: coarse)`
 * second; if the core asked the media query directly, an app that pins itself to
 * `desktop` would get touch behaviour with desktop styling. One resolution order,
 * shared.
 */

import { isCoarsePointer, prefersReducedMotion } from "../dom/platform";
import { getComputedDir } from "../dom/text-dir";
import type { Density, Direction, EnvironmentContext, MotionMode } from "../types";

export interface EnvironmentOverrides {
  readonly dir?: Direction | undefined;
  readonly locale?: string | undefined;
  readonly density?: Density | undefined;
  readonly motion?: MotionMode | undefined;
  /** Shorthand for `motion: "reduced" | "full"`. `motion` wins when both are set. */
  readonly reducedMotion?: boolean | undefined;
}

export const defaultEnvironment: EnvironmentContext = {
  dir: "ltr",
  locale: "en-US",
  density: "desktop",
  motion: "full",
  reducedMotion: false,
};

function toMotion(value: string | null): MotionMode | null {
  return value === "full" || value === "reduced" || value === "none" ? value : null;
}

/**
 * Overrides, then the attribute, then the media query — the order this whole
 * module resolves in, and the one `_tokens.scss` keeps too, where an explicit
 * `data-motion="full"` vetoes `prefers-reduced-motion`.
 *
 * An unrecognised `data-motion` is not a mode: it falls through to the query
 * rather than being read as "reduced", so a typo cannot quietly slow an app down.
 */
function resolveMotion(
  attribute: string | null,
  overrides: EnvironmentOverrides,
  prefersReduced: boolean,
): MotionMode {
  if (overrides.motion !== undefined) return overrides.motion;
  if (overrides.reducedMotion !== undefined) return overrides.reducedMotion ? "reduced" : "full";
  const declared = toMotion(attribute);
  if (declared !== null) return declared;
  return prefersReduced ? "reduced" : "full";
}

function closestAttribute(node: Element | null | undefined, attribute: string): string | null {
  return node?.closest(`[${attribute}]`)?.getAttribute(attribute) ?? null;
}

export function resolveEnvironment(
  node: HTMLElement | null | undefined,
  overrides: EnvironmentOverrides = {},
): EnvironmentContext {
  const win = node?.ownerDocument.defaultView;
  if (node == null || win === null || win === undefined) {
    // The SSR path: overrides only, never a platform read.
    const motion = resolveMotion(null, overrides, false);
    return {
      dir: overrides.dir ?? defaultEnvironment.dir,
      locale: overrides.locale ?? defaultEnvironment.locale,
      density: overrides.density ?? defaultEnvironment.density,
      motion,
      reducedMotion: motion !== "full",
    };
  }

  const density = closestAttribute(node, "data-sui-density");
  const locale = closestAttribute(node, "lang");
  const motion = resolveMotion(
    closestAttribute(node, "data-motion"),
    overrides,
    prefersReducedMotion(win),
  );

  return {
    dir: overrides.dir ?? getComputedDir(node),
    locale: overrides.locale ?? locale ?? win.navigator.language ?? defaultEnvironment.locale,
    density:
      overrides.density ??
      (density === "touch" || density === "desktop"
        ? density
        : isCoarsePointer(win)
          ? "touch"
          : "desktop"),
    motion,
    reducedMotion: motion !== "full",
  };
}

export interface TrackEnvironmentOptions extends EnvironmentOverrides {
  onChange(environment: EnvironmentContext): void;
}

/**
 * Watches both sources — the media queries and the attributes an app can flip at
 * runtime — and reports only when the resolved value actually differs.
 */
export function trackEnvironment(
  node: HTMLElement | null | undefined,
  options: TrackEnvironmentOptions,
): VoidFunction {
  const win = node?.ownerDocument.defaultView;
  if (node == null || win === null || win === undefined) return () => {};

  const { onChange, ...overrides } = options;
  let current = resolveEnvironment(node, overrides);

  const update = (): void => {
    const next = resolveEnvironment(node, overrides);
    if (
      next.dir === current.dir &&
      next.locale === current.locale &&
      next.density === current.density &&
      // `motion` and not `reducedMotion`: the boolean cannot see a switch from
      // "reduced" to "none", which is exactly the switch that changes whether an
      // exit animation exists at all.
      next.motion === current.motion
    ) {
      return;
    }
    current = next;
    onChange(next);
  };

  return subscribe(node.ownerDocument, win, update);
}

interface EnvironmentHub {
  readonly listeners: Set<VoidFunction>;
  readonly stop: VoidFunction;
}

const hubs = new WeakMap<Document, EnvironmentHub>();

// One observer and one pair of queries per document, whatever the number of
// instances: a list of a thousand selects would otherwise hold a thousand of each.
function subscribe(
  doc: Document,
  win: Window & typeof globalThis,
  listener: VoidFunction,
): VoidFunction {
  let hub = hubs.get(doc);
  if (hub === undefined) {
    const listeners = new Set<VoidFunction>();
    const notify = (): void => {
      for (const each of [...listeners]) each();
    };
    const queries = [
      win.matchMedia("(pointer: coarse)"),
      win.matchMedia("(prefers-reduced-motion: reduce)"),
    ];
    for (const query of queries) query.addEventListener("change", notify);
    const observer = new win.MutationObserver(notify);
    observer.observe(doc.documentElement, {
      attributes: true,
      subtree: true,
      attributeFilter: ["data-sui-density", "data-motion", "dir", "lang"],
    });
    hub = {
      listeners,
      stop: () => {
        for (const query of queries) query.removeEventListener("change", notify);
        observer.disconnect();
      },
    };
    hubs.set(doc, hub);
  }
  const current = hub;
  current.listeners.add(listener);
  return () => {
    if (!current.listeners.delete(listener) || current.listeners.size > 0) return;
    current.stop();
    if (hubs.get(doc) === current) hubs.delete(doc);
  };
}

/**
 * Focus trap without sentinel nodes.
 *
 * The usual implementation injects two tabbable spans around the container. They
 * work, and they also break `:first-child` styling, show up in the accessibility
 * tree of some screen readers, and get stripped by frameworks that reconcile
 * children. Intercepting Tab in capture is fewer moving parts and leaves the DOM
 * the author wrote intact.
 *
 * Traps nest: only the last one activated reacts, so a popover inside a dialog
 * traps within the popover and hands control back on close.
 */

import { addDomEvent, isComposingEvent } from "../dom/event";
import { contains, DOCUMENT_POSITION_FOLLOWING, DOCUMENT_POSITION_PRECEDING } from "../dom/query";
import { rafs } from "../dom/raf";
import { focusElement, getTabbableEdges, getTabbables } from "../nav";
import { restoreFocus } from "./restore-focus";
import { holdTab, isClaimedTab } from "./tab-handoff";

export interface FocusTrapOptions {
  /** Where focus goes on activation. Defaults to the first tabbable, then the container. */
  readonly initialFocus?: (() => HTMLElement | null | undefined) | undefined;
  /** Where focus returns on teardown. Defaults to whatever had it before. */
  readonly finalFocus?: (() => HTMLElement | null | undefined) | undefined;
  readonly loop?: boolean | undefined;
  readonly restoreFocus?: boolean | undefined;
  readonly isDisabled?: (() => boolean) | undefined;
  /**
   * Widens "inside" past the container's DOM subtree — a menu portalled out of a
   * dialog is not a descendant of it, and is still part of it. Focus that this
   * accepts is neither pulled back nor taken on activation. A Tab from it whose
   * native step stays in the child layer is left to the browser, unless a
   * handler moves the focus back into the surface first; any other is prevented
   * in capture. Either way, once the child layer has answered, the trap moves
   * the focus one stop on from wherever that left it — unless the layer placed
   * it itself through `proxyTabFocus`.
   *
   * One limit: the first case is only seen in the bubble phase. A handler that
   * moves the focus back into the surface and also stops the propagation leaves
   * the trap nothing to answer, and the browser steps on from the surface.
   */
  readonly owns?: ((target: Node | null) => boolean) | undefined;
}

const NOOP: VoidFunction = () => {};
const active = new WeakMap<Document, HTMLElement[]>();

function activeTraps(doc: Document): HTMLElement[] {
  const existing = active.get(doc);
  if (existing !== undefined) return existing;
  const created: HTMLElement[] = [];
  active.set(doc, created);
  return created;
}

export function trapFocus(
  node: HTMLElement | null | undefined,
  options: FocusTrapOptions = {},
): VoidFunction {
  const doc = node?.ownerDocument;
  const win = doc?.defaultView;
  if (
    node === null ||
    node === undefined ||
    doc === undefined ||
    win === null ||
    win === undefined
  ) {
    return NOOP;
  }

  const traps = activeTraps(doc);
  traps.push(node);
  const restoreTo =
    options.restoreFocus === false ? null : (doc.activeElement as HTMLElement | null);
  const enabled = (): boolean => options.isDisabled?.() !== true && traps.at(-1) === node;
  const inChildLayer = (target: Node | null): boolean =>
    !contains(node, target) && options.owns?.(target) === true;
  const isInside = (target: Node | null): boolean => contains(node, target) || inChildLayer(target);

  // Two frames: an adapter can portal the content in after `connect` returns, so
  // the first tabbable may not exist yet (research/core.md §1.4).
  const cancelInitial = rafs(win, () => {
    if (!enabled()) return;
    if (inChildLayer(doc.activeElement)) return;
    const target = options.initialFocus?.() ?? getTabbableEdges(node)[0] ?? node;
    if (target === node && !node.hasAttribute("tabindex")) node.setAttribute("tabindex", "-1");
    focusElement(target);
  });

  let linkStep: {
    readonly event: KeyboardEvent;
    readonly from: Element;
    readonly link: HTMLElement;
  } | null = null;

  const linkAfter = (
    tabbables: readonly HTMLElement[],
    from: Element | null,
    backward: boolean,
  ): HTMLElement | undefined => {
    const index = tabbables.indexOf(from as HTMLElement);
    const neighbour = index === -1 ? undefined : tabbables[index + (backward ? -1 : 1)];
    return neighbour?.matches("a[href], area[href]") === true ? neighbour : undefined;
  };

  const holdAtEdge = (event: KeyboardEvent, current: Element | null): void => {
    const tabbables = getTabbables(node);
    if (tabbables.length === 0) {
      // Nothing to move to: hold focus on the container rather than let it escape.
      event.preventDefault();
      focusElement(node);
      return;
    }

    const first = tabbables[0] as HTMLElement;
    const last = tabbables.at(-1) as HTMLElement;

    if (!contains(node, current)) {
      event.preventDefault();
      focusElement(event.shiftKey ? last : first);
      return;
    }

    // WebKit leaves links out of its own Tab sequence unless the system asks for
    // them, so its step from a control can cross a link and then leave the
    // surface. When the next stop here is a link, the step is taken instead, but
    // in the bubble phase and only if nothing answered the key and the focus did
    // not move, so a control that handles its own Tab keeps it. A handler that
    // stops the propagation leaves the browser's step as it is, and in WebKit that
    // step can leave the surface.
    const link = linkAfter(tabbables, current, event.shiftKey);
    if (link !== undefined) {
      linkStep = { event, from: current as Element, link };
      return;
    }

    if (options.loop === false) return;
    if (!event.shiftKey && current === last) {
      event.preventDefault();
      focusElement(first);
    } else if (event.shiftKey && current === first) {
      event.preventDefault();
      focusElement(last);
    }
  };

  /**
   * Whether the browser's own Tab from `from` stays in a child layer. Landing in
   * the surface does not count: from a portal, the browser lands on the surface's
   * edge and not after the element the layer was opened from.
   */
  const nativeStepStaysInChild = (from: Element, backward: boolean): boolean => {
    const mask = backward ? DOCUMENT_POSITION_PRECEDING : DOCUMENT_POSITION_FOLLOWING;
    const candidates = getTabbables(doc.body).filter(
      (candidate) => (from.compareDocumentPosition(candidate) & mask) !== 0,
    );
    const next = backward ? candidates.at(-1) : candidates[0];
    return next !== undefined && inChildLayer(next);
  };

  /**
   * Moves the focus one stop on from wherever it is now: from a stop of the
   * surface to its neighbour, wrapping unless `loop` is off, and from anywhere
   * else to the surface's edge.
   */
  const stepOn = (backward: boolean): void => {
    const tabbables = getTabbables(node);
    const edge = (backward ? tabbables.at(-1) : tabbables[0]) ?? node;
    const index = tabbables.indexOf(doc.activeElement as HTMLElement);
    if (index === -1) {
      focusElement(edge);
      return;
    }
    const next = tabbables[index + (backward ? -1 : 1)];
    if (next !== undefined) focusElement(next);
    else if (options.loop !== false) focusElement(edge);
  };

  // A Tab held from a child layer, waiting for that layer to answer it — a menu
  // closes and hands the focus back to its trigger, a proxy places it past its
  // anchor — before the trap decides where the focus goes.
  let pending: {
    readonly event: KeyboardEvent;
    readonly held: boolean;
    readonly cancel: VoidFunction;
  } | null = null;

  const settle = (event: KeyboardEvent, fromBubble: boolean): void => {
    if (pending?.event !== event) return;
    const { held, cancel } = pending;
    cancel();
    pending = null;
    if (!enabled() || isClaimedTab(event)) return;
    const backward = event.shiftKey;
    if (!held) {
      // Left to the browser in capture, whose step stayed in the child layer —
      // unless a handler since moved the focus out of it, back into the surface.
      if (!fromBubble || event.defaultPrevented || inChildLayer(doc.activeElement)) return;
      event.preventDefault();
      stepOn(backward);
      return;
    }
    if (fromBubble && inChildLayer(doc.activeElement)) {
      // A child layer that closes on Tab can only hand the focus back once its
      // framework flushes, and under Playwright's Firefox React's flush lands
      // after the whole dispatch rather than between listeners. A microtask
      // queued now runs behind it.
      void Promise.resolve().then(() => {
        if (enabled()) stepOn(backward);
      });
      return;
    }
    stepOn(backward);
  };

  const onKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== "Tab" || event.defaultPrevented || !enabled()) return;
    if (event.ctrlKey || event.altKey || event.metaKey || isComposingEvent(event)) return;
    const current = doc.activeElement;
    if (!inChildLayer(current)) {
      holdAtEdge(event, current);
      return;
    }
    if (current !== null && nativeStepStaysInChild(current, event.shiftKey)) {
      pending = { event, held: false, cancel: NOOP };
      return;
    }
    // Prevented here, in capture: a listener further down may stop the event
    // before any bubble-phase check sees it, and the browser's own step from a
    // portal leaves the modal. The bubble listener settles it once the child
    // layer has answered; the task is for when nothing let it get that far.
    holdTab(event);
    const timer = win.setTimeout(() => settle(event, false), 0);
    pending = { event, held: true, cancel: () => win.clearTimeout(timer) };
  };

  const onKeyDownSettled = (event: KeyboardEvent): void => {
    settle(event, true);
    if (linkStep?.event !== event) return;
    const { from, link } = linkStep;
    linkStep = null;
    if (event.defaultPrevented || !enabled() || doc.activeElement !== from) return;
    if (linkAfter(getTabbables(node), from, event.shiftKey) !== link) return;
    event.preventDefault();
    focusElement(link);
  };

  // Focus can also arrive from outside the keyboard — a click on the page behind,
  // or a screen reader moving the virtual cursor.
  const onFocusIn = (event: FocusEvent): void => {
    if (!enabled()) return;
    const target = event.target as HTMLElement | null;
    if (isInside(target)) return;
    focusElement(getTabbableEdges(node)[0] ?? node);
  };

  const disposers = [
    addDomEvent(doc, "keydown", onKeyDown, { capture: true }),
    addDomEvent(win, "keydown", onKeyDownSettled),
    addDomEvent(doc, "focusin", onFocusIn, { capture: true }),
  ];

  return () => {
    cancelInitial();
    pending?.cancel();
    pending = null;
    for (let index = disposers.length - 1; index >= 0; index--) disposers[index]?.();
    const position = traps.lastIndexOf(node);
    if (position !== -1) traps.splice(position, 1);
    const target = options.finalFocus?.() ?? restoreTo;
    // Only restore what is still in the document: the element that opened the
    // layer may have been unmounted with it.
    if (target != null && contains(doc, target)) restoreFocus(target, node);
  };
}

/**
 * Tab through a portal as if it were still where the author wrote it.
 *
 * A non-modal popover portalled to `<body>` is last in the DOM, so tabbing out of
 * it lands wherever the document ends instead of after its trigger. This restores
 * the visual order: forward out of the content goes to the element after the
 * trigger, backward goes to the trigger itself.
 *
 * A modal surface has no "after the trigger" while the rest of the page is
 * inert. One whose Tab also closes it passes `placeOnDispose`: while its trigger
 * is inert the key is held, and the step is placed by the disposer, once the
 * inert layer is released. Without `placeOnDispose`, a surface that says it is
 * modal (`aria-modal="true"`) wraps instead, while its trigger is inert: from
 * the last stop to the first, and back.
 *
 * A menu's submenus are portalled apart from it, so the tree is read from the
 * layer stack: the root answers Tab for every open submenu, a submenu for none.
 */

import { addDomEvent, isComposingEvent } from "../dom/event";
import { contains, DOCUMENT_POSITION_FOLLOWING, DOCUMENT_POSITION_PRECEDING } from "../dom/query";
import { getLayerStack } from "../interaction/layer-stack";
import { FOCUSABLE_SELECTOR, focusElement, getTabbables } from "../nav";
import { claimTab, isHeldTab } from "./tab-handoff";

export interface ProxyTabFocusOptions {
  readonly triggerNode: () => HTMLElement | null | undefined;
  readonly onFocusOut?: ((target: HTMLElement | null) => void) | undefined;
  readonly isDisabled?: (() => boolean) | undefined;
  /**
   * Hold the step until the disposer runs instead of placing it on the key,
   * whenever the trigger is inert. For a modal surface whose Tab also closes it:
   * while open, everything after the trigger — and the trigger itself — is
   * inert, so the step can only be placed once the layer that made them inert
   * has been released.
   *
   * Read at dispose: the step is placed only when it answers yes, so a teardown
   * that keeps the surface open, or a close the Tab did not cause, places
   * nothing. Any later keydown or click drops the held step, and so does any
   * dismissal a layer asks for since (`LayerStack.dismissals`): an Escape or a
   * press outside closes the surface from a document listener that runs before
   * this one, and a pad's B has no DOM event at all. A close that comes
   * later with no input in between cannot be told from a close accepted late,
   * so it places the step too. When the close is refused the Tab is swallowed
   * and the focus stays inside — unlike the non-modal path, which lets it
   * leave; with the page inert there is nowhere to go.
   */
  readonly placeOnDispose?: (() => boolean) | undefined;
}

const NOOP: VoidFunction = () => {};

export function proxyTabFocus(
  node: HTMLElement | null | undefined,
  options: ProxyTabFocusOptions,
): VoidFunction {
  const doc = node?.ownerDocument;
  if (node === null || node === undefined || doc === undefined) return NOOP;

  let held: "forward" | "backward" | null = null;
  // The stack's dismissal count when the step was held: any dismissal since —
  // Escape, a pad's B, a press outside — closed the surface for another reason.
  let heldAt = 0;

  // A menu tree answers Tab at its root, read from the layer stack: a submenu's
  // anchor is an item that goes with the tree, and the focus in any open submenu
  // is on the root's edge. `null` for a submenu, which leaves the key to the root.
  const stack = getLayerStack(doc);
  const getTree = (): Node[] | null => {
    const own = stack.layers().find((layer) => layer.node === node);
    if (own?.type !== "menu") return [node];
    if (stack.get(own.parentId ?? "")?.type === "menu") return null;
    return [
      node,
      ...stack
        .descendantsOf(own.id)
        .filter((layer) => layer.type === "menu")
        .map((layer) => layer.node),
    ];
  };
  const inside = (tree: readonly Node[], target: Node | null): boolean =>
    tree.some((part) => contains(part, target));

  const placeHeld = (): void => {
    const direction = held;
    held = null;
    if (direction === null || heldAt !== stack.dismissals) return;
    if (options.placeOnDispose?.() !== true) return;
    const tree = getTree() ?? [node];
    const current = doc.activeElement as HTMLElement | null;
    if (current !== null && current !== doc.body && !inside(tree, current)) return;
    const trigger = options.triggerNode() ?? null;
    if (trigger === null || !trigger.isConnected) return;
    const reachable = trigger.matches(FOCUSABLE_SELECTOR) ? trigger : null;
    const target =
      direction === "backward"
        ? reachable
        : (getTabbables(doc.body).find(
            (candidate) =>
              (trigger.compareDocumentPosition(candidate) & DOCUMENT_POSITION_FOLLOWING) !== 0 &&
              !inside(tree, candidate),
          ) ?? reachable);
    if (target === null) return;
    focusElement(target);
    options.onFocusOut?.(target);
  };

  const onKeyDown = (event: KeyboardEvent): void => {
    held = null;
    if (event.key !== "Tab" || options.isDisabled?.() === true) return;
    if (event.ctrlKey || event.altKey || event.metaKey || isComposingEvent(event)) return;
    // A trap that owns this layer has already prevented the key so that nothing
    // can carry it out of the modal; the step is still this module's to place.
    if (event.defaultPrevented && !isHeldTab(event)) return;

    const current = doc.activeElement as HTMLElement | null;
    const tree = getTree();
    if (tree === null || !inside(tree, current)) return;
    const trigger = options.triggerNode() ?? null;
    const inert = (trigger?.closest("[inert]") ?? null) !== null;

    // Held only while the trigger is inert: anywhere else the step is placed now.
    if (options.placeOnDispose !== undefined && inert) {
      event.preventDefault();
      claimTab(event);
      held = event.shiftKey ? "backward" : "forward";
      heldAt = stack.dismissals;
      return;
    }

    const tabbables = getTabbables(node);
    const first = tabbables[0] ?? null;
    const last = tabbables.at(-1) ?? null;

    // A trigger inert under any other layer, or in a region the consumer made
    // inert, still steps past: only a modal surface owns the inert page.
    if (inert && node.getAttribute("aria-modal") === "true") {
      if (current !== (event.shiftKey ? first : last)) return;
      event.preventDefault();
      claimTab(event);
      focusElement(event.shiftKey ? last : first);
      return;
    }
    if (trigger === null) return;

    // A popover opened from a store hands over its anchor, which can be a plain
    // box that focusing does nothing to: the step then goes to its tabbable
    // neighbour, and with none the key is left alone rather than swallowed. Read
    // from the selector, not from `isFocusable`, which also answers no for a
    // trigger a modal layer has made inert — and the focus returns there on close.
    const reachable = trigger.matches(FOCUSABLE_SELECTOR) ? trigger : null;

    // The document order the author sees, skipping anything that lives inside
    // the portalled content. Ordered by document position and not by index in
    // the list: an anchor that is only programmatically focusable — a context
    // menu's region, which carries `tabindex="-1"` — is filtered out of
    // `getTabbables`, so `indexOf` returned -1 and `slice(0)` handed back the
    // whole document. Tab then landed on the first tabbable of the page instead
    // of on the one after the anchor.
    const outside = (mask: number): HTMLElement[] =>
      getTabbables(doc.body).filter(
        (candidate) =>
          (trigger.compareDocumentPosition(candidate) & mask) !== 0 && !inside(tree, candidate),
      );

    const nested = !contains(node, current);

    if (event.shiftKey && (current === first || nested)) {
      const target = reachable ?? outside(DOCUMENT_POSITION_PRECEDING).at(-1) ?? null;
      if (target === null) return;
      event.preventDefault();
      claimTab(event);
      focusElement(target);
      options.onFocusOut?.(target);
      return;
    }

    if (!event.shiftKey && (current === last || nested)) {
      const next = outside(DOCUMENT_POSITION_FOLLOWING)[0] ?? null;
      if (next === null && reachable === null) return;
      event.preventDefault();
      claimTab(event);
      focusElement(next ?? reachable);
      options.onFocusOut?.(next);
    }
  };

  const remove = addDomEvent(doc, "keydown", onKeyDown, { capture: true });
  if (options.placeOnDispose === undefined) return remove;
  const removeClick = addDomEvent(
    doc,
    "click",
    () => {
      held = null;
    },
    { capture: true },
  );
  return () => {
    remove();
    removeClick();
    placeHeld();
  };
}

/**
 * Hands the focus back when a layer closes.
 *
 * The element the focus goes back to can have stopped taking it while the layer
 * was open: a picker disabled while open (decision 61) has a `disabled` trigger,
 * and focusing it is a silent no-op. The focus then stays in the content, which
 * unmounts and takes it down to `body` (R58). So the browser is asked, not a
 * selector: when the focus did not land, it goes to the tab stop after the
 * target in the document, else the one before, never one inside the layer that
 * is closing. A target no longer in the document is left alone, as before.
 *
 * The fallback reads the document, not a shadow root: inside one, the guard sees
 * the host and the tab stops stay out of reach, so it never runs there.
 */

import { contains, DOCUMENT_POSITION_FOLLOWING, DOCUMENT_POSITION_PRECEDING } from "../dom/query";
import { focusElement, getTabbables } from "../nav";

export function restoreFocus(
  target: HTMLElement | null | undefined,
  leaving?: Node | null | undefined,
): void {
  if (target?.isConnected !== true) return;
  focusElement(target);
  // The root's own answer, not `:focus`, which an unfocused window can withhold.
  if ((target.getRootNode() as Document | ShadowRoot).activeElement === target) return;
  // A focus that already left the layer was put there by someone: left alone.
  const doc = target.ownerDocument;
  if (focusWentElsewhere(doc, leaving, doc.activeElement)) return;
  // Never inside the target either: `body` as a target is no trigger to stand in for.
  const stops = getTabbables(doc).filter(
    (node) => !contains(leaving, node) && !contains(target, node),
  );
  const at =
    (mask: number) =>
    (node: HTMLElement): boolean =>
      (target.compareDocumentPosition(node) & mask) !== 0;
  const fallback =
    stops.find(at(DOCUMENT_POSITION_FOLLOWING)) ?? stops.findLast(at(DOCUMENT_POSITION_PRECEDING));
  if (fallback !== undefined) focusElement(fallback);
}

/**
 * The focus left `leaving` for an element someone chose: not `body`, which is
 * nowhere, and not `active` inside `leaving`. "Nowhere" is read on the document:
 * a shadow root answers `null` for a focus anywhere outside it. `active` is the
 * caller's, so a layer inside a shadow root can pass the root's own answer.
 */
export function focusWentElsewhere(
  doc: Document,
  leaving: Node | null | undefined,
  active: Element | null,
): boolean {
  return doc.activeElement !== null && doc.activeElement !== doc.body && !contains(leaving, active);
}

/**
 * Roving tabindex: one stop in the tab order for the whole composite, arrows to
 * move inside it. Shared by radio-group, toolbar, toggle-group, tabs, menu and
 * listbox — the arithmetic is here so every one of them agrees on what Home does
 * and where a wrap lands.
 *
 * Pure, and that is the point: the arrow keys and the gamepad d-pad resolve to the
 * same `RovingAction` (CDC D9), so the machines never learn which one moved.
 * `dir` inverts left/right here rather than in each component.
 */

import type { Direction, NavigationIntent, Orientation } from "../types";

export type RovingAction = "next" | "prev" | "first" | "last";

export interface RovingOptions {
  readonly count: number;
  readonly loop?: boolean | undefined;
  readonly isDisabled?: ((index: number) => boolean) | undefined;
}

export interface RovingKeyOptions {
  readonly orientation?: Orientation | undefined;
  readonly dir?: Direction | undefined;
  /** Both axes move, whatever the orientation — grids and the d-pad. */
  readonly bothAxes?: boolean | undefined;
}

export function getRovingKeyAction(
  key: string,
  options: RovingKeyOptions = {},
): RovingAction | null {
  const orientation = options.orientation ?? "vertical";
  const rtl = options.dir === "rtl";
  const horizontal = options.bothAxes === true || orientation === "horizontal";
  const vertical = options.bothAxes === true || orientation === "vertical";

  switch (key) {
    case "ArrowDown":
      return vertical ? "next" : null;
    case "ArrowUp":
      return vertical ? "prev" : null;
    case "ArrowRight":
      return horizontal ? (rtl ? "prev" : "next") : null;
    case "ArrowLeft":
      return horizontal ? (rtl ? "next" : "prev") : null;
    case "Home":
      return "first";
    case "End":
      return "last";
    default:
      return null;
  }
}

/** The intents that move a highlight, expressed as the keys they are twins of. */
const INTENT_KEYS: Readonly<Record<string, string>> = {
  moveUp: "ArrowUp",
  moveDown: "ArrowDown",
  moveLeft: "ArrowLeft",
  moveRight: "ArrowRight",
  home: "Home",
  end: "End",
};

/**
 * The same resolution, entered from a pad instead of a keyboard — the half that
 * makes the promise above true. It lives here and not in each machine because
 * two copies of this mirror are two chances for one of them to answer `next`
 * where the other answers `null`, which is precisely how a d-pad stops behaving
 * like the arrows it is supposed to be indistinguishable from.
 */
export function getRovingIntentAction(
  intent: NavigationIntent,
  options: RovingKeyOptions = {},
): RovingAction | null {
  const key = INTENT_KEYS[intent];
  return key === undefined ? null : getRovingKeyAction(key, options);
}

/**
 * Returns the index to move to, or the current one when the move is impossible.
 * Disabled items are stepped over — never focused and never left as the answer.
 */
export function getNextIndex(
  current: number,
  action: RovingAction,
  options: RovingOptions,
): number {
  const { count } = options;
  if (count <= 0) return -1;
  const loop = options.loop ?? true;
  const disabled = (index: number): boolean => options.isDisabled?.(index) === true;

  const scan = (from: number, step: number): number => {
    for (let offset = 1; offset <= count; offset++) {
      let index = from + step * offset;
      if (index < 0 || index >= count) {
        if (!loop) return from >= 0 && from < count ? from : -1;
        index = ((index % count) + count) % count;
      }
      if (!disabled(index)) return index;
    }
    return from;
  };

  const first = (): number => (disabled(0) ? scan(0, 1) : 0);
  const last = (): number => (disabled(count - 1) ? scan(count - 1, -1) : count - 1);
  // Outside the collection — nothing focused yet, or an index left over from a
  // shorter list. Entering forward lands on the first item, backward on the last.
  const outside = current < 0 || current >= count;

  switch (action) {
    case "next":
      return outside ? first() : scan(current, 1);
    case "prev":
      return outside ? last() : scan(current, -1);
    case "first":
      return first();
    case "last":
      return last();
  }
}

/** Exactly one item is in the tab order; everything else is reachable by arrow. */
export function getRovingTabIndex(index: number, activeIndex: number): 0 | -1 {
  return index === activeIndex ? 0 : -1;
}

/** The first enabled index — where a composite starts before anything is chosen. */
export function getInitialIndex(options: RovingOptions): number {
  for (let index = 0; index < options.count; index++) {
    if (options.isDisabled?.(index) !== true) return index;
  }
  return -1;
}

/**
 * Where the focus goes when the item at `index` is removed: the next enabled one,
 * and the previous one when there is no next (APG). `-1` when it was the only item
 * there was.
 *
 * Read against the collection as it stands *before* the removal, which is the only
 * state a machine can see — the consumer owns the removal itself.
 */
export function getRemovalIndex(index: number, options: RovingOptions): number {
  const bounded = { ...options, loop: false };
  // `getNextIndex` answers with the index it started from when a non-looping move
  // has nowhere to go, which is exactly the "no next item" signal wanted here.
  const forward = getNextIndex(index, "next", bounded);
  if (forward !== index && forward !== -1) return forward;
  const back = getNextIndex(index, "prev", bounded);
  return back === index ? -1 : back;
}

/**
 * The handshake between a modal surface's focus trap and the child layers it
 * owns, for one Tab.
 *
 * The trap prevents a Tab that would carry the focus out of both in capture,
 * before any listener can stop the event from reaching it — and a prevented
 * event is one `proxyTabFocus` otherwise leaves alone. So the trap marks the
 * prevention as its own, and a child layer that then places the focus itself
 * claims the key, which tells the trap not to step on a second time.
 */

const held = new WeakSet<Event>();
const claimed = new WeakSet<Event>();

export function holdTab(event: KeyboardEvent): void {
  held.add(event);
  event.preventDefault();
}

export function isHeldTab(event: KeyboardEvent): boolean {
  return held.has(event);
}

export function claimTab(event: KeyboardEvent): void {
  claimed.add(event);
}

export function isClaimedTab(event: KeyboardEvent): boolean {
  return claimed.has(event);
}

/**
 * The release half of a gesture: carrying a surface from where the finger left it
 * to where it belongs, at a speed that matches how it was thrown.
 *
 * Opt-in, behind `@standarui/core/gesture`, because this is the only WAAPI in the
 * library besides `focus-ring` and a consumer who never drags anything should not
 * download it (motion.md §3.3). `interaction/drag-axis` is its other half and has
 * no dependency on it — a component that pages rather than settles takes the
 * tracking alone.
 *
 * **No physics at runtime.** Three precalculated (duration, easing) pairs are
 * perceptually enough (motion.md §2.5), and a spring integrator in JS is the kind
 * of dependency this repo writes by hand or does without.
 *
 * **No curve is written here, and the media query is never consulted.** Both
 * values are read from custom properties *on the node*, so the cascade answers —
 * which means `data-motion="full" | "reduced" | "none"` and
 * `prefers-reduced-motion` arrive already resolved, in the priority motion.md §4.2
 * gives them (`data-motion` wins). A `matchMedia` call here would silently
 * override an app that had asked for full motion. `focus-ring` does consult it,
 * for a reason that does not apply here: it swaps a travel for a crossfade, a
 * change of *nature* no token can express. A settle has no such variant — the
 * surface has to reach its detent either way, and only the speed changes.
 */

/** Which of the three recipes a release earned. */
export type SettleBucket = "slow" | "medium" | "flick";

export interface SettleCurve {
  /** Name of the custom property holding the duration, e.g. `--sui-duration-300`. */
  readonly duration: string;
  /** Name of the custom property holding the easing, e.g. `--sui-spring-smooth`. */
  readonly easing: string;
}

export interface SettleOptions {
  /** Value the animated property has right now, e.g. `"0 120px"`. */
  readonly from: string;
  /**
   * Value it must end on. Make the CSS say the same thing before calling: the
   * animation does not fill, so the last frame hands straight over to the cascade
   * and a mismatch shows as a one-frame jump.
   */
  readonly to: string;
  /** Signed px/ms, as `drag-axis` reports it. Only its magnitude is read here. */
  readonly velocity: number;
  /** Defaults to `translate` — compositor-only, and what a sheet moves on. */
  readonly property?: string | undefined;
  /** Override any of the three recipes' property names. */
  readonly tokens?: Partial<Readonly<Record<SettleBucket, SettleCurve>>> | undefined;
}

/**
 * The two speeds that separate the recipes, in px/ms (motion.md §2.5). Physics,
 * not presentation: a threshold is about the finger, and there is nothing for a
 * stylesheet to say about it.
 */
const SLOW_MAX = 0.2;
const FLICK_MIN = 0.5;

const DEFAULT_TOKENS: Readonly<Record<SettleBucket, SettleCurve>> = {
  slow: { duration: "--sui-spring-smooth-duration", easing: "--sui-spring-smooth" },
  medium: { duration: "--sui-duration-300", easing: "--sui-spring-smooth" },
  // motion.md §2.5 prescribes 180 ms here and the token ladder's nearest rung is
  // 200. The 20 ms are left on the table rather than written into this file: a
  // component that wants the exact number passes its own property, and the
  // catalogue keeps one place where durations live.
  flick: { duration: "--sui-duration-200", easing: "--sui-ease-in" },
};

const FALLBACK_DURATION: Readonly<Record<SettleBucket, number>> = {
  slow: 520,
  medium: 300,
  flick: 180,
};

const FALLBACK_EASING = "ease-out";

/** Local rather than shared: hoisting it would put it in the root bundle, which is
 * the one thing an opt-in module exists to stay out of. `focus-ring` keeps its own
 * copy for the same reason. */
function readMilliseconds(value: string, fallback: number): number {
  const trimmed = value.trim();
  const parsed = Number.parseFloat(trimmed);
  if (!Number.isFinite(parsed)) return fallback;
  return trimmed.endsWith("ms") ? parsed : parsed * 1000;
}

/**
 * Pure, and exported so a machine can assert the boundaries without a DOM. The
 * comparisons are deliberately asymmetric — `0.2` is medium and `0.5` is a flick —
 * so every speed lands in exactly one bucket.
 */
export function resolveSettleBucket(velocity: number): SettleBucket {
  const speed = Math.abs(velocity);
  if (speed < SLOW_MAX) return "slow";
  return speed < FLICK_MIN ? "medium" : "flick";
}

/**
 * Animates `node` from `from` to `to`, returning the `Animation` so the caller can
 * `cancel()` it when a new gesture starts and await `finished` when it lands.
 *
 * That promise is the second reason this lives in the core rather than in a
 * stylesheet: a sheet has to resize its inner scroller **once the settle is over**,
 * and `transitionend` fires per property and lies when interrupted.
 *
 * Returns `null` when there is nothing to animate — no node, no `animate`, or a
 * duration the cascade has flattened to zero. A caller treats that as "already
 * arrived", because the CSS has placed it.
 */
export function settleTo(
  node: HTMLElement | null | undefined,
  options: SettleOptions,
): Animation | null {
  if (node === null || node === undefined || typeof node.animate !== "function") return null;

  const bucket = resolveSettleBucket(options.velocity);
  const curve = options.tokens?.[bucket] ?? DEFAULT_TOKENS[bucket];
  const style = node.ownerDocument.defaultView?.getComputedStyle(node) ?? null;

  const duration = readMilliseconds(
    style?.getPropertyValue(curve.duration) ?? "",
    FALLBACK_DURATION[bucket],
  );
  if (duration <= 0) return null;

  const easing = (style?.getPropertyValue(curve.easing) ?? "").trim();
  const property = options.property ?? "translate";

  return node.animate([{ [property]: options.from }, { [property]: options.to }], {
    duration,
    easing: easing === "" ? FALLBACK_EASING : easing,
    // No fill: the last frame hands over to the cascade, which is already holding
    // the resting position. A `fill: "forwards"` would pin an inline-ish override
    // on the node and the next detent change would animate from a stale base.
    fill: "none",
  });
}

