/**
 * The measured half of a disclosure: how tall the panel is, and when its exit is
 * really over.
 *
 * Shared from day one by `accordion` and `collapsible`, with `tree-view` next.
 * It is a module rather than a sibling import because every component budget
 * marks `../../*` external: a component that imported a brother would be
 * measured nowhere at all (the 2026-08-28 rule, eight precedents in
 * `scripts/size-budget.ts`).
 *
 * **The two custom properties are written straight onto the node**, never
 * published through a bindable — the same arbitrage `data-scroll` makes
 * (architecture.md L47): a measurement is not a state, and routing it through
 * the machine would turn every open into a second render for a number no
 * transition depends on.
 *
 * `scrollHeight` in both directions, and it is an integer, so a panel may pop by
 * up to a pixel at the end of an open. A close that interrupts an open restarts
 * from the natural height rather than the current one. Both are Radix's
 * behaviour and both are accepted here rather than papered over.
 */

import { resolveEnvironment } from "../environment/environment";
import { createPresence, type Presence } from "../presence/presence";

export interface CollapseOptions {
  /** The node may take `hidden` — the machine drops the value from `exitingValues`. */
  onExitComplete(): void;
  /** Ceiling on the wait. Defaults to the presence's own. */
  readonly timeout?: number | undefined;
}

export interface Collapse {
  /**
   * Measures the node, writes `--sui-collapse-height` / `--sui-collapse-width`
   * on it, then hands the state to the presence. Measuring in both directions is
   * deliberate: the close needs the height the panel actually grew to, which is
   * not the one the open was measured at.
   */
  setOpen(open: boolean, node: HTMLElement | null | undefined): void;
  isExiting(): boolean;
  destroy(): void;
}

export function createCollapse(options: CollapseOptions): Collapse {
  // Read at each call and handed to the presence through a getter, exactly as
  // the vanilla adapter does: no paint pays for the resolution until an exit
  // actually starts, and a `data-motion` an app flips at runtime is obeyed by
  // the very next close instead of by the mode this instance was built with.
  let immediate = false;

  const presence: Presence = createPresence({
    onExitComplete: (): void => options.onExitComplete(),
    timeout: options.timeout,
    get immediate(): boolean {
      return immediate;
    },
  });

  return {
    setOpen(open: boolean, node: HTMLElement | null | undefined): void {
      if (node !== null && node !== undefined) {
        immediate = resolveEnvironment(node).motion === "none";
        node.style.setProperty("--sui-collapse-height", `${node.scrollHeight}px`);
        node.style.setProperty("--sui-collapse-width", `${node.scrollWidth}px`);
      }
      presence.setPresent(open, node);
    },
    isExiting: (): boolean => presence.isExiting(),
    destroy: (): void => presence.destroy(),
  };
}

/**
 * A dismissable layer is `interact-outside` plus Escape plus a place in the stack.
 *
 * Only the top-most layer reacts to Escape — otherwise one key press would close
 * a menu, its popover and the dialog holding both. Outside-membership is answered
 * by the stack, not by `contains`, so a portalled child never dismisses its own
 * parent. And the trigger is excluded by default: without that, clicking a trigger
 * to close would dismiss on pointerdown and reopen on the click that follows.
 */

import { addDomEvent } from "../dom/event";
import { contains } from "../dom/query";
import { trackInteractOutside } from "./interact-outside";
import { type DismissReason, getLayerStack, type Layer, type LayerType } from "./layer-stack";

export interface DismissableOptions {
  readonly id: string;
  readonly type: LayerType;
  readonly modal?: boolean | undefined;
  /** The layer this one opened from — required once either end is portalled. */
  readonly parentId?: string | undefined;
  onDismiss(reason: DismissReason): void;
  readonly onEscapeKeyDown?: ((event: KeyboardEvent) => void) | undefined;
  readonly onPointerDownOutside?: ((event: PointerEvent) => void) | undefined;
  readonly onFocusOutside?: ((event: FocusEvent) => void) | undefined;
  /** Nodes that are logically part of the layer — the trigger, an anchor. */
  readonly exclude?: (() => readonly (HTMLElement | null | undefined)[]) | undefined;
  readonly dismissOnEscape?: boolean | undefined;
  readonly dismissOnOutsidePointer?: boolean | undefined;
  readonly dismissOnFocusOutside?: boolean | undefined;
  readonly isDisabled?: (() => boolean) | undefined;
}

const NOOP: VoidFunction = () => {};

export function trackDismissableLayer(
  node: HTMLElement | null | undefined,
  options: DismissableOptions,
): VoidFunction {
  const doc = node?.ownerDocument;
  if (node === null || node === undefined || doc === undefined) return NOOP;

  const stack = getLayerStack(doc);
  const layer: Layer = {
    id: options.id,
    node,
    type: options.type,
    modal: options.modal ?? false,
    parentId: options.parentId,
    dismiss: (reason) => {
      stack.dismissals += 1;
      options.onDismiss(reason);
    },
  };
  stack.add(layer);

  const isExcluded = (target: HTMLElement): boolean =>
    (options.exclude?.() ?? []).some((excluded) => contains(excluded, target));

  const disposeOutside = trackInteractOutside(node, {
    isDisabled: options.isDisabled,
    isOutside: (target) => !stack.containsTarget(options.id, target) && !isExcluded(target),
    onPointerDownOutside: options.onPointerDownOutside,
    onFocusOutside: (event) => {
      options.onFocusOutside?.(event);
      if (options.dismissOnFocusOutside !== true) return;
      // Same guard as the pointer path, and now that focus has a channel of its own
      // it needs its own copy: a layer under a modal cannot be reached, and the
      // focus that just left it went *into* the modal above.
      if (stack.hasModalAbove(options.id)) return;
      layer.dismiss("focus-outside");
    },
    onInteractOutside: () => {
      if (options.dismissOnOutsidePointer === false) return;
      // A layer under a modal cannot be reached by a pointer anyway; dismissing it
      // would close the wrong surface.
      if (stack.hasModalAbove(options.id)) return;
      layer.dismiss("outside-pointer");
    },
  });

  const onKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== "Escape" || event.defaultPrevented) return;
    if (options.isDisabled?.() === true || !stack.isTopMost(options.id)) return;
    options.onEscapeKeyDown?.(event);
    if (event.defaultPrevented || options.dismissOnEscape === false) return;
    layer.dismiss("escape");
  };

  const disposeEscape = addDomEvent(doc, "keydown", onKeyDown, { capture: true });

  return () => {
    disposeEscape();
    disposeOutside();
    stack.remove(options.id);
  };
}

/**
 * A finger, a stylus or a mouse travelling along **one** axis, reported as a
 * signed offset in pixels and a signed velocity in px/ms.
 *
 * This is the half of a gesture that is *interaction*: capture, threshold,
 * sampling, the click a drag leaves behind. What a component does with the
 * release — settling to a resting position — is animation, and lives in
 * `@standarui/core/gesture` so a consumer that only pages a carousel never
 * downloads WAAPI (motion.md §3.3).
 *
 * **Not `press`.** That module's first rule is "never call `preventDefault` on a
 * pointer event", which is right for a press and wrong here: a drag has to stop
 * the text selection it would otherwise paint across the page. The two cannot be
 * one module, and a control uses one or the other.
 *
 * **Not the slider's pointer path either.** That one re-reads the track's rect on
 * every move and answers in percent, because a scroll under the finger would make
 * a cached rect drift. This one answers in signed pixels from where the gesture
 * started and reads no rect at all. Merging them would make an audited component
 * pay for a rewrite; the question is worth reopening when `carousel` and
 * `splitter` exist and there are three call sites to look at.
 */

import { addDomEvent, isPrimaryPointer } from "../dom/event";
import { resolveDir } from "../dom/text-dir";
import type { Direction } from "../types";

/** Which of the two logical axes the gesture runs along. */
export type DragAxis = "block" | "inline";

export interface DragAxisEvent {
  /** Signed pixels from where the gesture started, already mirrored for RTL. */
  readonly position: number;
  /** Signed px/ms over the recent window — `0` when the finger came to rest. */
  readonly velocity: number;
  readonly originalEvent: PointerEvent;
}

/**
 * While a press is armed, the browser's own drag of a link, an image or a selection inside the node is refused; an element marked `draggable="true"` keeps its drag-and-drop.
 */
export interface DragAxisOptions {
  /** A function is asked once per gesture, at `pointerdown`, for a value that can change. */
  readonly axis: DragAxis | (() => DragAxis);
  /**
   * Omit to read what the page resolved around the node (`resolveDir`). A
   * function is asked once per gesture, as `axis` is.
   */
  readonly dir?: Direction | (() => Direction | undefined) | undefined;
  /** Travel before the gesture is one, in px. Defaults to 4, as `color-picker`. */
  readonly threshold?: number | undefined;
  /**
   * Asked once, at `pointerdown`, before anything is armed. This is where a sheet
   * refuses a gesture that belongs to a scroller underneath it — the module has no
   * opinion about what makes a start legitimate, and every consumer's answer is
   * different.
   */
  readonly canStart?: ((event: PointerEvent) => boolean) | undefined;
  readonly isDisabled?: (() => boolean) | undefined;
  readonly onDragStart?: ((event: DragAxisEvent) => void) | undefined;
  readonly onDrag?: ((event: DragAxisEvent) => void) | undefined;
  readonly onDragEnd?: ((event: DragAxisEvent) => void) | undefined;
  readonly onDragCancel?: (() => void) | undefined;
}

interface Sample {
  readonly position: number;
  readonly time: number;
}

const NOOP: VoidFunction = () => {};

const DEFAULT_THRESHOLD_PX = 4;

/** Enough to average out one slow frame, short enough to stay recent. */
const SAMPLE_WINDOW = 5;

/**
 * A sample older than this is not evidence about where the finger is *going*.
 *
 * Without the cutoff a finger that flicks, holds still for half a second and then
 * lifts releases with the velocity of the flick, because holding still fires no
 * `pointermove` and the window keeps describing a movement that has stopped. The
 * sheet would then fly off under a finger that had visibly parked it.
 */
const STALE_SAMPLE_MS = 100;

export function trackDragAxis(
  node: HTMLElement | null | undefined,
  options: DragAxisOptions,
): VoidFunction {
  if (node === null || node === undefined) return NOOP;

  let pointerId: number | null = null;
  let started = false;
  let swallowClick = false;
  let origin = 0;
  // Resolved once per gesture rather than per move: without a `dir` prop the
  // answer comes from `getComputedStyle`, which forces a style recalc, and a
  // `pointermove` fires every frame while the writing direction does not change
  // under the finger. The same call the slider's pointer path makes.
  let sign = 1;
  let axis: DragAxis = "inline";
  let samples: Sample[] = [];

  const threshold = options.threshold ?? DEFAULT_THRESHOLD_PX;
  const disabled = (): boolean => options.isDisabled?.() ?? false;

  const coordinateOf = (event: PointerEvent): number =>
    axis === "block" ? event.clientY : event.clientX;

  const positionOf = (event: PointerEvent): number => (coordinateOf(event) - origin) * sign;

  const record = (position: number, time: number): void => {
    samples.push({ position, time });
    if (samples.length > SAMPLE_WINDOW) samples.shift();
  };

  const velocityAt = (time: number): number => {
    const last = samples.at(-1);
    if (last === undefined) return 0;
    const first = samples.find((sample) => time - sample.time <= STALE_SAMPLE_MS);
    if (first === undefined || last.time <= first.time) return 0;
    return (last.position - first.position) / (last.time - first.time);
  };

  const detail = (event: PointerEvent): DragAxisEvent => ({
    position: positionOf(event),
    velocity: velocityAt(event.timeStamp),
    originalEvent: event,
  });

  const releaseCapture = (): void => {
    if (pointerId === null) return;
    try {
      node.releasePointerCapture(pointerId);
    } catch {
      // Already handed back by the browser — nothing left to release.
    }
  };

  // The rest of an armed press is heard on the document, not on the node: the
  // capture waits for the threshold, and until then a move or a release only
  // reaches the node while the pointer is over it — a 24 px grabber loses the
  // move that crosses the threshold, and a release outside it would never come.
  let unlisten: VoidFunction = NOOP;

  const disarm = (): void => {
    unlisten();
    unlisten = NOOP;
    releaseCapture();
    pointerId = null;
    started = false;
  };

  const cancel = (): void => {
    const wasDragging = started;
    disarm();
    swallowClick = false;
    if (wasDragging) options.onDragCancel?.();
  };

  const onMove = (event: PointerEvent): void => {
    if (event.pointerId !== pointerId) return;
    if (
      !started &&
      (event.pointerType === "mouse" || event.pointerType === "pen") &&
      event.buttons === 0
    ) {
      // A bare hover: the button came up where this document could not hear it —
      // Firefox delivers no release outside the frame. Only touch is guaranteed an
      // implicit capture; a mouse or a pen can lose its release.
      disarm();
      return;
    }
    const position = positionOf(event);
    record(position, event.timeStamp);
    if (!started) {
      if (Math.abs(position) < threshold) return;
      started = true;
      swallowClick = true;
      try {
        node.setPointerCapture(event.pointerId);
      } catch {
        // A pointer that is already gone still deserves the rest of the sequence;
        // capture is what keeps the finger attached, not a precondition.
      }
      options.onDragStart?.(detail(event));
      return;
    }
    // The one `preventDefault` this module makes, and only once the gesture is
    // real: it stops the selection a drag would otherwise paint across the page.
    // Scroll is not stopped here — that is `touch-action`, which belongs to the
    // sheet, because only CSS can refuse a scroll before the first move fires.
    event.preventDefault();
    options.onDrag?.(detail(event));
  };

  const onUp = (event: PointerEvent): void => {
    if (event.pointerId !== pointerId) return;
    // Browsers do not guarantee a final `pointermove` at the release point, and
    // this sample is also what makes a parked finger read as stopped rather than
    // as whatever it was doing five frames ago.
    record(positionOf(event), event.timeStamp);
    const wasDragging = started;
    const end = detail(event);
    disarm();
    if (wasDragging) options.onDragEnd?.(end);
  };

  const onCancel = (event: PointerEvent): void => {
    if (event.pointerId !== pointerId) return;
    cancel();
  };

  const disposers = [
    addDomEvent(node, "pointerdown", (event: PointerEvent) => {
      // A mouse or a pen pressing while a press is armed proves its release was
      // lost — a focus switch, a touchpad tap with no move, a pen back with a new
      // id. A second touch is a second finger and waits its turn.
      if (pointerId !== null) {
        if (event.pointerType !== "mouse" && event.pointerType !== "pen") return;
        cancel();
      }
      if (disabled() || !isPrimaryPointer(event)) return;
      if (options.canStart?.(event) === false) return;
      pointerId = event.pointerId;
      started = false;
      swallowClick = false;
      axis = typeof options.axis === "function" ? options.axis() : options.axis;
      origin = coordinateOf(event);
      const dir = typeof options.dir === "function" ? options.dir() : options.dir;
      sign = axis === "inline" && resolveDir(dir, node) === "rtl" ? -1 : 1;
      samples = [{ position: 0, time: event.timeStamp }];
      const doc = node.ownerDocument;
      const off = [
        addDomEvent(doc, "pointermove", onMove, { capture: true }),
        addDomEvent(doc, "pointerup", onUp, { capture: true }),
        addDomEvent(doc, "pointercancel", onCancel, { capture: true }),
      ];
      unlisten = () => {
        for (const dispose of off) dispose();
      };
      // No capture and no `preventDefault` here, deliberately: nothing is a gesture
      // yet. A capture would retarget the `pointerup` to this node, and a click goes
      // to the common ancestor of where it went down and where it came up — so a
      // link or a button inside the dragged surface would never be activated.
    }),

    // A mouse that presses on a link, an image or a selection inside the surface
    // would otherwise start the browser's own drag-and-drop on its first move, and
    // the engine answers that with a `pointercancel` that ends this gesture. Only
    // refused while a press of ours is armed, and never for an element the page
    // made `draggable="true"` itself: that is a drag-and-drop someone asked for.
    addDomEvent(node, "dragstart", (event: DragEvent) => {
      if (pointerId === null) return;
      const target = event.target as Node | null;
      const element = target?.nodeType === 1 ? (target as Element) : target?.parentElement;
      const own = element?.closest('[draggable="true" i]');
      if (own !== null && own !== undefined && node.contains(own)) return;
      event.preventDefault();
    }),

    // A drag that ends over the surface still produces a click. Swallowing it is
    // what keeps a consumer's own handler from acting on a gesture that was never
    // a click (precedent: switch, slider, color-picker).
    addDomEvent(
      node,
      "click",
      (event: MouseEvent) => {
        if (!swallowClick) return;
        swallowClick = false;
        event.preventDefault();
        event.stopPropagation();
      },
      { capture: true },
    ),
  ];

  return () => {
    disarm();
    for (const dispose of disposers.reverse()) dispose();
  };
}

/**
 * The drawn bar of a strip that scrolls along its line (`toggle-group`, `tabs`):
 * a part outside the scroller, a thumb inside it, kept in step with the scroll.
 *
 * **Written straight onto the nodes, never through a machine.** The thumb moves on
 * every scroll frame, and a bindable would make each of them a transition, a notify
 * and an adapter render for a fact nothing reads back; the sheet draws from the two
 * custom properties and from `data-state`, the same trade `trackScrollEdges` makes.
 * `scroll-area` keeps its own machine because its viewport and content ids are its
 * own and its bars have hover, linger and page states a strip does not need.
 *
 * **Shown by the scroller's own `data-scroll-inline`**, which already leaves out the
 * vertical orientation and a disabled strip: the one fact that says there is
 * somewhere to go is read once and not recomputed here.
 */

import { addDomEvent } from "../dom/event";
import { observeAttributes, observeChildren, observeResize } from "../dom/observers";
import { getComputedDir } from "../dom/text-dir";
import { trackDragAxis } from "./drag-axis";
import { turnWheelInline } from "./scroll-edges";
import {
  type AxisMetrics,
  dragOffset,
  thumbLength,
  thumbPosition,
  trackLength,
} from "./scroll-thumb";

const NOOP: VoidFunction = () => {};

const LENGTH = "--sui-scroll-thumb-length";

const OFFSET = "--sui-scroll-thumb-offset";

export function trackInlineScrollbar(
  scroller: HTMLElement | null | undefined,
  bar: HTMLElement | null | undefined,
  thumb: HTMLElement | null | undefined,
): VoidFunction {
  if (scroller == null || bar == null || thumb == null) return NOOP;
  const win = scroller.ownerDocument.defaultView;
  if (win === null) return NOOP;

  const metrics = (): AxisMetrics => ({
    viewport: scroller.clientWidth,
    content: scroller.scrollWidth,
    offset: Math.abs(scroller.scrollLeft),
  });
  const track = (): number => trackLength(bar.clientWidth, false);

  let length = "";
  let offset = "";
  const sync = (): void => {
    const visible = scroller.hasAttribute("data-scroll-inline");
    const state = visible ? "visible" : "hidden";
    if (bar.getAttribute("data-state") !== state) bar.setAttribute("data-state", state);
    if (!visible) return;
    const read = metrics();
    const room = track();
    const nextLength = `${thumbLength(read, room)}px`;
    const nextOffset = `${thumbPosition(read, room)}px`;
    if (nextLength !== length) {
      length = nextLength;
      thumb.style.setProperty(LENGTH, length);
    }
    if (nextOffset !== offset) {
      offset = nextOffset;
      thumb.style.setProperty(OFFSET, offset);
    }
  };

  let frame = 0;
  const schedule = (): void => {
    if (frame !== 0) return;
    frame = win.requestAnimationFrame(() => {
      frame = 0;
      sync();
    });
  };

  const halt = (): void => scroller.scrollBy({ left: 0, behavior: "smooth" });

  let rtl = false;
  let start = 0;
  const write = (position: number): void => {
    scroller.scrollLeft = (rtl ? -1 : 1) * dragOffset(start, position, metrics(), track());
  };

  sync();

  const disposers = [
    addDomEvent(scroller, "scroll", schedule, { passive: true }),
    observeResize(scroller, sync),
    observeResize(bar, sync),
    observeChildren(scroller, sync),
    observeAttributes(scroller, ["data-scroll-inline"], sync),
    addDomEvent(thumb, "pointerdown", (event: PointerEvent) => {
      if (event.pointerType === "mouse" || event.pointerType === "pen") event.preventDefault();
      halt();
    }),
    addDomEvent(thumb, "wheel", (event) => turnWheelInline(scroller, event), { passive: false }),
    trackDragAxis(thumb, {
      axis: "inline",
      onDragStart: (event) => {
        halt();
        rtl = getComputedDir(scroller) === "rtl";
        start = Math.abs(scroller.scrollLeft);
        bar.setAttribute("data-dragging", "");
        write(event.position);
      },
      onDrag: (event) => write(event.position),
      onDragEnd: (event) => {
        write(event.position);
        bar.removeAttribute("data-dragging");
      },
      onDragCancel: () => {
        scroller.scrollLeft = (rtl ? -1 : 1) * start;
        bar.removeAttribute("data-dragging");
      },
    }),
  ];

  return () => {
    if (frame !== 0) win.cancelAnimationFrame(frame);
    frame = 0;
    bar.removeAttribute("data-dragging");
    for (const dispose of disposers.reverse()) dispose();
  };
}

/**
 * The raw plumbing for "the user interacted somewhere else". It deliberately does
 * NOT decide what "elsewhere" means: that answer belongs to the layer stack, so a
 * popover portalled out of a dialog is not treated as outside its own parent
 * (research/core.md §5, piège 2). The predicate is injected.
 *
 * Listeners are native and in capture, never routed through an adapter's
 * synthetic system — React's root delegation would otherwise let the outside
 * pointerdown land before the trigger's own handler and reopen what it just
 * closed (piège 4).
 *
 * A pointer that goes down inside and comes up outside is a drag, not an outside
 * interaction: the decision is taken on pointerdown and confirmed on pointerup.
 */

import { addDomEvent } from "../dom/event";
import { contains, getEventTarget, isHTMLElement } from "../dom/query";

export interface InteractOutsideOptions {
  readonly onPointerDownOutside?: ((event: PointerEvent) => void) | undefined;
  readonly onFocusOutside?: ((event: FocusEvent) => void) | undefined;
  readonly onInteractOutside?: ((event: Event) => void) | undefined;
  /** Extra exclusions — the layer stack, a portalled subtree, a trigger. */
  readonly isOutside?: ((target: HTMLElement) => boolean) | undefined;
  readonly isDisabled?: (() => boolean) | undefined;
}

const NOOP: VoidFunction = () => {};

export function trackInteractOutside(
  node: HTMLElement | null | undefined,
  options: InteractOutsideOptions,
): VoidFunction {
  const doc = node?.ownerDocument;
  if (node === null || node === undefined || doc === undefined) return NOOP;

  let pointerDownWasOutside = false;

  const outside = (event: Event): boolean => {
    const target = getEventTarget(event);
    if (!isHTMLElement(target)) return false;
    if (contains(node, target)) return false;
    // A target already detached from the document is the remains of the click
    // that removed it, not a click somewhere else.
    if (!contains(doc, target)) return false;
    return options.isOutside?.(target) ?? true;
  };

  const onPointerDown = (event: PointerEvent): void => {
    if (options.isDisabled?.() === true) {
      pointerDownWasOutside = false;
      return;
    }
    pointerDownWasOutside = outside(event);
    if (pointerDownWasOutside) options.onPointerDownOutside?.(event);
  };

  const onPointerUp = (event: PointerEvent): void => {
    const wasOutside = pointerDownWasOutside;
    pointerDownWasOutside = false;
    if (!wasOutside || !outside(event)) return;
    options.onInteractOutside?.(event);
  };

  // Focus leaving is reported on its own channel and never on the pointer's. It
  // used to call both, which made "dismiss on an outside click but not when focus
  // leaves" — what a popover anchored to a field wants — inexpressible, and closed
  // a non-modal surface with `outside-pointer` when nobody had pointed at anything.
  // Nobody saw it because a dialog is modal by default and traps the focus.
  const onFocusIn = (event: FocusEvent): void => {
    if (options.isDisabled?.() === true || !outside(event)) return;
    options.onFocusOutside?.(event);
  };

  const disposers = [
    addDomEvent(doc, "pointerdown", onPointerDown, { capture: true }),
    addDomEvent(doc, "pointerup", onPointerUp, { capture: true }),
    addDomEvent(doc, "focusin", onFocusIn, { capture: true }),
  ];

  return () => {
    for (let index = disposers.length - 1; index >= 0; index--) disposers[index]?.();
  };
}

/**
 * One stack of open surfaces per document, and the single source of truth for
 * "who closes first".
 *
 * `element.contains()` cannot answer that question. A popover portalled to the
 * body out of a dialog is not a DOM descendant of the dialog, so a click inside
 * it reads as outside and closes the dialog underneath it (research/core.md §5,
 * piège 2). Membership is therefore logical: a layer declares its parent, and
 * "inside" means inside that layer or inside any layer descending from it.
 *
 * The gamepad B button pops this same stack (CDC §4.4), which is why dismissal
 * order lives here rather than inside each component.
 */

import { contains } from "../dom/query";

export type LayerType = "dialog" | "drawer" | "popover" | "menu" | "listbox" | "tooltip";

/**
 * `"drag"` is the one a decorator sends: a sheet thrown past its smallest detent is
 * a dismissal, and it has to travel the same path as the others so `canDismiss`
 * gets its say and `onDismiss` is told why.
 */
export type DismissReason = "escape" | "outside-pointer" | "focus-outside" | "back" | "drag";

/**
 * The three a surface locks together, and the reason they are one question rather
 * than three clauses repeated in every machine that answers it.
 *
 * `closeOnEscape` already documents the pair: B and Escape share one lock. A drag
 * past the smallest detent joins them because it is the same kind of act — the
 * person saying "take this away", deliberately, from inside the surface. What it is
 * *not* is a click in the gutter: `closeOnInteractOutside` is about attention
 * landing elsewhere, and a thumb on the sheet never left.
 *
 * Stated once here so the eighth overlay gets it right by importing it. When
 * `"drag"` was added to the union, six of the seven machines carrying a
 * `canDismiss` compiled unchanged and silently routed it to the wrong branch —
 * only the three with an exhaustive `Record<DismissReason, …>` table said a word.
 */
export function isEscapeLikeDismissal(reason: DismissReason): boolean {
  return reason === "escape" || reason === "back" || reason === "drag";
}

export interface Layer {
  readonly id: string;
  readonly node: HTMLElement;
  readonly type: LayerType;
  /** Modal layers make everything below them inert and lock the scroll. */
  readonly modal: boolean;
  /** Declared parenthood — the part the DOM cannot tell us once portalled. */
  readonly parentId?: string | undefined;
  dismiss(reason: DismissReason): void;
}

export interface LayerStack {
  add(layer: Layer): void;
  remove(id: string): void;
  layers(): readonly Layer[];
  get(id: string): Layer | undefined;
  isTopMost(id: string): boolean;
  /** Layers descending from `id`, however deeply nested. */
  descendantsOf(id: string): Layer[];
  /** True when the target sits inside this layer or one of its descendants. */
  containsTarget(id: string, target: Node | null): boolean;
  /** Dismisses the top layer and reports whether there was one — the B button. */
  dismissTop(reason: DismissReason): boolean;
  hasModalAbove(id: string): boolean;
  /**
   * Bumped by every dismissal a layer of this document asks for, accepted or
   * not: a Tab held across a close reads it to tell its own close from one an
   * Escape, a pad's B or a press outside asked for since.
   */
  dismissals: number;
}

const stacks = new WeakMap<Document, LayerStack>();

export function getLayerStack(doc: Document): LayerStack {
  const existing = stacks.get(doc);
  if (existing !== undefined) return existing;

  const layers: Layer[] = [];
  const indexOf = (id: string): number => layers.findIndex((layer) => layer.id === id);
  const get = (id: string): Layer | undefined => layers.find((layer) => layer.id === id);

  const descendsFrom = (layer: Layer, ancestorId: string): boolean => {
    let parentId = layer.parentId;
    const seen = new Set<string>([layer.id]);
    while (parentId !== undefined && !seen.has(parentId)) {
      if (parentId === ancestorId) return true;
      seen.add(parentId);
      parentId = get(parentId)?.parentId;
    }
    return false;
  };

  const descendantsOf = (id: string): Layer[] =>
    layers.filter((layer) => layer.id !== id && descendsFrom(layer, id));

  const stack: LayerStack = {
    /**
     * A layer can arrive *after* its own descendants. React runs layout effects
     * child-first, so two dialogs that mount open in the same commit register
     * inner-then-outer, and a plain push would land the parent on top of its own
     * children: Escape would then dismiss the outer surface and unmount the inner
     * one with it — one key press, both gone. Declared parenthood outranks arrival
     * order, so a layer lands underneath anything that already descends from it.
     */
    add(layer: Layer): void {
      const existingIndex = indexOf(layer.id);
      if (existingIndex !== -1) layers.splice(existingIndex, 1);
      const firstDescendant = layers.findIndex((other) => descendsFrom(other, layer.id));
      if (firstDescendant === -1) layers.push(layer);
      else layers.splice(firstDescendant, 0, layer);
    },
    remove(id: string): void {
      const index = indexOf(id);
      if (index !== -1) layers.splice(index, 1);
      if (layers.length === 0) stacks.delete(doc);
    },
    layers: (): readonly Layer[] => layers,
    get,
    isTopMost: (id: string): boolean => layers.at(-1)?.id === id,
    descendantsOf,
    containsTarget(id: string, target: Node | null): boolean {
      const layer = get(id);
      if (layer === undefined || target === null) return false;
      if (contains(layer.node, target)) return true;
      return descendantsOf(id).some((child) => contains(child.node, target));
    },
    dismissTop(reason: DismissReason): boolean {
      const top = layers.at(-1);
      if (top === undefined) return false;
      top.dismiss(reason);
      return true;
    },
    hasModalAbove(id: string): boolean {
      const index = indexOf(id);
      if (index === -1) return false;
      return layers.slice(index + 1).some((layer) => layer.modal);
    },
    dismissals: 0,
  };

  stacks.set(doc, stack);
  return stack;
}

/**
 * Long press — the touch equivalent of a right click, and the gesture that opens
 * a context menu on iOS. The gamepad reaches the same machines through the Y
 * button (CDC §4.4), so a component never learns the gesture, only the intent.
 *
 * The pointer has to stay put: a long press that drifts is a scroll, and stealing
 * it would make a list unscrollable. `preventDefault` is never called — the native
 * callout is suppressed in CSS with `touch-action` / `-webkit-touch-callout`,
 * where it belongs.
 */

import { isPrimaryPointer } from "../dom/event";
import { timeout } from "../dom/raf";

export interface LongPressEvent {
  readonly target: HTMLElement;
  readonly pointerType: string;
  readonly x: number;
  readonly y: number;
  readonly originalEvent: PointerEvent;
}

export interface LongPressOptions {
  readonly onLongPress: (event: LongPressEvent) => void;
  readonly onCancel?: (() => void) | undefined;
  readonly isDisabled?: (() => boolean) | undefined;
  /** Milliseconds before it fires. 500 is the iOS context-menu delay. */
  readonly threshold?: number | undefined;
  /** Movement in px that turns the gesture into a scroll. */
  readonly tolerance?: number | undefined;
  /** Mouse long-press is off by default: on a pointer device it is a right click. */
  readonly allowMouse?: boolean | undefined;
}

const NOOP: VoidFunction = () => {};
const DEFAULT_THRESHOLD = 500;
const DEFAULT_TOLERANCE = 10;

export function trackLongPress(
  node: HTMLElement | null | undefined,
  options: LongPressOptions,
): VoidFunction {
  const win = node?.ownerDocument.defaultView;
  if (node === null || node === undefined || win === null || win === undefined) return NOOP;

  const threshold = options.threshold ?? DEFAULT_THRESHOLD;
  const tolerance = options.tolerance ?? DEFAULT_TOLERANCE;
  let cancelTimer: VoidFunction | undefined;
  let origin: { x: number; y: number; pointerId: number } | null = null;

  const cancel = (): void => {
    if (origin === null) return;
    origin = null;
    cancelTimer?.();
    cancelTimer = undefined;
    options.onCancel?.();
  };

  const onPointerDown = (event: PointerEvent): void => {
    if (options.isDisabled?.() === true || !isPrimaryPointer(event)) return;
    if (event.pointerType === "mouse" && options.allowMouse !== true) return;

    origin = { x: event.clientX, y: event.clientY, pointerId: event.pointerId };
    cancelTimer = timeout(
      win,
      () => {
        origin = null;
        cancelTimer = undefined;
        options.onLongPress({
          target: node,
          pointerType: event.pointerType,
          x: event.clientX,
          y: event.clientY,
          originalEvent: event,
        });
      },
      threshold,
    );
  };

  const onPointerMove = (event: PointerEvent): void => {
    if (origin === null || event.pointerId !== origin.pointerId) return;
    const moved = Math.hypot(event.clientX - origin.x, event.clientY - origin.y);
    if (moved > tolerance) cancel();
  };

  node.addEventListener("pointerdown", onPointerDown);
  node.addEventListener("pointermove", onPointerMove);
  node.addEventListener("pointerup", cancel);
  node.addEventListener("pointercancel", cancel);
  node.addEventListener("pointerleave", cancel);

  return () => {
    cancel();
    node.removeEventListener("pointerdown", onPointerDown);
    node.removeEventListener("pointermove", onPointerMove);
    node.removeEventListener("pointerup", cancel);
    node.removeEventListener("pointercancel", cancel);
    node.removeEventListener("pointerleave", cancel);
  };
}

/**
 * Unified press tracking over pointer events.
 *
 * Two rules, both learned from React Aria's 2025 rewrite of `usePress`: never
 * call `preventDefault` on a pointer event, and never move focus by hand. The
 * browser already does both correctly, and fighting it is what breaks text
 * selection, drag-and-drop and the iOS keyboard.
 *
 * Pointer capture is what makes press feel native: the finger can slide off the
 * control and come back, and `press-end` / `press-start` fire as it crosses the
 * bounds, so `data-pressed` follows the finger. A press that ends outside the
 * bounds is cancelled, exactly like a native button.
 *
 * A control uses either this or `onClick` — never both, or a touch will fire the
 * machine twice through the compatibility click.
 */

import { isPrimaryPointer } from "../dom/event";

export type PressPointerType = "mouse" | "touch" | "pen" | "keyboard" | "virtual";

export interface PressEvent {
  readonly type: "press-start" | "press-end" | "press" | "press-cancel";
  readonly pointerType: PressPointerType;
  readonly target: HTMLElement;
  readonly originalEvent: Event;
}

export interface PressOptions {
  readonly onPressStart?: ((event: PressEvent) => void) | undefined;
  readonly onPressEnd?: ((event: PressEvent) => void) | undefined;
  readonly onPress?: ((event: PressEvent) => void) | undefined;
  readonly onPressCancel?: ((event: PressEvent) => void) | undefined;
  readonly isDisabled?: (() => boolean) | undefined;
  /**
   * Enter and Space activate the way a native button does. Leave it off on a real
   * `<button>`, which already turns both into a click.
   */
  readonly keyboard?: boolean | undefined;
}

const NOOP: VoidFunction = () => {};

function isWithin(node: HTMLElement, x: number, y: number): boolean {
  const rect = node.getBoundingClientRect();
  return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
}

export function trackPress(
  node: HTMLElement | null | undefined,
  options: PressOptions,
): VoidFunction {
  if (node === null || node === undefined) return NOOP;

  let pointerId: number | null = null;
  let pointerType: PressPointerType = "mouse";
  let within = false;
  let keyDown = false;

  const disabled = (): boolean => options.isDisabled?.() ?? false;

  const emit = (type: PressEvent["type"], originalEvent: Event): void => {
    const event: PressEvent = { type, pointerType, target: node, originalEvent };
    if (type === "press-start") options.onPressStart?.(event);
    else if (type === "press-end") options.onPressEnd?.(event);
    else if (type === "press") options.onPress?.(event);
    else options.onPressCancel?.(event);
  };

  const release = (event: Event): void => {
    if (pointerId !== null && node.hasPointerCapture(pointerId)) {
      node.releasePointerCapture(pointerId);
    }
    pointerId = null;
    if (!within) return;
    within = false;
    emit("press-end", event);
  };

  const onPointerDown = (event: PointerEvent): void => {
    if (disabled() || pointerId !== null || !isPrimaryPointer(event)) return;
    pointerId = event.pointerId;
    // `pointerType` is "" for some assistive-technology clicks; treat those as
    // virtual so a control can tell a real finger from a screen-reader activation.
    pointerType = (event.pointerType || "virtual") as PressPointerType;
    within = true;
    try {
      node.setPointerCapture(event.pointerId);
    } catch {
      // The pointer can already be gone, and a programmatic activation has no
      // real pointer to capture. Neither is a reason to drop the press.
    }
    emit("press-start", event);
  };

  const onPointerMove = (event: PointerEvent): void => {
    if (event.pointerId !== pointerId) return;
    const inside = isWithin(node, event.clientX, event.clientY);
    if (inside === within) return;
    within = inside;
    emit(inside ? "press-start" : "press-end", event);
  };

  const onPointerUp = (event: PointerEvent): void => {
    if (event.pointerId !== pointerId) return;
    const activated = within && !disabled();
    release(event);
    if (activated) emit("press", event);
  };

  const onPointerCancel = (event: PointerEvent): void => {
    if (event.pointerId !== pointerId) return;
    release(event);
    emit("press-cancel", event);
  };

  const onKeyDown = (event: KeyboardEvent): void => {
    if (disabled() || (event.key !== "Enter" && event.key !== " ")) return;
    // Space would scroll the page. This is the one `preventDefault` press makes,
    // and only when it is standing in for a button that is not a `<button>`.
    if (event.key === " ") event.preventDefault();
    if (event.repeat) return;
    pointerType = "keyboard";
    keyDown = true;
    within = true;
    emit("press-start", event);
    // Enter activates on keydown, Space on keyup — APG, and what a native button does.
    if (event.key === "Enter") {
      keyDown = false;
      within = false;
      emit("press-end", event);
      emit("press", event);
    }
  };

  const onKeyUp = (event: KeyboardEvent): void => {
    if (!keyDown || event.key !== " ") return;
    keyDown = false;
    within = false;
    emit("press-end", event);
    if (!disabled()) emit("press", event);
  };

  const onBlur = (event: FocusEvent): void => {
    if (!keyDown) return;
    keyDown = false;
    within = false;
    emit("press-end", event);
    emit("press-cancel", event);
  };

  node.addEventListener("pointerdown", onPointerDown);
  node.addEventListener("pointermove", onPointerMove);
  node.addEventListener("pointerup", onPointerUp);
  node.addEventListener("pointercancel", onPointerCancel);
  if (options.keyboard === true) {
    node.addEventListener("keydown", onKeyDown);
    node.addEventListener("keyup", onKeyUp);
    node.addEventListener("blur", onBlur);
  }

  return () => {
    node.removeEventListener("pointerdown", onPointerDown);
    node.removeEventListener("pointermove", onPointerMove);
    node.removeEventListener("pointerup", onPointerUp);
    node.removeEventListener("pointercancel", onPointerCancel);
    node.removeEventListener("keydown", onKeyDown);
    node.removeEventListener("keyup", onKeyUp);
    node.removeEventListener("blur", onBlur);
    if (pointerId !== null && node.hasPointerCapture(pointerId)) {
      node.releasePointerCapture(pointerId);
    }
  };
}

/**
 * The pointer's intent, read from where it has been rather than from where it is.
 *
 * A cascading surface — a submenu, a nested `select`, a `navigation-menu` panel —
 * sits diagonally from the item that opened it, so a pointer travelling towards it
 * necessarily crosses items that are not it. Closing on that crossing is the
 * single most complained-about bug in every menu implementation that does not do
 * this, and re-opening afterwards is not the same thing: the child would flicker.
 *
 * Pure, and deliberately so — the whole rule is testable with four numbers and no
 * DOM. The trail is the caller's; this module only reads it.
 */

import type { Rect } from "../types";

export interface TrailPoint {
  readonly x: number;
  readonly y: number;
}

/** Enough to have a direction, few enough that a flick does not outlive itself. */
const DEFAULT_TRAIL_LENGTH = 3;

/** How far past the surface's edges the cone still counts as "heading in". */
const DEFAULT_PAD = 12;

export function pushTrail(
  trail: readonly TrailPoint[],
  point: TrailPoint,
  length: number = DEFAULT_TRAIL_LENGTH,
): TrailPoint[] {
  return [...trail, point].slice(-length);
}

/**
 * Whether the pointer, extended along its recent travel, would cross the near edge
 * of `rect` between its top and bottom. A cone rather than the literal triangle of
 * the classic implementation: the two are the same test, and one line of algebra
 * is cheaper than three cross products.
 */
export function isPointerHeadingTo(
  trail: readonly TrailPoint[],
  rect: Rect | null,
  pad: number = DEFAULT_PAD,
): boolean {
  if (rect === null || rect.width === 0 || trail.length < 2) return false;
  const to = trail[trail.length - 1];
  const from = trail[0];
  if (to === undefined || from === undefined) return false;

  const dx = to.x - from.x;
  if (dx === 0) return false;
  // The edge the pointer would reach first: the surface is on one side or the other.
  const distance = (rect.x >= to.x ? rect.x : rect.x + rect.width) - to.x;
  // Travelling away from it, or already past it.
  if (distance * dx <= 0) return false;

  const y = to.y + ((to.y - from.y) * distance) / dx;
  return y >= rect.y - pad && y <= rect.y + rect.height + pad;
}

/**
 * Which way a scroller can still go, published on the scroller itself as
 * `data-scroll="up" | "down" | "up down"` — absent when there is nothing to
 * reach in either direction.
 *
 * **Written by an effect straight onto the node, never through a bindable.** The
 * value changes on every scroll frame, and a bindable would make each of them a
 * transition, a notify and an adapter render — for a fact no state depends on.
 * Nothing in a machine ever reads it back; it exists so a sheet can draw the
 * affordance, which is the same trade the positioner already makes with
 * `--sui-transform-origin`. The inline variant does two more things, both for
 * the machine that installed it: it writes `tabindex="-1"` on a scroller that
 * scrolls, and it tells the caller when the box starts or stops being one.
 *
 * Three things move it and all three are watched, because two of them are not
 * scrolls at all: the surface being re-capped against a shrinking viewport
 * (`observeResize`) and rows being added or removed under a filter
 * (`observeChildren`) both change what is reachable without the scroll position
 * moving a pixel.
 */

import { addDomEvent } from "../dom/event";
import { observeAttributes, observeChildren, observeResize } from "../dom/observers";
import { getComputedDir } from "../dom/text-dir";
import { resolveEnvironment } from "../environment/environment";

export type ScrollEdges = "" | "up" | "down" | "up down";

/**
 * A pixel of slack on both reads. A fractional zoom, a subpixel row height or a
 * device pixel ratio that is not an integer all leave `scrollTop + clientHeight`
 * a fraction short of `scrollHeight` on a scroller that is, visibly, at its end —
 * and an affordance that says "there is more below" when there is not is worse
 * than none, because it never goes away.
 */
const EPSILON = 1;

export function readScrollEdges(el: Element): ScrollEdges {
  const up = el.scrollTop > EPSILON;
  const down = el.scrollTop + el.clientHeight < el.scrollHeight - EPSILON;
  if (up) return down ? "up down" : "up";
  return down ? "down" : "";
}

/**
 * Whether `el` still has somewhere to go in one logical direction on one axis.
 *
 * The question `readScrollEdges` answers is "what affordance do I draw", and its
 * vocabulary — `up`, `down`, published as `data-scroll` — is the answer to that
 * one. This is a different question: *does this gesture belong to the scroller or
 * to the surface around it*, asked once at `pointerdown` and never drawn. Widening
 * `ScrollEdges` to carry an inline pair would have changed what `data-scroll`
 * publishes for `menu`, which already ships, so the two stay apart.
 *
 * **Reads `scrollLeft` through `Math.abs`, which is what makes it direction-blind.**
 * Under the modern model an RTL scroller runs from `0` at the inline start down to
 * a negative number at the inline end, an LTR one from `0` up to a positive one:
 * the distance already travelled from the start is the magnitude either way, so no
 * `dir` has to be resolved and no writing direction can be got wrong.
 */
export function hasScrollRoom(
  el: Element,
  axis: "block" | "inline",
  towards: "start" | "end",
): boolean {
  const travelled = axis === "block" ? el.scrollTop : Math.abs(el.scrollLeft);
  if (towards === "start") return travelled > EPSILON;
  const visible = axis === "block" ? el.clientHeight : el.clientWidth;
  const total = axis === "block" ? el.scrollHeight : el.scrollWidth;
  return travelled + visible < total - EPSILON;
}

const NOOP: VoidFunction = () => {};

const writtenTabindex = new WeakSet<Element>();

function trackEdges<T extends string>(
  el: HTMLElement | null | undefined,
  attribute: string,
  read: (el: Element) => T,
  onChange?: (edges: T) => void,
  attributes: readonly string[] = [],
): VoidFunction {
  if (el === null || el === undefined) return NOOP;

  let last: T | null = null;
  const sync = (): void => {
    const edges = read(el);
    if (edges === last) return;
    last = edges;
    if (edges === "") el.removeAttribute(attribute);
    else el.setAttribute(attribute, edges);
    onChange?.(edges);
  };

  sync();
  const removeScroll = addDomEvent(el, "scroll", sync, { passive: true });
  const stopResize = observeResize(el, sync);
  const stopChildren = observeChildren(el, sync);
  const stopAttributes = attributes.length > 0 ? observeAttributes(el, attributes, sync) : NOOP;

  return () => {
    stopAttributes();
    stopChildren();
    stopResize();
    removeScroll();
  };
}

/**
 * Keeps `data-scroll` current on `el` until the returned disposer runs.
 *
 * **The disposer does not take the attribute back**, and that is deliberate: a
 * surface tears its effects down when it starts closing, while `presence` keeps
 * the node mounted for the exit. Removing it there would snap the affordance off
 * at the first frame of a fade the person is still watching. The install re-reads,
 * so a reopened surface never inherits a stale value.
 */
export function trackScrollEdges(el: HTMLElement | null | undefined): VoidFunction {
  return trackEdges(el, "data-scroll", readScrollEdges);
}

/**
 * Which way a scroller can still go along the inline axis, published as
 * `data-scroll-inline="start" | "end" | "start end"`. `start` means there is
 * content before the visible window in the writing direction, so the leading edge
 * is where the affordance belongs; the vocabulary is logical so a right-to-left
 * scroller needs no second reading. A separate attribute from `data-scroll`, for
 * the reason `hasScrollRoom` gives: `menu` already ships the vertical one.
 */
export type InlineScrollEdges = "" | "start" | "end" | "start end";

export function readInlineScrollEdges(el: Element): InlineScrollEdges {
  const start = hasScrollRoom(el, "inline", "start");
  const end = hasScrollRoom(el, "inline", "end");
  if (start) return end ? "start end" : "start";
  return end ? "end" : "";
}

/**
 * Keeps `data-scroll-inline` current on `el`, with the disposer semantics of
 * `trackScrollEdges`. **It also writes `tabindex="-1"` on `el` while the scroller
 * has somewhere to go**, and takes it back when it has not: Firefox makes every
 * scrollable box a tab stop of its own, in front of the roving stop the composite
 * already exposes, and arrows pressed there scroll instead of moving. The nodes
 * this module has written one on are remembered module-wide, so an install that
 * follows a disposer on the same node (a re-run effect, `StrictMode`) still knows
 * the attribute is its own to remove; an author's own `tabindex` is never touched.
 * `active` is asked on every read, for the scroller whose axis is not always the
 * inline one: while it answers `false` the attribute is absent, whatever the box
 * overflows by. `attributes` names attributes of `el` that, when they change,
 * make a read of their own — what `active` depends on, when nothing else
 * observable moves with it. `onToggle` runs after the box starts or stops being a
 * scroller, which is when the sheet changes its padding and every child moves
 * without resizing — the one change a caller that measures children cannot hear
 * from an observer. **While the box scrolls, a vertical wheel over it moves it
 * along its line** until it has no further to go (`turnWheelInline`); a box that
 * fits never takes the wheel from the page, and `wheel: false` never installs the
 * listener at all.
 */
export function trackInlineScrollEdges(
  el: HTMLElement | null | undefined,
  options: {
    active?: () => boolean;
    attributes?: readonly string[];
    onToggle?: () => void;
    wheel?: boolean;
  } = {},
): VoidFunction {
  if (el === null || el === undefined) return NOOP;

  const { active = () => true, attributes, onToggle, wheel = true } = options;
  let scrolls = false;
  let stopWheel = NOOP;
  const read = (node: Element): InlineScrollEdges => (active() ? readInlineScrollEdges(node) : "");
  const stopEdges = trackEdges(
    el,
    "data-scroll-inline",
    read,
    (edges) => {
      if (edges !== "" && !el.hasAttribute("tabindex")) {
        el.setAttribute("tabindex", "-1");
        writtenTabindex.add(el);
      } else if (edges === "" && writtenTabindex.has(el)) {
        el.removeAttribute("tabindex");
        writtenTabindex.delete(el);
      }
      if ((edges !== "") !== scrolls) {
        scrolls = edges !== "";
        stopWheel();
        stopWheel =
          scrolls && wheel
            ? addDomEvent(el, "wheel", (event) => turnWheelInline(el, event), { passive: false })
            : NOOP;
        onToggle?.();
      }
    },
    attributes,
  );
  return () => {
    stopWheel();
    stopEdges();
  };
}

/** What one line of a wheel in `DOM_DELTA_LINE` is taken to be worth, in pixels. */
const WHEEL_LINE = 16;

/**
 * A vertical wheel over a strip that scrolls along its line moves the strip, and
 * only while it can still go that way: at its end, when the wheel is mostly
 * horizontal, or with Ctrl, Shift, Meta or Alt held (zoom, sideways, and the
 * gestures a platform or an app gives those), the event is left alone and the
 * page scrolls as it would anywhere else. Installed
 * only while the box is a scroller, which is the one time it is passive: false.
 * Down goes to the inline end, so to the left in a right-to-left strip. The
 * deltas are read before `deltaMode`: Firefox reports lines to a page that asks
 * for the mode first, and pixels otherwise. The drawn bar's thumb, which is outside
 * the scroller and takes the pointer, hands its wheel here too.
 */
export function turnWheelInline(el: HTMLElement, event: WheelEvent): void {
  const { altKey, ctrlKey, metaKey, shiftKey, deltaX, deltaY } = event;
  if (event.defaultPrevented || altKey || ctrlKey || metaKey || shiftKey) return;
  if (Math.abs(deltaY) <= Math.abs(deltaX)) return;
  if (!hasScrollRoom(el, "inline", deltaY > 0 ? "end" : "start")) return;

  const unit = [1, WHEEL_LINE, el.clientWidth][event.deltaMode] ?? 1;
  event.preventDefault();
  el.scrollLeft += (getComputedDir(el) === "rtl" ? -deltaY : deltaY) * unit;
}

/**
 * Brings `target` into view along the inline axis of `scroller` and nowhere
 * else worth naming: the nearest edge, so nothing moves when it is already
 * visible, and `scroll-padding-inline` is respected, so the item stops past the
 * fade and not under it. A scroller with nothing to scroll is left alone, which
 * is what keeps a group that fits from moving the page. The motion resolves like
 * `tabs`' `scrollActiveIntoView`: attributes first, media query second. **A smooth
 * scroll asked for earlier is cancelled first, by a smooth scroll of nothing**:
 * Firefox starts a smooth scroll a frame or more after the call, so the scroller
 * still reads its old position, and a `scrollIntoView` with nothing to do there
 * left the earlier one to run on — a burst of arrows round the track came back to
 * the first segment and slid on to the end. Once a frame has passed, an instant
 * scroll to the same position no longer cancels it in Firefox and a smooth one
 * does; WebKit keeps it through either, and the `scrollIntoView` that follows
 * replaces it there.
 */
export function scrollIntoInlineView(scroller: HTMLElement | null, target: HTMLElement): void {
  if (scroller === null || scroller.scrollWidth <= scroller.clientWidth) return;
  const behavior = resolveEnvironment(scroller).reducedMotion ? "auto" : "smooth";
  scroller.scrollBy({ left: 0, behavior });
  target.scrollIntoView({ block: "nearest", inline: "nearest", behavior });
}

export interface AxisMetrics {
  readonly viewport: number;
  readonly content: number;
  readonly offset: number;
}

export const OVERFLOW_EPSILON = 1;

export const SCROLLBAR_SIZE = 12;

export const THUMB_INSET = 3;

export const THUMB_MIN = 16;

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function overflows(metrics: AxisMetrics): boolean {
  return metrics.content > metrics.viewport + OVERFLOW_EPSILON;
}

export function trackLength(viewport: number, corner: boolean): number {
  return Math.max(0, viewport - 2 * THUMB_INSET - (corner ? SCROLLBAR_SIZE : 0));
}

export function thumbLength(metrics: AxisMetrics, track: number): number {
  if (!overflows(metrics) || track <= 0) return 0;
  return Math.min(track, Math.max(THUMB_MIN, (track * metrics.viewport) / metrics.content));
}

export function thumbPosition(metrics: AxisMetrics, track: number): number {
  const range = metrics.content - metrics.viewport;
  const travel = track - thumbLength(metrics, track);
  if (range <= 0 || travel <= 0) return 0;
  return clamp((travel * metrics.offset) / range, 0, travel);
}

export function dragOffset(
  start: number,
  position: number,
  metrics: AxisMetrics,
  track: number,
): number {
  const range = Math.max(0, metrics.content - metrics.viewport);
  const travel = track - thumbLength(metrics, track);
  if (range === 0 || travel <= 0) return clamp(start, 0, range);
  return clamp(start + (position * range) / travel, 0, range);
}

export function pageOffset(metrics: AxisMetrics, direction: 1 | -1): number {
  const range = Math.max(0, metrics.content - metrics.viewport);
  return clamp(metrics.offset + direction * metrics.viewport, 0, range);
}

/**
 * Shared typeahead buffer for menu, select, listbox and tree.
 *
 * Pure: the caller owns the state object and passes the clock, so the whole
 * behaviour is testable without a DOM and without fake timers. Two APG rules do
 * the work — repeating one character cycles through the items that start with it,
 * and anything else extends the search string until the buffer times out.
 */

export interface TypeaheadState {
  query: string;
  lastKeyAt: number;
}

export interface TypeaheadOptions<T> {
  readonly items: readonly T[];
  readonly itemToString: (item: T) => string;
  readonly isItemDisabled?: ((item: T) => boolean) | undefined;
  readonly activeIndex?: number | undefined;
  /** How long the buffer survives between keystrokes. */
  readonly timeout?: number | undefined;
  readonly now?: number | undefined;
}

const DEFAULT_TIMEOUT = 350;

export function createTypeaheadState(): TypeaheadState {
  return { query: "", lastKeyAt: 0 };
}

/** A key that types a character, as opposed to one that navigates. */
export function isTypeaheadKey(key: string): boolean {
  return key.length === 1 && key !== " " && !/\s/.test(key);
}

export function getByTypeahead<T>(
  state: TypeaheadState,
  key: string,
  options: TypeaheadOptions<T>,
): T | null {
  const now = options.now ?? Date.now();
  const expired = now - state.lastKeyAt > (options.timeout ?? DEFAULT_TIMEOUT);
  state.query = (expired ? "" : state.query) + key.toLowerCase();
  state.lastKeyAt = now;

  // "aaa" means "cycle through the a's", not "look for the item called aaa".
  const repeated =
    state.query.length > 1 && [...state.query].every((char) => char === key.toLowerCase());
  const search = repeated ? key.toLowerCase() : state.query;

  const { items, itemToString, isItemDisabled, activeIndex } = options;
  const count = items.length;
  if (count === 0) return null;

  // Start after the active item when cycling, and at it otherwise, so extending a
  // search never jumps away from a match the user is already sitting on.
  const from = activeIndex === undefined || activeIndex < 0 ? 0 : activeIndex + (repeated ? 1 : 0);

  for (let offset = 0; offset < count; offset++) {
    const item = items[(from + offset) % count];
    if (item === undefined) continue;
    if (isItemDisabled?.(item) === true) continue;
    if (itemToString(item).toLowerCase().startsWith(search)) return item;
  }
  return null;
}

export function resetTypeahead(state: TypeaheadState): void {
  state.query = "";
  state.lastKeyAt = 0;
}

import { toKebabCase } from "../utils/string";

/**
 * The anatomy is the single source of truth for a component's parts, shared by
 * `connect`, the SCSS layer, the docs and the tests (research/core.md §1.3).
 * Part keys are camelCase in code and kebab-case on the element, so the styles
 * read `[data-part~="menu:item-trigger"]`.
 *
 * Both attributes are token *lists*, in the shape of `class`: composing two parts
 * onto one element — `<PopoverTrigger render={<ButtonRoot/>}>` — gives that
 * element both identities rather than the outer one erasing the inner. `data-part`
 * carries the scope with it (`"popover:trigger button:root"`) precisely so that a
 * list cannot invent a pair nobody rendered: with the scope in a separate list,
 * that element would also answer to `popover` × `root`, and the day somebody
 * styles that pair the breakage is silent. The token *is* the pair, so `~=` is
 * exact.
 */

export interface PartAttributes {
  /** The component's own name; a list when parts are composed. */
  readonly "data-scope": string;
  /** Scope-qualified — `"dialog:close-trigger"`, never a bare `"close-trigger"`. */
  readonly "data-part": string;
}

export interface AnatomyPart {
  readonly attrs: PartAttributes;
  readonly selector: string;
}

export interface Anatomy<T extends string> {
  readonly name: string;
  parts<P extends string>(...names: P[]): Anatomy<P>;
  extendWith<P extends string>(...names: P[]): Anatomy<T | P>;
  rename(name: string): Anatomy<T>;
  keys(): T[];
  build(): Record<T, AnatomyPart>;
}

export function createAnatomy<T extends string = never>(
  name: string,
  parts: readonly T[] = [],
): Anatomy<T> {
  return {
    name,
    parts: <P extends string>(...names: P[]): Anatomy<P> => createAnatomy<P>(name, names),
    extendWith: <P extends string>(...names: P[]): Anatomy<T | P> =>
      createAnatomy<T | P>(name, [...parts, ...names]),
    rename: (next: string): Anatomy<T> => createAnatomy<T>(next, parts),
    keys: (): T[] => [...parts],
    build: (): Record<T, AnatomyPart> => {
      const result = {} as Record<T, AnatomyPart>;
      for (const part of parts) {
        const attrs: PartAttributes = {
          "data-scope": name,
          "data-part": `${name}:${toKebabCase(part)}`,
        };
        result[part] = { attrs, selector: `[data-part~="${attrs["data-part"]}"]` };
      }
      return result;
    },
  };
}

import type { Machine, MachineConfig, MachineSchema } from "./types";

/**
 * A typed identity. It exists to bind the schema to the config so every state
 * name, event type, guard, action and effect is checked against the same
 * declaration — and for nothing else: a machine must stay inert data so it can
 * be shared between an SSR render and every client instance.
 */
export function createMachine<S extends MachineSchema>(config: MachineConfig<S>): Machine<S> {
  return config;
}

import type { Scope } from "./scope";

/**
 * Part ids are derived, never generated: `{component}:{scope id}:{part}`, with the
 * scope id coming from the adapter (`useId` and friends). No `Math.random()`, no
 * module-level counter — that is the whole hydration-safety story (research/core.md
 * §1.4). Any part can be overridden through the machine's `ids` prop, which is how
 * a consumer wires a label rendered outside the component.
 */
export function getPartId(scope: Scope, component: string, part: string, key?: string): string {
  const overrideKey = key === undefined ? part : `${part}:${key}`;
  const override = scope.ids?.[overrideKey];
  if (override !== undefined) return override;
  const base = `${component}:${scope.id}:${part}`;
  return key === undefined ? base : `${base}:${key}`;
}

/**
 * The prop getters returned by `connect` speak plain DOM: HTML attribute names,
 * native event types, camelCase handlers. Every adapter's `normalizeProps` maps
 * that to its own dialect (`class` → `className`, `onFocusIn` → `onFocus`,
 * `onClick` → `onclick`…) and casts once, at that boundary — which is why the
 * handlers below are typed with real DOM events even though React will hand a
 * synthetic one to the same function.
 *
 * `data-*` and `aria-*` are pattern index signatures rather than an exhaustive
 * list: the state contract (`data-state`, `data-focus-visible`…) grows per
 * component, but a typo in a real prop still fails to compile.
 */

export type EventHandler<E extends Event = Event> = (event: E) => void;

export interface DOMEventProps {
  onClick?: EventHandler<MouseEvent> | undefined;
  /** Middle and right button. `click` never fires for either. */
  onAuxClick?: EventHandler<MouseEvent> | undefined;
  onDoubleClick?: EventHandler<MouseEvent> | undefined;
  onContextMenu?: EventHandler<MouseEvent> | undefined;
  onMouseDown?: EventHandler<MouseEvent> | undefined;
  onMouseUp?: EventHandler<MouseEvent> | undefined;
  onMouseEnter?: EventHandler<MouseEvent> | undefined;
  onMouseLeave?: EventHandler<MouseEvent> | undefined;
  onMouseMove?: EventHandler<MouseEvent> | undefined;
  onPointerDown?: EventHandler<PointerEvent> | undefined;
  onPointerUp?: EventHandler<PointerEvent> | undefined;
  onPointerMove?: EventHandler<PointerEvent> | undefined;
  onPointerEnter?: EventHandler<PointerEvent> | undefined;
  onPointerLeave?: EventHandler<PointerEvent> | undefined;
  onPointerCancel?: EventHandler<PointerEvent> | undefined;
  onLostPointerCapture?: EventHandler<PointerEvent> | undefined;
  onTouchStart?: EventHandler<TouchEvent> | undefined;
  onTouchEnd?: EventHandler<TouchEvent> | undefined;
  onTouchMove?: EventHandler<TouchEvent> | undefined;
  onTouchCancel?: EventHandler<TouchEvent> | undefined;
  onKeyDown?: EventHandler<KeyboardEvent> | undefined;
  onKeyUp?: EventHandler<KeyboardEvent> | undefined;
  onFocus?: EventHandler<FocusEvent> | undefined;
  onBlur?: EventHandler<FocusEvent> | undefined;
  onFocusIn?: EventHandler<FocusEvent> | undefined;
  onFocusOut?: EventHandler<FocusEvent> | undefined;
  onInput?: EventHandler<Event> | undefined;
  onBeforeInput?: EventHandler<InputEvent> | undefined;
  onChange?: EventHandler<Event> | undefined;
  onSelect?: EventHandler<Event> | undefined;
  onSubmit?: EventHandler<SubmitEvent> | undefined;
  onReset?: EventHandler<Event> | undefined;
  onScroll?: EventHandler<Event> | undefined;
  onWheel?: EventHandler<WheelEvent> | undefined;
  onDragStart?: EventHandler<DragEvent> | undefined;
  onCompositionStart?: EventHandler<CompositionEvent> | undefined;
  onCompositionUpdate?: EventHandler<CompositionEvent> | undefined;
  onCompositionEnd?: EventHandler<CompositionEvent> | undefined;
  onAnimationStart?: EventHandler<AnimationEvent> | undefined;
  onAnimationEnd?: EventHandler<AnimationEvent> | undefined;
  onTransitionEnd?: EventHandler<TransitionEvent> | undefined;
  onCopy?: EventHandler<ClipboardEvent> | undefined;
  onCut?: EventHandler<ClipboardEvent> | undefined;
  onPaste?: EventHandler<ClipboardEvent> | undefined;
}

export interface CommonProps extends DOMEventProps {
  [key: `data-${string}`]: string | number | boolean | undefined;
  [key: `aria-${string}`]: string | number | boolean | undefined;
