/** One slot per element kind an adapter has to render. */
export interface PropTypes<T = unknown> {
  element: T;
  a: T;
  button: T;
  input: T;
  label: T;
  output: T;
  select: T;
  textarea: T;
  img: T;
  svg: T;
  circle: T;
  path: T;
}

export interface NormalizeProps<T extends PropTypes> {
  element(props: HTMLProps): T["element"];
  a(props: AnchorProps): T["a"];
  button(props: ButtonProps): T["button"];
  input(props: InputProps): T["input"];
  label(props: LabelProps): T["label"];
  output(props: OutputProps): T["output"];
  select(props: SelectProps): T["select"];
  textarea(props: TextareaProps): T["textarea"];
  img(props: ImgProps): T["img"];
  svg(props: SVGProps): T["svg"];
  circle(props: CircleProps): T["circle"];
  path(props: PathProps): T["path"];
}

/** Props as the adapter sees them, once the element kind stops mattering. */
export type AnyProps = Readonly<Record<string, unknown>>;

export function createNormalizer<T extends PropTypes>(
  transform: (props: AnyProps) => unknown,
): NormalizeProps<T> {
  const wrap = (props: object): never => transform(props as AnyProps) as never;
  return {
    element: wrap,
    a: wrap,
    button: wrap,
    input: wrap,
    label: wrap,
    output: wrap,
    select: wrap,
    textarea: wrap,
    img: wrap,
    svg: wrap,
    circle: wrap,
    path: wrap,
  };
}

/**
 * The contract every adapter implements (architecture.md: ~100-150 lines per
 * framework). There is a single interpreter in the core; frameworks only inject
 * their reactivity.
 *
 * `bindable` carries the controlled/uncontrolled semantics, and those semantics
 * are the behavioural parity promise of the library — so they are NOT reimplemented
 * per adapter. `createBindable` below is the one implementation; an adapter's
 * `bindable` supplies nothing but a mutable cell and delegates. The cell has to
 * notify on every write, an identical one included (see `Cell`), so a framework
 * primitive that drops those (useState, shallowRef, $state, signal) cannot be the
 * cell itself. The adapters here hold a plain variable and notify on each write.
 */

import { isDev } from "../utils/env";
import { warn } from "../utils/invariant";

export interface BindableParams<V> {
  readonly defaultValue?: V | undefined;
  /** Present (even as `null`) means controlled: the core reports, never writes. */
  readonly value?: V | undefined;
  readonly isEqual?: ((a: V, b: V) => boolean) | undefined;
  readonly onChange?: ((next: V, prev: V) => void) | undefined;
  readonly debugLabel?: string | undefined;
}

export interface Bindable<V> {
  /** The value the bindable was created with — survives later writes. */
  initial(): V;
  get(): V;
  set(next: V | ((prev: V) => V)): void;
  controlled(): boolean;
}

/**
 * The single reactive primitive an adapter has to provide. `set` notifies even
 * when the value is identical: a controlled write the parent absorbs — rejected,
 * or answered with the value it already held — reaches the adapter through
 * nothing else.
 */
export interface Cell<V> {
  get(): V;
  set(value: V): void;
}

export interface ReactivityAdapter {
  bindable<V>(init: () => BindableParams<V>): Bindable<V>;
  memo<V>(compute: () => V, deps: () => readonly unknown[]): () => V;
  track(deps: () => readonly unknown[], effect: VoidFunction): void;
  batch(fn: VoidFunction): void;
  onCleanup(dispose: VoidFunction): void;
}

/**
 * `init` is re-invoked on every read: that is how a controlled value stays fresh
 * when the consumer passes a new prop. Keep it allocation-cheap.
 */
export function createBindable<V>(
  init: () => BindableParams<V>,
  createCell: (initial: V) => Cell<V>,
): Bindable<V> {
  const first = init();
  const initialValue = (first.value ?? first.defaultValue) as V;
  const cell = createCell(initialValue);
  const controlledAtInit = first.value !== undefined;
  let warned = false;

  const controlled = (): boolean => {
    const isControlled = init().value !== undefined;
    if (isDev() && !warned && isControlled !== controlledAtInit) {
      warned = true;
      const label = first.debugLabel ?? "a bindable";
      const from = controlledAtInit ? "controlled" : "uncontrolled";
      warn(
        true,
        `${label} switched from ${from} to ${controlledAtInit ? "un" : ""}controlled. \
Decide once and keep it for the lifetime of the component.`,
      );
    }
    return isControlled;
  };

  const get = (): V => (controlled() ? (init().value as V) : cell.get());

  const set = (next: V | ((prev: V) => V)): void => {
    const params = init();
    const prev = get();
    const value = typeof next === "function" ? (next as (prev: V) => V)(prev) : next;
    const equal = params.isEqual ?? Object.is;
    // Without this guard a value that round-trips back identical re-emits onChange
    // forever (research/core.md §5, piège 1).
    if (equal(value, prev)) return;
    if (params.value === undefined) cell.set(value);
    params.onChange?.(value, prev);
    // A parent may answer with the value it already held, which a framework drops
    // without rendering; touching the cell is the only way the adapter hears of it.
    if (params.value !== undefined) cell.set(cell.get());
  };

  return { initial: (): V => initialValue, get, set, controlled };
}

/**
 * Every DOM read a machine performs goes through a `Scope`. Nothing in the core
 * ever touches `document` or `window` directly (architecture.md, règles dures):
 * that is what makes shadow roots, iframes and SSR work without a single special
 * case. The lookups stay lazy — a `Scope` can be built during render, it only
 * reaches for a document when an effect actually asks.
 *
 * The methods fall in two groups, and the split is the SSR contract:
 *
 * - **Render-safe** — `getRootNode`, `getById`, `getActiveElement`,
 *   `isActiveElement`. A machine reads these from its `watch` dependencies, and
 *   an adapter records those dependencies while it renders, so they are reached
 *   before any element exists. They answer "nothing" then, which is exactly what
 *   they already answer on the first client render, before the mount effect.
 * - **Effect-time** — `getDoc`, `getWin`, `getComputedStyle`. These exist to
 *   install listeners and to measure; they are only reachable after `start()`,
 *   which no server render performs. They throw rather than invent a document,
 *   with the same message `createInputSystem` uses, so the mistake names itself
 *   instead of surfacing as a bare `ReferenceError` from the wrong layer.
 */

import { invariant } from "../utils/invariant";

export type RootNode = Document | ShadowRoot;

/** `{ [part]: id }`, or `{ [`${part}:${key}`]: id }` for parts that repeat. */
export type PartIdOverrides = Readonly<Record<string, string | undefined>>;

export interface ScopeInit {
  readonly id: string;
  readonly ids?: PartIdOverrides | undefined;
  readonly getRootNode?: (() => RootNode) | undefined;
}

export interface Scope {
  readonly id: string;
  readonly ids: PartIdOverrides | undefined;
  /** `null` on the server, and on the client until the tree is mounted. */
  getRootNode(): RootNode | null;
  getDoc(): Document;
  getWin(): Window & typeof globalThis;
  getById<T extends Element = HTMLElement>(id: string): T | null;
  getActiveElement(): HTMLElement | null;
  isActiveElement(node: Element | null): boolean;
  getComputedStyle(node: Element): CSSStyleDeclaration;
}

export function createScope(init: ScopeInit): Scope {
  // `globalThis.document` rather than the bare identifier: on the server the
  // latter is a ReferenceError, not `undefined`, so there is nothing to fall
  // back from. This was the single global access left in the core, and the one
  // that stopped five components from rendering on a server.
  const getRootNode = (): RootNode | null => init.getRootNode?.() ?? globalThis.document ?? null;

  // A Document has a null `ownerDocument` and is its own document; a ShadowRoot
  // points at the one that owns it.
  const getDoc = (): Document => {
    const root = getRootNode();
    invariant(
      root !== null,
      "scope.getDoc() needs a document — call it from an effect, not during render or on the server",
    );
    return root.ownerDocument ?? (root as Document);
  };

  const getWin = (): Window & typeof globalThis => {
    const win = getDoc().defaultView;
    invariant(
      win !== null,
      "scope.getWin() needs a window — the document this scope belongs to has no view",
    );
    return win;
  };

  const getActiveElement = (): HTMLElement | null =>
    (getRootNode()?.activeElement as HTMLElement | null) ?? null;

  return {
    id: init.id,
    ids: init.ids,
    getRootNode,
    getDoc,
    getWin,
    getActiveElement,
    getById: <T extends Element = HTMLElement>(id: string): T | null =>
      (getRootNode()?.getElementById(id) as T | null) ?? null,
    isActiveElement: (node: Element | null): boolean =>
      node !== null && getActiveElement() === node,
    getComputedStyle: (node: Element): CSSStyleDeclaration => getWin().getComputedStyle(node),
  };
}

/**
 * The document's own root, for the effects that still have to resolve something
 * when no part of the component is rendered — a surface opened from a store has
 * no trigger and no anchor to read.
 *
 * Render-safe by construction: it goes through `getRootNode`, never `getDoc`,
 * which throws where there is no document (a plain node test, the server). The
 * answer there is `null`, and a caller that passes it on gets the same "nothing
 * to read" it already got from a missing part.
 */
export function getDocumentEl(scope: Scope): HTMLElement | null {
  const root = scope.getRootNode();
  if (root === null) return null;
  return (root.ownerDocument ?? (root as Document)).documentElement;
}

/**
 * The single interpreter. Zag duplicates it inside every framework's `useMachine`;
 * here there is one, parameterised by the injected `ReactivityAdapter` — that is
 * the "Zag v1 amélioré" decision of architecture.md.
 *
 * `createService` performs no side effect: it can run during an SSR render or a
 * React render pass. Effects and entry actions only happen in `start()`, and
 * `stop()` undoes exactly what `start()` did, in reverse — StrictMode's
 * mount/unmount/mount is therefore a no-op on state.
 */

import { isDev } from "../utils/env";
import { invariant, warn } from "../utils/invariant";
import type { Bindable, BindableParams, ReactivityAdapter } from "./reactivity";
import { createScope } from "./scope";
import type {
  ComputedAccessor,
  ContextAccessor,
  EffectCleanup,
  EventAccessor,
  EventOf,
  Machine,
  MachineParams,
  MachineSchema,
  PropAccessor,
  PropsOf,
  RefsAccessor,
  Service,
  ServiceRuntime,
  ServiceStatus,
  StateAccessor,
  StateNode,
  StateOf,
  TagOf,
  Transition,
  TransitionDefinition,
  TransitionMap,
} from "./types";

const INIT_EVENT = { type: "MACHINE.INIT" } as const;

/**
 * Spreading a consumer's props produces explicit `undefined`s, and
 * `{ dir: "ltr", ...props }` would then hand a machine `dir: undefined` — the
 * default silently erased. Stripped here so no machine has to defend itself.
 * The same object comes back when there is nothing to strip, which keeps the
 * memo above from invalidating on identity.
 */
function withoutUndefined<T extends object>(props: T): T {
  let found = false;
  for (const value of Object.values(props)) {
    if (value === undefined) {
      found = true;
      break;
    }
  }
  if (!found) return props;

  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(props)) {
    if (value !== undefined) result[key] = value;
  }
  return result as T;
}

export function createService<S extends MachineSchema>(
  machine: Machine<S>,
  reactivity: ReactivityAdapter,
  runtime: ServiceRuntime<S>,
): Service<S> {
  type Params = MachineParams<S>;

  const scope = createScope({
    id: runtime.id,
    ids: runtime.ids,
    getRootNode: runtime.getRootNode,
  });

  const states = machine.states as Readonly<Record<string, StateNode<S> | undefined>>;
  const guards = (machine.implementations?.guards ?? {}) as unknown as Record<
    string,
    ((params: Params) => boolean) | undefined
  >;
  const actionImpls = (machine.implementations?.actions ?? {}) as unknown as Record<
    string,
    ((params: Params) => void) | undefined
  >;
  const effectImpls = (machine.implementations?.effects ?? {}) as unknown as Record<
    string,
    ((params: Params) => EffectCleanup) | undefined
  >;
  const computedImpls = (machine.computed ?? {}) as unknown as Record<
    string,
    ((params: Params) => unknown) | undefined
  >;

  let status: ServiceStatus = "not-started";
  let currentEvent = INIT_EVENT as unknown as EventOf<S>;
  let previousEvent: EventOf<S> | undefined;
  let previousState: StateOf<S> | undefined;
  let transitionActions: readonly string[] | undefined;
  let machineEffects: VoidFunction | undefined;
  const queued: EventOf<S>[] = [];
  const stateEffects = new Map<string, VoidFunction>();

  // --- props ---------------------------------------------------------------

  const resolveProps = reactivity.memo<PropsOf<S>>(
    () => {
      const incoming = withoutUndefined(runtime.props()) as Partial<PropsOf<S>>;
      return machine.props?.({ props: incoming, scope }) ?? (incoming as PropsOf<S>);
    },
    () => [runtime.props()],
  );
  const prop = ((key: string) =>
    (resolveProps() as Record<string, unknown>)[key]) as unknown as PropAccessor<S>;

  // --- context -------------------------------------------------------------

  const contextBindables = (machine.context?.({
    prop,
    scope,
    bindable: <V>(init: () => BindableParams<V>): Bindable<V> => reactivity.bindable(init),
    getContext: () => context,
    getComputed: () => computed,
    getRefs: () => refs,
    getEvent: () => currentEvent,
  }) ?? {}) as unknown as Record<string, Bindable<unknown> | undefined>;

  const contextBindable = (key: string): Bindable<unknown> => {
    const value = contextBindables[key];
    invariant(value !== undefined, `unknown context key "${key}"`);
    return value;
  };

  const context = {
    get: (key: string) => contextBindable(key).get(),
    set: (key: string, value: unknown) => {
      contextBindable(key).set(value as never);
    },
    initial: (key: string) => contextBindable(key).initial(),
  } as unknown as ContextAccessor<S>;

  // --- refs ----------------------------------------------------------------

  const refsValue = (machine.refs?.({ prop, context, scope }) ?? {}) as Record<string, unknown>;
  const refs = {
    get: (key: string) => refsValue[key],
    set: (key: string, value: unknown) => {
      refsValue[key] = value;
    },
  } as unknown as RefsAccessor<S>;

  // --- computed ------------------------------------------------------------

  // Deliberately not memoised: a computed value must be a cheap pure read of
  // context/props, and a cache here would need invalidation the adapter cannot see.
  const computed = ((key: string) => {
    const compute = computedImpls[key];
    invariant(compute !== undefined, `unknown computed key "${key}"`);
    return compute(params);
  }) as unknown as ComputedAccessor<S>;

  // --- state ---------------------------------------------------------------

  // Hoisted so reading the state never allocates: `init` is called on every read.
  const stateParams: BindableParams<StateOf<S>> = {
    defaultValue: machine.initialState({ prop }),
    onChange: (next, prev) => runTransition(next, prev),
  };
  const state = reactivity.bindable<StateOf<S>>(() => stateParams);

  const stateAccessor: StateAccessor<S> = {
    get: (): StateOf<S> => state.get(),
    previous: (): StateOf<S> | undefined => previousState,
    matches: (...values: readonly StateOf<S>[]): boolean => values.includes(state.get()),
    hasTag: (tag: TagOf<S>): boolean =>
      (states[state.get()]?.tags as readonly string[] | undefined)?.includes(tag) ?? false,
  };

  const event: EventAccessor<S> = {
    current: (): EventOf<S> => currentEvent,
    previous: (): EventOf<S> | undefined => previousEvent,
  };

  const params: Params = {
    prop,
    context,
    computed,
    refs,
    scope,
    state: stateAccessor,
    send,
    get event(): EventOf<S> {
      return currentEvent;
    },
  };

  // --- transitions ---------------------------------------------------------

  function transitionsOf(
    map: TransitionMap<S> | undefined,
  ): Record<string, Transition<S> | undefined> {
    return (map ?? {}) as unknown as Record<string, Transition<S> | undefined>;
  }

  const globalOn = transitionsOf(machine.on);

  function evaluateGuard(guard: TransitionDefinition<S>["guard"]): boolean {
    if (guard === undefined) return true;
    if (typeof guard === "function") return guard(params);
    const negated = guard.startsWith("!");
    const name = negated ? guard.slice(1) : guard;
    const predicate = guards[name];
    invariant(predicate !== undefined, `unknown guard "${name}"`);
    const result = predicate(params);
    return negated ? !result : result;
  }

  function pickTransition(entry: Transition<S> | undefined): TransitionDefinition<S> | undefined {
    if (entry === undefined) return undefined;
    if (!Array.isArray(entry)) {
      const single = entry as TransitionDefinition<S>;
      return evaluateGuard(single.guard) ? single : undefined;
    }
    return (entry as readonly TransitionDefinition<S>[]).find((candidate) =>
      evaluateGuard(candidate.guard),
    );
  }

  function runActions(names: readonly string[] | undefined): void {
    if (names === undefined) return;
    for (const name of names) {
      const action = actionImpls[name];
      invariant(action !== undefined, `unknown action "${name}"`);
      action(params);
    }
  }

  function installEffects(names: readonly string[]): VoidFunction {
    const cleanups: VoidFunction[] = [];
    for (const name of names) {
      const effect = effectImpls[name];
      invariant(effect !== undefined, `unknown effect "${name}"`);
      const cleanup = effect(params);
      if (typeof cleanup === "function") cleanups.push(cleanup);
    }
    // Reverse order: the last effect installed is the first torn down, so an
    // effect can rely on everything set up before it still being alive.
    return () => {
      for (let index = cleanups.length - 1; index >= 0; index--) cleanups[index]?.();
    };
  }

  function enterState(value: string): void {
    const names = states[value]?.effects;
    if (names !== undefined && names.length > 0) {
      stateEffects.set(value, installEffects(names));
    }
    runActions(states[value]?.entry);
  }

  function exitState(value: string): void {
    const cleanup = stateEffects.get(value);
    if (cleanup !== undefined) {
      stateEffects.delete(value);
      cleanup();
    }
    runActions(states[value]?.exit);
  }

  function runTransition(next: StateOf<S>, prev: StateOf<S>): void {
    previousState = prev;
    exitState(prev);
    runActions(transitionActions);
    transitionActions = undefined;
    enterState(next);
  }

  function deliver(current: EventOf<S>): void {
    previousEvent = currentEvent;
    currentEvent = current;

    const value = state.get();
    const stateOn = transitionsOf(states[value]?.on);
    const transition = pickTransition(stateOn[current.type] ?? globalOn[current.type]);
    if (transition === undefined) return;

    const target = (transition.target ?? value) as StateOf<S>;
    if (target !== value) {
      transitionActions = transition.actions;
      state.set(target);
      return;
    }
    if (transition.reenter === true) {
      transitionActions = transition.actions;
      runTransition(target, value);
      return;
    }
    runActions(transition.actions);
  }

  function send(current: EventOf<S>): void {
    if (status === "not-started") {
      // Adapters connect handlers before their mount effect runs; dropping those
      // events would lose a click landing in the same tick as hydration.
      queued.push(current);
      return;
    }
    if (status === "stopped") {
      warn(isDev(), `event "${current.type}" was sent after the service stopped`);
      return;
    }
    reactivity.batch(() => deliver(current));
  }

  // --- lifecycle -----------------------------------------------------------

  const start = (): void => {
    if (status === "started") return;
    status = "started";
    reactivity.batch(() => {
      if (machine.effects !== undefined) machineEffects = installEffects(machine.effects);
      runActions(machine.entry);
      enterState(state.get());
      const pending = queued.splice(0, queued.length);
      for (const current of pending) deliver(current);
    });
  };

  const stop = (): void => {
    if (status !== "started") return;
    status = "stopped";
    reactivity.batch(() => {
      const cleanup = stateEffects.get(state.get());
      if (cleanup !== undefined) {
        stateEffects.delete(state.get());
        cleanup();
      }
      runActions(machine.exit);
      machineEffects?.();
      machineEffects = undefined;
    });
  };

  // Rebuilt rather than spread from `params`: spreading would freeze the `event`
  // getter to whatever the event was at construction time.
  machine.watch?.({
    prop,
    context,
    computed,
    refs,
    scope,
    state: stateAccessor,
    send,
    get event(): EventOf<S> {
      return currentEvent;
    },
    track: (deps, effect) => reactivity.track(deps, effect),
    action: runActions,
  });
  reactivity.onCleanup(stop);

  return {
    state: stateAccessor,
    context,
    prop,
    computed,
    refs,
    event,
    scope,
    send,
    start,
    stop,
    status: (): ServiceStatus => status,
  };
}

/**
 * Prop merging — the primitive every adapter's `asChild` / render-prop is built
 * on, and the reason a consumer can add their own `onClick` to a part without
 * losing the machine's.
 *
 * The ordering rule is the one Radix settled on, and it is worth stating because
 * it looks inconsistent at first: later arguments win for values, but their
 * handlers run FIRST. That is what makes `event.defaultPrevented` an actual veto
 * — the consumer's handler runs, and the library's handler, which is the one that
 * checks `defaultPrevented`, sees the decision (research/core.md §1.3).
 *
 * `class` accumulates instead of overriding, and `style` merges key by key, since
 * both are additive by nature. So do `data-scope` and `data-part`: composing two
 * parts onto one element is the whole point of `render`, and under "later wins"
 * the outer part's identity erased the inner one — a `<PopoverTrigger
 * render={<ButtonRoot/>}>` came out as the popover's trigger and nothing else, so
 * every rule in the button's sheet stopped matching. They are lists now, and this
 * is the one place the rule can live: `mergeProps` is never called with a part's
 * attributes inside `connect`, only by the adapters' composition, so every adapter
 * inherits it without knowing it exists.
 */

import type { AnyProps } from "./prop-types";

type Handler = (...args: unknown[]) => unknown;

function isHandler(key: string, value: unknown): value is Handler {
  return (
    typeof value === "function" &&
    key.length > 2 &&
    key.startsWith("on") &&
    key[2] === key[2]?.toUpperCase()
  );
}

function parseStyle(style: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const declaration of style.split(";")) {
    const separator = declaration.indexOf(":");
    if (separator === -1) continue;
    const property = declaration.slice(0, separator).trim();
    if (property !== "") result[property] = declaration.slice(separator + 1).trim();
  }
  return result;
}

/**
 * Deduplicated because these two are generated, not authored: the same identity
 * reaching the same element twice is a composition artefact, not an intent.
 */
function mergeTokens(existing: unknown, value: unknown): string {
  const tokens = new Set<string>();
  for (const source of [existing, value]) {
    if (typeof source !== "string") continue;
    for (const token of source.split(" ")) {
      if (token !== "") tokens.add(token);
    }
  }
  return [...tokens].join(" ");
}

function toStyleObject(style: unknown): Record<string, unknown> {
  if (typeof style === "string") return parseStyle(style);
  if (typeof style === "object" && style !== null) return { ...(style as Record<string, unknown>) };
  return {};
}

export function mergeProps(...list: readonly (AnyProps | null | undefined)[]): AnyProps {
  const result: Record<string, unknown> = {};

  for (const props of list) {
    if (props == null) continue;

    for (const [key, value] of Object.entries(props)) {
      const existing = result[key];

      if (isHandler(key, value) && isHandler(key, existing)) {
        // Reversed: the handler contributed later runs before the earlier one.
        result[key] = (...args: unknown[]): void => {
          value(...args);
          existing(...args);
        };
        continue;
      }

      if (key === "class" || key === "className") {
        const merged = [existing, value].filter(
          (entry) => typeof entry === "string" && entry !== "",
        );
        result[key] = merged.join(" ");
        continue;
      }

      if (key === "data-scope" || key === "data-part") {
        result[key] = mergeTokens(existing, value);
        continue;
      }

      if (key === "style") {
        result[key] = { ...toStyleObject(existing), ...toStyleObject(value) };
        continue;
      }

      // An explicit `undefined` never erases a value somebody else provided.
      if (value !== undefined) result[key] = value;
    }
  }

  return result;
}

/**
 * A machine is pure data: `createMachine` is a typed identity, nothing runs at
 * creation (research/core.md §1.1). This file is the whole type surface of that
 * data plus the accessors the interpreter hands to guards, actions and effects.
 *
 * The schema is a type-level bag. Each slot is optional and untyped in the base,
 * and resolved through the `*Of<S>` helpers, so a component declares only what it
 * has:
 *
 *   interface ToggleSchema extends MachineSchema {
 *     state: "off" | "on"
 *     props: ToggleMachineProps
 *     context: { pressed: boolean }
 *     event: { type: "TRIGGER.CLICK" } | { type: "PRESSED.SET"; pressed: boolean }
 *     action: "togglePressed" | "invokeOnChange"
 *   }
 */

import type { Bindable, BindableParams } from "./reactivity";
import type { PartIdOverrides, RootNode, Scope } from "./scope";

/**
 * Events are named `PART.VERB` — a hard rule (architecture.md), enforced by the
 * template literal rather than by review: `{ type: "click" }` does not typecheck.
 */
export interface EventObject {
  readonly type: `${string}.${string}`;
}

export interface MachineSchema {
  readonly state: string;
  readonly tag?: string;
  readonly props?: unknown;
  readonly context?: unknown;
  readonly computed?: unknown;
  readonly refs?: unknown;
  readonly event?: EventObject;
  readonly action?: string;
  readonly guard?: string;
  readonly effect?: string;
}

type Empty = Record<never, never>;

export type StateOf<S extends MachineSchema> = S["state"];
export type TagOf<S extends MachineSchema> = S extends { tag: infer T extends string } ? T : never;
export type PropsOf<S extends MachineSchema> = S extends { props: infer P } ? P : Empty;
export type ContextOf<S extends MachineSchema> = S extends { context: infer C } ? C : Empty;
export type ComputedOf<S extends MachineSchema> = S extends { computed: infer C } ? C : Empty;
export type RefsOf<S extends MachineSchema> = S extends { refs: infer R } ? R : Empty;
export type EventOf<S extends MachineSchema> = S extends { event: infer E extends EventObject }
  ? E
  : EventObject;
export type ActionOf<S extends MachineSchema> = S extends { action: infer A extends string }
  ? A
  : never;
export type GuardOf<S extends MachineSchema> = S extends { guard: infer G extends string }
  ? G
  : never;
export type EffectOf<S extends MachineSchema> = S extends { effect: infer E extends string }
  ? E
  : never;

export type BindableMap<C> = { [K in keyof C]: Bindable<C[K]> };

// --- accessors -------------------------------------------------------------

export type PropAccessor<S extends MachineSchema> = <K extends keyof PropsOf<S>>(
  key: K,
) => PropsOf<S>[K];

export interface ContextAccessor<S extends MachineSchema> {
  get<K extends keyof ContextOf<S>>(key: K): ContextOf<S>[K];
  set<K extends keyof ContextOf<S>>(
    key: K,
    value: ContextOf<S>[K] | ((prev: ContextOf<S>[K]) => ContextOf<S>[K]),
  ): void;
  initial<K extends keyof ContextOf<S>>(key: K): ContextOf<S>[K];
}

export type ComputedAccessor<S extends MachineSchema> = <K extends keyof ComputedOf<S>>(
  key: K,
) => ComputedOf<S>[K];

export interface RefsAccessor<S extends MachineSchema> {
  get<K extends keyof RefsOf<S>>(key: K): RefsOf<S>[K];
  set<K extends keyof RefsOf<S>>(key: K, value: RefsOf<S>[K]): void;
}

export interface StateAccessor<S extends MachineSchema> {
  get(): StateOf<S>;
  matches(...values: readonly StateOf<S>[]): boolean;
  hasTag(tag: TagOf<S>): boolean;
  previous(): StateOf<S> | undefined;
}

export interface EventAccessor<S extends MachineSchema> {
  current(): EventOf<S>;
  previous(): EventOf<S> | undefined;
}

// --- parameter objects -----------------------------------------------------

/** What guards, actions, effects and computed values receive. */
export interface MachineParams<S extends MachineSchema> {
  readonly prop: PropAccessor<S>;
  readonly context: ContextAccessor<S>;
  readonly computed: ComputedAccessor<S>;
  readonly refs: RefsAccessor<S>;
  readonly state: StateAccessor<S>;
  readonly event: EventOf<S>;
  readonly scope: Scope;
  send(event: EventOf<S>): void;
}

export interface PropsParams<S extends MachineSchema> {
  readonly props: Partial<PropsOf<S>>;
  readonly scope: Scope;
}

export interface ContextParams<S extends MachineSchema> {
  readonly prop: PropAccessor<S>;
  readonly scope: Scope;
  bindable<V>(init: () => BindableParams<V>): Bindable<V>;
  getContext(): ContextAccessor<S>;
  getComputed(): ComputedAccessor<S>;
  getRefs(): RefsAccessor<S>;
  getEvent(): EventOf<S>;
}

export interface RefsParams<S extends MachineSchema> {
  readonly prop: PropAccessor<S>;
  readonly context: ContextAccessor<S>;
  readonly scope: Scope;
}

export interface InitialStateParams<S extends MachineSchema> {
  readonly prop: PropAccessor<S>;
}

export interface WatchParams<S extends MachineSchema> extends MachineParams<S> {
  track(deps: () => readonly unknown[], effect: VoidFunction): void;
  action(actions: readonly ActionOf<S>[]): void;
}

// --- transitions -----------------------------------------------------------

export type GuardExpression<S extends MachineSchema> =
  | GuardOf<S>
  | `!${GuardOf<S>}`
  | ((params: MachineParams<S>) => boolean);

export interface TransitionDefinition<S extends MachineSchema> {
  readonly target?: StateOf<S>;
  readonly guard?: GuardExpression<S>;
  readonly actions?: readonly ActionOf<S>[];
  /** Re-run exit and entry even when the target is the current state. */
  readonly reenter?: boolean;
}

export type Transition<S extends MachineSchema> =
  | TransitionDefinition<S>
  | readonly TransitionDefinition<S>[];

export type TransitionMap<S extends MachineSchema> = {
  readonly [E in EventOf<S>["type"]]?: Transition<S>;
};

export interface StateNode<S extends MachineSchema> {
  readonly tags?: readonly TagOf<S>[];
  readonly entry?: readonly ActionOf<S>[];
  readonly exit?: readonly ActionOf<S>[];
  readonly effects?: readonly EffectOf<S>[];
  readonly on?: TransitionMap<S>;
}

// --- the machine -----------------------------------------------------------

/**
 * An effect returns its teardown, or nothing at all. `void` and not `undefined`:
 * with `undefined` every effect without a cleanup would have to `return undefined`
 * explicitly.
 */
// biome-ignore lint/suspicious/noConfusingVoidType: see above — this is the React `useEffect` shape.
export type EffectCleanup = VoidFunction | void;

export interface MachineImplementations<S extends MachineSchema> {
  readonly guards?: Readonly<Record<GuardOf<S>, (params: MachineParams<S>) => boolean>>;
  readonly actions?: Readonly<Record<ActionOf<S>, (params: MachineParams<S>) => void>>;
  /** The interpreter runs the teardowns in reverse order of installation. */
  readonly effects?: Readonly<Record<EffectOf<S>, (params: MachineParams<S>) => EffectCleanup>>;
}

export interface MachineConfig<S extends MachineSchema> {
  props?(params: PropsParams<S>): PropsOf<S>;
  context?(params: ContextParams<S>): BindableMap<ContextOf<S>>;
  refs?(params: RefsParams<S>): RefsOf<S>;
  readonly computed?: {
    readonly [K in keyof ComputedOf<S>]: (params: MachineParams<S>) => ComputedOf<S>[K];
  };
  watch?(params: WatchParams<S>): void;
  /** Pure function of the props — this is what makes SSR render the right markup. */
  initialState(params: InitialStateParams<S>): StateOf<S>;
  readonly entry?: readonly ActionOf<S>[];
  readonly exit?: readonly ActionOf<S>[];
  readonly effects?: readonly EffectOf<S>[];
  readonly on?: TransitionMap<S>;
  readonly states: Readonly<Record<StateOf<S>, StateNode<S>>>;
  readonly implementations?: MachineImplementations<S>;
}

export type Machine<S extends MachineSchema> = MachineConfig<S>;

// --- the service -----------------------------------------------------------

export type ServiceStatus = "not-started" | "started" | "stopped";

/**
 * What an adapter hands in, as opposed to what a machine sees. An explicit
 * `undefined` is allowed here because that is what spreading a consumer's props
 * produces; the interpreter strips those before applying the machine's defaults,
 * so `{ dir: undefined }` cannot erase `dir: "ltr"`.
 */
export type PropsInput<S extends MachineSchema> = {
  [K in keyof PropsOf<S>]?: PropsOf<S>[K] | undefined;
};

export interface ServiceRuntime<S extends MachineSchema> {
  readonly id: string;
  readonly ids?: PartIdOverrides | undefined;
  readonly getRootNode?: (() => RootNode) | undefined;
  props(): PropsInput<S>;
}

export interface Service<S extends MachineSchema> {
  readonly state: StateAccessor<S>;
  readonly context: ContextAccessor<S>;
  readonly prop: PropAccessor<S>;
  readonly computed: ComputedAccessor<S>;
  readonly refs: RefsAccessor<S>;
  readonly event: EventAccessor<S>;
  readonly scope: Scope;
  send(event: EventOf<S>): void;
  /** Installs effects and entry actions. Idempotent, and symmetric with `stop`. */
  start(): void;
  stop(): void;
  status(): ServiceStatus;
}

/**
 * Anchor positioning, written here rather than taken from Floating UI: it is the
 * single biggest dependency Zag carries, and the budget for it is 3 kB (CDC D7).
 *
 * The whole thing is a pure function of three rectangles. No DOM, no measuring,
 * no scheduling — those live in `track-position`. That is what makes flip, shift
 * and arrow placement testable as arithmetic instead of as screenshots.
 *
 * The input placement is logical — `start` is the left edge in LTR and the right
 * edge in RTL — and everything returned is physical, because that is what the
 * arrow, the transform origin and `data-side` / `data-align` all need.
 */

import type { Direction, Rect } from "../types";

export type Side = "top" | "right" | "bottom" | "left";
export type Align = "start" | "center" | "end";
export type Placement = Side | `${Side}-${Align}`;

export interface PositionOptions {
  readonly placement?: Placement | undefined;
  /** Distance from the anchor along the main axis. */
  readonly gap?: number | undefined;
  /** Nudge along the cross axis, before any shifting. */
  readonly offset?: number | undefined;
  /** Flip to the opposite side when the preferred one overflows. */
  readonly flip?: boolean | undefined;
  /**
   * Where to go when the preferred placement does not fit, in order of
   * preference. Left unset the list is the opposite side alone, which is the only
   * thing this function knew how to try before — so a caller that asks for nothing
   * gets the answer it always got.
   *
   * The list is what lets a surface leave its **axis**: a submenu that fits on
   * neither side has no opposite left to try, and without a perpendicular
   * candidate it stays where it does not fit and is cropped by the stylesheet's
   * own `max-inline-size` instead — a position error turned into a width error.
   */
  readonly fallbackPlacements?: readonly Placement[] | undefined;
  /** Slide along the cross axis to stay inside the boundary. */
  readonly shift?: boolean | undefined;
  /** Breathing room kept between the surface and the boundary. */
  readonly padding?: number | undefined;
  readonly arrowSize?: number | undefined;
  /** Keeps the arrow away from a rounded corner. */
  readonly arrowPadding?: number | undefined;
  /**
   * Floor the surface at the anchor's width. A **floor**, never an identity: a
   * surface that needs more room keeps its own width, because clamping it down
   * is how a select ends up ellipsising every row it was opened to show.
   */
  readonly matchWidth?: boolean | undefined;
  readonly dir?: Direction | undefined;
}

export interface ArrowPosition {
  readonly x: number;
  readonly y: number;
}

export interface PositionResult {
  readonly x: number;
  readonly y: number;
  readonly placement: Placement;
  readonly side: Side;
  readonly align: Align;
  readonly arrow: ArrowPosition | null;
  /** For `--sui-transform-origin`: growth starts at the anchor. */
  readonly transformOrigin: string;
  /**
   * The width to write on the surface, and `null` whenever it already has the
   * one it should keep — `matchWidth` off, or a surface wider than its anchor.
   */
  readonly width: number | null;
  /** True when the surface had to leave its preferred side. */
  readonly flipped: boolean;
  /**
   * Room left for the surface once it sits on `side`, main axis measured from the
   * anchor edge and cross axis from the boundary. Published as
   * `--sui-available-width` / `--sui-available-height` so a surface taller than
   * its room can cap itself in CSS — which it cannot do alone, the stylesheet
   * having no idea where the anchor is.
   */
  readonly availableWidth: number;
  readonly availableHeight: number;
}

const OPPOSITE: Readonly<Record<Side, Side>> = {
  top: "bottom",
  bottom: "top",
  left: "right",
  right: "left",
};

function parsePlacement(placement: Placement): { side: Side; align: Align } {
  const [side, align = "center"] = placement.split("-") as [Side, Align | undefined];
  return { side, align };
}

function isVertical(side: Side): boolean {
  return side === "top" || side === "bottom";
}

/** `start`/`end` are logical; only the horizontal axis flips in RTL. */
function resolveAlign(align: Align, side: Side, dir: Direction): Align {
  if (align === "center" || !isVertical(side) || dir !== "rtl") return align;
  return align === "start" ? "end" : "start";
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

function coordsFor(
  anchor: Rect,
  floating: Rect,
  side: Side,
  align: Align,
  gap: number,
  offset: number,
): { x: number; y: number } {
  if (isVertical(side)) {
    const y = side === "top" ? anchor.y - floating.height - gap : anchor.y + anchor.height + gap;
    const x =
      align === "start"
        ? anchor.x
        : align === "end"
          ? anchor.x + anchor.width - floating.width
          : anchor.x + (anchor.width - floating.width) / 2;
    return { x: x + offset, y };
  }

  const x = side === "left" ? anchor.x - floating.width - gap : anchor.x + anchor.width + gap;
  const y =
    align === "start"
      ? anchor.y
      : align === "end"
        ? anchor.y + anchor.height - floating.height
        : anchor.y + (anchor.height - floating.height) / 2;
  return { x, y: y + offset };
}

/** How far past each edge of the boundary the surface would sit. Positive overflows. */
function overflowOn(
  side: Side,
  x: number,
  y: number,
  floating: Rect,
  boundary: Rect,
  padding: number,
): number {
  switch (side) {
    case "top":
      return boundary.y + padding - y;
    case "bottom":
      return y + floating.height - (boundary.y + boundary.height - padding);
    case "left":
      return boundary.x + padding - x;
    case "right":
      return x + floating.width - (boundary.x + boundary.width - padding);
  }
}

/**
 * Room the surface has once it is committed to `side`. The main axis is measured
 * from the anchor edge outwards, because that is the space the surface actually
 * grows into; the cross axis is the boundary itself, because shifting can use all
 * of it. Never negative: an anchor already outside its boundary means no room,
 * not room owed.
 */
function availableSpace(
  side: Side,
  anchor: Rect,
  boundary: Rect,
  gap: number,
  padding: number,
): { width: number; height: number } {
  const crossWidth = Math.max(0, boundary.width - padding * 2);
  const crossHeight = Math.max(0, boundary.height - padding * 2);

  switch (side) {
    case "top":
      return { width: crossWidth, height: Math.max(0, anchor.y - gap - (boundary.y + padding)) };
    case "bottom":
      return {
        width: crossWidth,
        height: Math.max(
          0,
          boundary.y + boundary.height - padding - (anchor.y + anchor.height + gap),
        ),
      };
    case "left":
      return { width: Math.max(0, anchor.x - gap - (boundary.x + padding)), height: crossHeight };
    case "right":
      return {
        width: Math.max(0, boundary.x + boundary.width - padding - (anchor.x + anchor.width + gap)),
        height: crossHeight,
      };
  }
}

function transformOriginFor(side: Side, align: Align): string {
  if (isVertical(side)) {
    const y = side === "top" ? "bottom" : "top";
    const x = align === "center" ? "center" : align === "start" ? "left" : "right";
    return `${x} ${y}`;
  }
  const x = side === "left" ? "right" : "left";
  const y = align === "center" ? "center" : align === "start" ? "top" : "bottom";
  return `${x} ${y}`;
}

/**
 * The origin once the cross axis has been clamped, where the alignment keyword no
 * longer describes anything: a surface shifted 134px away from its trigger still
 * said `left top`, so it grew out of a corner nowhere near the thing that opened
 * it. Measured against the anchor's centre and clamped into the surface, so the
 * growth still starts at the anchor — which is the whole promise of this field.
 */
function shiftedOriginFor(side: Side, anchor: Rect, x: number, y: number, floating: Rect): string {
  if (isVertical(side)) {
    const cross = clamp(anchor.x + anchor.width / 2 - x, 0, floating.width);
    return `${Math.round(cross)}px ${side === "top" ? "bottom" : "top"}`;
  }
  const cross = clamp(anchor.y + anchor.height / 2 - y, 0, floating.height);
  return `${side === "left" ? "right" : "left"} ${Math.round(cross)}px`;
}

export function computePosition(
  anchor: Rect,
  floating: Rect,
  boundary: Rect,
  options: PositionOptions = {},
): PositionResult {
  const { side: preferredSide, align: rawAlign } = parsePlacement(options.placement ?? "bottom");
  const dir = options.dir ?? "ltr";
  const align = resolveAlign(rawAlign, preferredSide, dir);
  const gap = options.gap ?? 0;
  const offset = options.offset ?? 0;
  const padding = options.padding ?? 0;
  // A floor, and it used to be an identity — which is the defect it was written
  // over: a 190px list clamped onto a 140px trigger truncated all five of its
  // rows and both of its headings. Native desktop menus answer flatly against the
  // identity too: they are 18-40px wider than their buttons, and
  // three different button widths sit under one identical menu width.
  //
  // `sized` stays max(anchor, floating) in both branches — the anchor's width
  // when the surface is narrower, the surface's own when it is not — so flip,
  // shift and the arrow clamp see exactly the box they always did.
  const width = options.matchWidth === true && floating.width < anchor.width ? anchor.width : null;
  const sized = width === null ? floating : { ...floating, width };

  let side = preferredSide;
  let placed = align;
  let { x, y } = coordsFor(anchor, sized, side, placed, gap, offset);

  if (options.flip !== false) {
    let overflow = overflowOn(side, x, y, sized, boundary, padding);
    if (overflow > 0) {
      const fallbacks =
        options.fallbackPlacements === undefined
          ? [{ side: OPPOSITE[side], align }]
          : options.fallbackPlacements.map((placement) => {
              const parsed = parsePlacement(placement);
              return { side: parsed.side, align: resolveAlign(parsed.align, parsed.side, dir) };
            });

      // Each candidate in turn, and the first that fits wins. Only ever moving to
      // something *better* is what keeps the old single-candidate behaviour intact:
      // flipping into a worse overflow is how a popover ends up half off-screen at
      // the top instead of at the bottom.
      for (const candidate of fallbacks) {
        const coords = coordsFor(anchor, sized, candidate.side, candidate.align, gap, offset);
        const candidateOverflow = overflowOn(
          candidate.side,
          coords.x,
          coords.y,
          sized,
          boundary,
          padding,
        );
        if (candidateOverflow < overflow) {
          side = candidate.side;
          placed = candidate.align;
          x = coords.x;
          y = coords.y;
          overflow = candidateOverflow;
        }
        if (overflow <= 0) break;
      }
    }
  }

  // Whether the cross axis had to be clamped, which is what makes the alignment
  // keyword stop describing where the surface actually is.
  let shifted = false;
  if (options.shift !== false) {
    if (isVertical(side)) {
      const min = boundary.x + padding;
      const max = boundary.x + boundary.width - padding - sized.width;
      const next = max >= min ? clamp(x, min, max) : min;
      shifted = next !== x;
      x = next;
    } else {
      const min = boundary.y + padding;
      const max = boundary.y + boundary.height - padding - sized.height;
      const next = max >= min ? clamp(y, min, max) : min;
      shifted = next !== y;
      y = next;
    }
  }

  const arrowSize = options.arrowSize ?? 0;
  let arrow: ArrowPosition | null = null;
  if (arrowSize > 0) {
    const arrowPadding = options.arrowPadding ?? 0;
    if (isVertical(side)) {
      // Centred on the anchor, then kept off the rounded corners.
      const centre = anchor.x + anchor.width / 2 - x - arrowSize / 2;
      const max = sized.width - arrowSize - arrowPadding;
      arrow = { x: max >= arrowPadding ? clamp(centre, arrowPadding, max) : centre, y: 0 };
    } else {
      const centre = anchor.y + anchor.height / 2 - y - arrowSize / 2;
      const max = sized.height - arrowSize - arrowPadding;
      arrow = { x: 0, y: max >= arrowPadding ? clamp(centre, arrowPadding, max) : centre };
    }
  }

  const available = availableSpace(side, anchor, boundary, gap, padding);

  return {
    x: Math.round(x),
    y: Math.round(y),
    placement: placed === "center" ? side : `${side}-${placed}`,
    side,
    align: placed,
    arrow,
    transformOrigin: shifted
      ? shiftedOriginFor(side, anchor, x, y, sized)
      : transformOriginFor(side, placed),
    width,
    flipped: side !== preferredSide,
    availableWidth: available.width,
    availableHeight: available.height,
  };
}

/**
 * The DOM half of the positioner: measure, apply, and keep it right.
 *
 * Everything that decides *where* lives in `compute-position`; this file only
 * reads rects and writes styles. Position is written as a `translate` rather than
 * as `top`/`left` so a move never triggers layout, and the custom properties the
 * CSS contract names (`--sui-transform-origin`, `--sui-anchor-width`,
 * `--sui-arrow-x/y`) are published here.
 *
 * Auto-update watches what actually moves the anchor: its own size, the surface's
 * size, and scrolling on every scrollable ancestor. A rAF polling loop would be
 * simpler and would also keep a phone's radio awake for a menu nobody is
 * touching.
 */

import { addDomEvent } from "../dom/event";
import { observeResize } from "../dom/observers";
import { raf } from "../dom/raf";
import type { Rect } from "../types";
import { computePosition, type PositionOptions, type PositionResult } from "./compute-position";

export interface TrackPositionOptions extends PositionOptions {
  readonly strategy?: "absolute" | "fixed" | undefined;
  readonly onPositioned?: ((result: PositionResult) => void) | undefined;
  /** The clipping box. Defaults to the viewport. */
  readonly boundary?: (() => Rect) | undefined;
  readonly arrowNode?: (() => HTMLElement | null | undefined) | undefined;
  /**
   * Anchor to a rect rather than to the element's own box — a caret, a text
   * range, a point on a canvas. When given it replaces the anchor's measurement,
   * and `anchor` becomes the element the surface still *watches*: pass the scroll
   * container so resize and scroll keep updating. Passing `null` for `anchor` is
   * allowed and costs exactly that tracking — only a window resize repositions.
   */
  readonly getAnchorRect?: (() => Rect) | undefined;
  /**
   * While this returns true the surface keeps the geometry it already has.
   *
   * For the window between "the machine has decided to close" and "the effect
   * that installed this tracker is torn down" — the select's selection blink is
   * the one that exists today. The commit rewrites the trigger's caption, the
   * trigger resizes under a surface that is still open and fully opaque, and
   * re-fitting it there is a jump the eye reads as a bug rather than as a close.
   */
  readonly paused?: (() => boolean) | undefined;
}

const NOOP: VoidFunction = () => {};

function rectOf(node: Element): Rect {
  const { x, y, width, height } = node.getBoundingClientRect();
  return { x, y, width, height };
}

function viewportRect(win: Window): Rect {
  return { x: 0, y: 0, width: win.innerWidth, height: win.innerHeight };
}

/** Every ancestor that can scroll, plus the window — those are the things that move it. */
function scrollParents(node: Element): (Element | Window)[] {
  const win = node.ownerDocument.defaultView;
  const parents: (Element | Window)[] = [];
  let current: Element | null = node.parentElement;
  while (current !== null && current !== node.ownerDocument.body) {
    const style = win?.getComputedStyle(current);
    const overflow = `${style?.overflow ?? ""}${style?.overflowX ?? ""}${style?.overflowY ?? ""}`;
    if (/auto|scroll|overlay|hidden/.test(overflow)) parents.push(current);
    current = current.parentElement;
  }
  if (win !== null && win !== undefined) parents.push(win);
  return parents;
}

export function trackPosition(
  anchor: HTMLElement | null | undefined,
  floating: HTMLElement | null | undefined,
  options: TrackPositionOptions = {},
): VoidFunction {
  const win = floating?.ownerDocument.defaultView;
  if (floating == null || win === null || win === undefined) return NOOP;

  const anchorEl = anchor ?? null;
  const readAnchorRect =
    options.getAnchorRect ?? (anchorEl !== null ? () => rectOf(anchorEl) : null);
  if (readAnchorRect === null) return NOOP;

  // **`fixed`, and `absolute` is the trap it replaced.** Everything computed below
  // is in viewport coordinates — `getBoundingClientRect` for the anchor, the
  // window box for the boundary — and it is written as a translate from
  // `top: 0; left: 0`. Under `absolute` in a portal with no positioned ancestor,
  // that origin is the *document*, so the surface landed exactly `-scrollY` away
  // from its anchor: correct on an unscrolled page and off by the whole scroll
  // offset on any other. Under `fixed` the containing block is the viewport, which
  // is the space the numbers were already in.
  //
  // The remaining exposure is an ancestor that establishes a containing block for
  // fixed descendants — `transform`, `filter`, `backdrop-filter`, `contain: paint`
  // — and this library paints glass with `backdrop-filter`. Portalling to the body
  // is what keeps a surface clear of one; a surface rendered inside glass has to
  // ask for `absolute` and accept the document-origin arithmetic that comes with it.
  const strategy = options.strategy ?? "fixed";
  let scheduled: VoidFunction | undefined;
  // Whether the *last* pass wrote a width, so the reset below can take back its
  // own answer without ever removing one the author set inline.
  let wroteWidth = false;

  const apply = (): void => {
    if (options.paused?.() === true) return;
    const anchorRect = readAnchorRect();
    const boundary = options.boundary?.() ?? viewportRect(win);

    // Taken out of flow *before* it is measured, and the order is the whole point:
    // a surface still in flow is a block-level box as wide as its container, and
    // that width goes straight into the shift clamp — `max` falls below `min` and
    // the surface is pinned to `padding`, hard against the boundary's edge,
    // whatever the placement asked for. Measuring the box in the layout mode it
    // will actually be laid out in costs one style recalc on the first pass and
    // nothing after for these three, which never change again.
    floating.style.position = strategy;
    floating.style.top = "0";
    floating.style.left = "0";
    // The width does change, so it is given back before the measurement: left in
    // place, `rectOf` below would return the answer of the *previous* pass instead
    // of the surface's natural width, and a `matchWidth` surface could never
    // shrink again once its anchor narrowed. One synchronous block, no frame
    // painted in between — the clear costs a recalc, never a flash.
    if (wroteWidth) {
      floating.style.removeProperty("width");
      wroteWidth = false;
    }

    const result = computePosition(anchorRect, rectOf(floating), boundary, options);

    // Translate, not top/left: moving a surface must not cost a layout pass.
    floating.style.transform = `translate3d(${result.x}px, ${result.y}px, 0)`;
    floating.style.setProperty("--sui-transform-origin", result.transformOrigin);
    floating.style.setProperty("--sui-anchor-width", `${anchorRect.width}px`);
    floating.style.setProperty("--sui-anchor-height", `${anchorRect.height}px`);
    floating.style.setProperty("--sui-available-width", `${result.availableWidth}px`);
    floating.style.setProperty("--sui-available-height", `${result.availableHeight}px`);
    floating.dataset["side"] = result.side;
    floating.dataset["align"] = result.align;
    if (result.width !== null) {
      floating.style.width = `${result.width}px`;
      wroteWidth = true;
    }

    const arrowNode = options.arrowNode?.();
    if (arrowNode != null && result.arrow !== null) {
      arrowNode.style.setProperty("--sui-arrow-x", `${result.arrow.x}px`);
      arrowNode.style.setProperty("--sui-arrow-y", `${result.arrow.y}px`);
    }

    options.onPositioned?.(result);
  };

  // Coalesced: a resize and a scroll in the same frame are one reposition.
  const schedule = (): void => {
    scheduled?.();
    scheduled = raf(win, () => {
      scheduled = undefined;
      apply();
    });
  };

  apply();

  const disposers: VoidFunction[] = [observeResize(floating, schedule)];
  // A virtual anchor with no element has nothing to observe and nothing to hang a
  // scroll listener on; the window still moves it.
  if (anchorEl !== null) {
    disposers.push(observeResize(anchorEl, schedule));
    for (const parent of scrollParents(anchorEl)) {
      disposers.push(addDomEvent(parent, "scroll", schedule, { passive: true, capture: true }));
    }
  }
  disposers.push(addDomEvent(win, "resize", schedule, { passive: true }));

  return () => {
    scheduled?.();
    for (let index = disposers.length - 1; index >= 0; index--) disposers[index]?.();
  };
}

/**
 * Keeps a node mounted until its exit animation has actually finished.
 *
 * `data-state="closed"` alone is not enough: the adapter would unmount on the
 * same tick and the animation would never be seen (research/core.md §5, piège 7).
 * So the state is applied, one frame is allowed to pass for the transition to
 * start, and `getAnimations()` is asked what is running.
 *
 * The timeout is not paranoia. A tab that goes to the background never fires
 * `finish`, and neither does an animation whose element gets `display: none` mid
 * flight — without a ceiling the node stays mounted for the rest of the session.
 */

export interface PresenceOptions {
  /** Fired when the node may leave the DOM. */
  onExitComplete(): void;
  /** Ceiling on how long an exit is allowed to take. */
  readonly timeout?: number | undefined;
  /** Skip the wait entirely — reduced motion, or a first render. */
  readonly immediate?: boolean | undefined;
}

export interface Presence {
  /** `present` is the machine's open state; `node` is the surface, if mounted. */
  setPresent(present: boolean, node: HTMLElement | null | undefined): void;
  isPresent(): boolean;
  /** True while an exit animation is still running. */
  isExiting(): boolean;
  destroy(): void;
}

const DEFAULT_TIMEOUT = 1000;

/**
 * Endless animations are dropped rather than awaited. A spinner still turning
 * inside the surface has a `finished` that never settles, so waiting on it would
 * turn every close into the full timeout ceiling.
 */
function finite(animations: readonly Animation[]): Animation[] {
  return animations.filter(
    (animation) => animation.effect?.getComputedTiming().iterations !== Number.POSITIVE_INFINITY,
  );
}

/**
 * The node's own animations decide when the exit is over; the subtree answers
 * only when the node itself has none.
 *
 * Reading the subtree unconditionally was the first shape of this, and it cannot
 * tell an exit from anything else finite that happens to be running inside the
 * surface at the moment it closes — a close trigger releasing its press spring
 * outlasts the surface's own fade by twice, and the node would leave on a
 * stranger's clock. Filtering the infinite ones was never the whole hazard: it
 * only stopped a spinner from pinning the node to the ceiling.
 *
 * The fallback is what keeps the case the subtree read was written for: an exit
 * is not always on the surface itself — a sheet that slides its own inner panel
 * animates a descendant, and asking the content node alone would measure that
 * exit as zero-length and cut it on the very next frame. Every surface this
 * library ships today animates its own content node, so the fallback is for a
 * shape that does not exist yet rather than one being taken away.
 */
function exitAnimations(node: HTMLElement): Animation[] {
  const own = finite(node.getAnimations?.() ?? []);
  if (own.length > 0) return own;
  return finite(node.getAnimations?.({ subtree: true }) ?? []);
}

export function createPresence(options: PresenceOptions): Presence {
  let present = false;
  let exiting = false;
  let generation = 0;
  let cancelFrame: VoidFunction | undefined;
  let cancelTimeout: VoidFunction | undefined;

  const stopWaiting = (): void => {
    cancelFrame?.();
    cancelFrame = undefined;
    cancelTimeout?.();
    cancelTimeout = undefined;
  };

  const complete = (): void => {
    stopWaiting();
    exiting = false;
    present = false;
    options.onExitComplete();
  };

  return {
    setPresent(next: boolean, node: HTMLElement | null | undefined): void {
      generation += 1;
      const current = generation;

      if (next) {
        // Re-opening mid-exit: cancel the teardown, the node never left.
        stopWaiting();
        exiting = false;
        present = true;
        return;
      }

      if (!present) return;
      const win = node?.ownerDocument.defaultView;
      if (options.immediate === true || node == null || win === null || win === undefined) {
        complete();
        return;
      }

      exiting = true;
      // One frame: the transition triggered by `data-state="closed"` does not
      // exist yet at the moment the attribute is written.
      const frame = win.requestAnimationFrame(() => {
        if (current !== generation) return;
        cancelFrame = undefined;
        const animations = exitAnimations(node);
        if (animations.length === 0) {
          complete();
          return;
        }
        void Promise.allSettled(animations.map((animation) => animation.finished)).then(() => {
          if (current === generation) complete();
        });
      });
      cancelFrame = () => win.cancelAnimationFrame(frame);

      const timer = win.setTimeout(() => {
        if (current === generation) complete();
      }, options.timeout ?? DEFAULT_TIMEOUT);
      cancelTimeout = () => win.clearTimeout(timer);
    },

    isPresent: (): boolean => present || exiting,
    isExiting: (): boolean => exiting,
    destroy(): void {
      generation += 1;
      stopWaiting();
      present = false;
      exiting = false;
    },
  };
}

/**
 * The reference `ReactivityAdapter`: no framework, no scheduler, no dependency.
 *
 * It exists to let the core be tested the way the exit criterion of Phase 2
 * demands: a machine driving real DOM attributes with no framework in the room.
 *
 * Propagation is synchronous and coalesced by `batch`: one event in, one
 * notification out. An adapter that needs microtask coalescing wraps this rather
 * than forking it.
 *
 * **It is not the store `@standarui/vanilla` builds on**, which this header
 * claimed until the vanilla adapter was written and measured the order. `flush`
 * runs the trackers first and notifies its listeners after, so a listener that
 * paints the DOM paints it *after* `watch` has already moved the machine's state
 * — and moving to `open` installs effects that resolve their node eagerly
 * (`trapFocus(getContentEl(scope))`). An overlay would install its focus trap,
 * its scroll lock and `hideOthers` against a surface that is not in the document
 * yet. React does not hit this because its watchers run in a layout effect, i.e.
 * after the commit that mounted the surface; the vanilla store reproduces that
 * order deliberately. The harness is safe because it mounts its whole markup up
 * front and never adds a part.
 */

import {
  type Bindable,
  type BindableParams,
  createBindable,
  type ReactivityAdapter,
} from "./machine/reactivity";
import { arrayEquals } from "./utils/equality";
import { invariant } from "./utils/invariant";

const MAX_PASSES = 50;

interface Tracker {
  readonly deps: () => readonly unknown[];
  readonly effect: VoidFunction;
  last: readonly unknown[];
}

export interface ReactivityRoot {
  readonly adapter: ReactivityAdapter;
  /** Called once per settled batch, after trackers have run. */
  subscribe(listener: VoidFunction): VoidFunction;
  /**
   * Re-runs the trackers and notifies. This is how an adapter reports a change the
   * graph cannot see for itself — new props coming down. Context writes flush on
   * their own; a prop is read through a getter the root never observed.
   */
  flush(): void;
  dispose(): void;
}

export function createReactivityRoot(): ReactivityRoot {
  const listeners = new Set<VoidFunction>();
  const trackers: Tracker[] = [];
  const cleanups: VoidFunction[] = [];
  let depth = 0;
  let dirty = false;
  let flushing = false;

  // Re-entrancy is the norm here, not the exception: trackers and listeners write.
  // A write during a flush marks the graph dirty and buys another pass instead of
  // recursing, and listeners only fire on a pass that settled.
  const flush = (): void => {
    if (flushing) return;
    flushing = true;
    try {
      let passes = 0;
      while (dirty) {
        dirty = false;
        for (const tracker of trackers) {
          const next = tracker.deps();
          if (arrayEquals(tracker.last, next)) continue;
          tracker.last = next;
          tracker.effect();
        }
        if (!dirty) {
          for (const listener of [...listeners]) listener();
        }
        passes += 1;
        invariant(passes <= MAX_PASSES, `reactivity did not settle after ${MAX_PASSES} passes`);
      }
    } finally {
      flushing = false;
    }
  };

  const notify = (): void => {
    dirty = true;
    if (depth === 0) flush();
  };

  const adapter: ReactivityAdapter = {
    bindable: <V>(init: () => BindableParams<V>): Bindable<V> =>
      createBindable(init, (initial) => {
        let value = initial;
        return {
          get: (): V => value,
          set: (next: V): void => {
            value = next;
            notify();
          },
        };
      }),

    memo: <V>(compute: () => V, deps: () => readonly unknown[]): (() => V) => {
      let cache: { deps: readonly unknown[]; value: V } | undefined;
      return (): V => {
        const next = deps();
        if (cache === undefined || !arrayEquals(cache.deps, next)) {
          cache = { deps: next, value: compute() };
        }
        return cache.value;
      };
    },

    // Registration does not fire the effect: a watcher reacts to changes, it does
    // not replay the initial state (that is what entry actions are for).
    track: (deps: () => readonly unknown[], effect: VoidFunction): void => {
      trackers.push({ deps, effect, last: deps() });
    },

    batch: (fn: VoidFunction): void => {
      depth += 1;
      try {
        fn();
      } finally {
        depth -= 1;
        if (depth === 0 && dirty) flush();
      }
    },

    onCleanup: (dispose: VoidFunction): void => {
      cleanups.push(dispose);
    },
  };

  return {
    adapter,
    subscribe: (listener: VoidFunction): VoidFunction => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    flush: notify,
    dispose: (): void => {
      for (let index = cleanups.length - 1; index >= 0; index--) cleanups[index]?.();
      cleanups.length = 0;
      trackers.length = 0;
      listeners.clear();
    },
  };
}

export type Direction = "ltr" | "rtl";

export type Orientation = "horizontal" | "vertical";

export type Density = "desktop" | "touch";

// The input vocabulary is the engine's, and the engine is `@standarx/nav`
// (decision 57). Re-exported here so a machine keeps naming its modality and its
// intents from the same module as its direction and its density.
export type { InputModality, IntentEvent, IntentSource, NavigationIntent } from "./nav";

/** Viewport-relative geometry, in the shape `getBoundingClientRect` reports it. */
export interface Rect {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

/**
 * The three modes the styles layer ships, and they are three and not two.
 *
 * `reduced` replaces movement with a crossfade — scales go to 1, distances to 0
 * — and deliberately leaves the durations alone; `none` is the one that flattens
 * them. A boolean cannot carry that difference, and anything downstream that
 * skips an animation on `reduced` is skipping a fade the design kept on purpose.
 */
export type MotionMode = "full" | "reduced" | "none";

export interface EnvironmentContext {
  readonly dir: Direction;
  readonly locale: string;
  readonly density: Density;
  readonly motion: MotionMode;
  /**
   * `motion !== "full"`. Kept because most consumers of it are asking the right
   * question — a smooth scroll and a travelling focus ring are both wrong under
   * either reduced mode. Only the ones deciding whether an animation exists at
   * all need to read `motion`.
   */
  readonly reducedMotion: boolean;
}

/**
 * sRGB colour arithmetic, as pure functions. Nothing here reads a document, a
 * service or a prop accessor — which is what lets the conversions, the parser and
 * the round trip be tested in the `unit` project, with no page anywhere.
 *
 * It sits outside `components/` for the reason `utils/range` does: `color-picker`
 * is the first consumer, not the only one, and per the CDC §5.1 amendment of
 * 2026-08-28 a shared layer with a single consumer carries its own budget line
 * rather than disappearing from every component's.
 *
 * **It imports nothing, on purpose.** `roundToPrecision` in `utils/range` does the
 * same job, but a shared module with a budget line of its own should not drag a
 * second one into every bundle that wanted a hex parser — and the decimal-safe
 * snap `range` is famous for solves a step-grid problem colours do not have.
 *
 * Three rules hold the model together:
 *
 * 1. **HSVA is the source of truth.** RGB and HSL are views, derived on demand.
 * 2. **Hue is anchored on the way in.** sRGB cannot tell a black from a black of
 *    a particular hue, so a conversion that lands on `v === 0` (or `s === 0`)
 *    would throw the hue away and the area would jump the next time it is used.
 *    `anchorHue` puts it back from the colour the write started on.
 * 3. **Rounding is late and once.** Channels stay floating point; only
 *    `formatColor` and `toHex` round, and only to what the notation can carry.
 *
 * Out of scope, and named rather than forgotten: the 148 CSS colour keywords
 * (~1.3 kB min+gzip on their own), `color()`, `lab()`, `lch()`, `oklab()`,
 * `oklch()` and `color-mix()`. OKLCH is excluded from v1 — no design
 * expresses a colour outside sRGB, and the gamut mapping CSS Color 4 requires is
 * the weight of this whole module again.
 */

export interface ColorValue {
  /** 0…360. Kept through achromatic writes rather than recomputed from them. */
  readonly h: number;
  /** 0…100. */
  readonly s: number;
  /** 0…100 — HSV *value*, the "B" of the `hsb` notation. */
  readonly v: number;
  /** 0…1. */
  readonly a: number;
}

/** Channels in 0…255, alpha in 0…1. Floating point until something formats them. */
export interface RgbColor {
  readonly r: number;
  readonly g: number;
  readonly b: number;
  readonly a: number;
}

export interface HslColor {
  readonly h: number;
  readonly s: number;
  readonly l: number;
  readonly a: number;
}

/**
 * `hsb` is this library's own notation, not a CSS one — it is what the panel
 * shows when a designer works in HSB, and `parseColor` accepts it back so a
 * controlled consumer can hand the string it was just given straight in again.
 */
export type ColorFormat = "hex" | "rgb" | "hsl" | "hsb";

export type ColorNumericChannel =
  | "hue"
  | "saturation"
  | "brightness"
  | "alpha"
  | "red"
  | "green"
  | "blue";

/** `hex` is a text channel: it has a field, never a slider — see `getChannelRange`. */
export type ColorChannel = ColorNumericChannel | "hex";

export interface ColorChannelRange {
  readonly min: number;
  readonly max: number;
  readonly step: number;
}

/** Below one hundredth of the smallest step any channel has. */
const EPSILON = 1e-6;

const CHANNEL_RANGES: Readonly<Record<ColorNumericChannel, ColorChannelRange>> = {
  hue: { min: 0, max: 360, step: 1 },
  saturation: { min: 0, max: 100, step: 1 },
  brightness: { min: 0, max: 100, step: 1 },
  alpha: { min: 0, max: 1, step: 0.01 },
  red: { min: 0, max: 255, step: 1 },
  green: { min: 0, max: 255, step: 1 },
  blue: { min: 0, max: 255, step: 1 },
};

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

function round(value: number, decimals: number): number {
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

/** The one circular channel. `359 + 1` is `0`, and `0 − 1` is `359`. */
export function wrapHue(hue: number): number {
  if (!Number.isFinite(hue)) return 0;
  return ((hue % 360) + 360) % 360;
}

/**
 * The range a channel's slider, its arrow keys and its `aria-value*` all read.
 * Total on the numeric channels alone: `hex` has no numbers to bound, and a
 * degenerate range for it is a trap rather than an answer.
 */
export function getChannelRange(channel: ColorNumericChannel): ColorChannelRange {
  return CHANNEL_RANGES[channel];
}

export function hsvToRgb(color: ColorValue): RgbColor {
  const h = wrapHue(color.h) / 60;
  const s = clamp(color.s, 0, 100) / 100;
  const v = clamp(color.v, 0, 100) / 100;
  const chroma = v * s;
  const second = chroma * (1 - Math.abs((h % 2) - 1));
  const base = v - chroma;

  let r = 0;
  let g = 0;
  let b = 0;
  if (h < 1) {
    r = chroma;
    g = second;
  } else if (h < 2) {
    r = second;
    g = chroma;
  } else if (h < 3) {
    g = chroma;
    b = second;
  } else if (h < 4) {
    g = second;
    b = chroma;
  } else if (h < 5) {
    r = second;
    b = chroma;
  } else {
    r = chroma;
    b = second;
  }

  return { r: (r + base) * 255, g: (g + base) * 255, b: (b + base) * 255, a: clamp(color.a, 0, 1) };
}

export function rgbToHsv(r: number, g: number, b: number, a: number): ColorValue {
  const red = clamp(r, 0, 255) / 255;
  const green = clamp(g, 0, 255) / 255;
  const blue = clamp(b, 0, 255) / 255;
  const max = Math.max(red, green, blue);
  const min = Math.min(red, green, blue);
  const delta = max - min;

  let h = 0;
  if (delta > 0) {
    if (max === red) h = ((green - blue) / delta) % 6;
    else if (max === green) h = (blue - red) / delta + 2;
    else h = (red - green) / delta + 4;
    h = wrapHue(h * 60);
  }

  return { h, s: max === 0 ? 0 : (delta / max) * 100, v: max * 100, a: clamp(a, 0, 1) };
}

export function hsvToHsl(color: ColorValue): HslColor {
  const s = clamp(color.s, 0, 100) / 100;
  const v = clamp(color.v, 0, 100) / 100;
  const l = (v * (2 - s)) / 2;
  const edge = Math.min(l, 1 - l);
  return {
    h: wrapHue(color.h),
    s: edge === 0 ? 0 : ((v - l) / edge) * 100,
    l: l * 100,
    a: clamp(color.a, 0, 1),
  };
}

export function hslToHsv(h: number, s: number, l: number, a: number): ColorValue {
  const saturation = clamp(s, 0, 100) / 100;
  const lightness = clamp(l, 0, 100) / 100;
  const v = lightness + saturation * Math.min(lightness, 1 - lightness);
  return {
    h: wrapHue(h),
    s: v === 0 ? 0 : 2 * (1 - lightness / v) * 100,
    v: v * 100,
    a: clamp(a, 0, 1),
  };
}

/** The eight-bit view — what a hex string, an `rgb()` and a swatch all show. */
export function toRgb255(color: ColorValue): RgbColor {
  const rgb = hsvToRgb(color);
  return { r: Math.round(rgb.r), g: Math.round(rgb.g), b: Math.round(rgb.b), a: rgb.a };
}

function pad(value: number): string {
  return clamp(Math.round(value), 0, 255).toString(16).padStart(2, "0");
}

export function toHex(color: ColorValue, withAlpha: boolean): string {
  const { r, g, b } = toRgb255(color);
  const alpha = withAlpha ? pad(clamp(color.a, 0, 1) * 255) : "";
  return `#${pad(r)}${pad(g)}${pad(b)}${alpha}`;
}

/**
 * The hue (and, on black, the saturation) the conversion could not carry.
 * Without it, dragging the brightness to zero and back would come up red.
 */
export function anchorHue(next: ColorValue, previous: ColorValue): ColorValue {
  if (next.v <= EPSILON) return { h: previous.h, s: previous.s, v: next.v, a: next.a };
  if (next.s <= EPSILON) return { h: previous.h, s: next.s, v: next.v, a: next.a };
  return next;
}

export function getChannelValue(color: ColorValue, channel: ColorNumericChannel): number {
  switch (channel) {
    case "hue":
      // 360 is the track's right edge, where `End` puts it: read back as 0, the
      // thumb would be drawn and published at the left. Both edges paint red.
      return color.h === 360 ? 360 : wrapHue(color.h);
    case "saturation":
      return color.s;
    case "brightness":
      return color.v;
    case "alpha":
      return color.a;
    default: {
      const rgb = toRgb255(color);
      if (channel === "red") return rgb.r;
      if (channel === "green") return rgb.g;
      return rgb.b;
    }
  }
}

/**
 * One channel moves, everything else holds still. The RGB channels round-trip
 * through the eight-bit view first, so nudging red by one lands on an integer
 * instead of drifting off the grid a float conversion left it on.
 */
export function withChannel(
  color: ColorValue,
  channel: ColorNumericChannel,
  value: number,
): ColorValue {
  const range = CHANNEL_RANGES[channel];
  const next = clamp(Number.isFinite(value) ? value : 0, range.min, range.max);
  switch (channel) {
    case "hue":
      return { ...color, h: next };
    case "saturation":
      return { ...color, s: next };
    case "brightness":
      return { ...color, v: next };
    case "alpha":
      return { ...color, a: next };
    default: {
      const rgb = toRgb255(color);
      const r = channel === "red" ? next : rgb.r;
      const g = channel === "green" ? next : rgb.g;
      const b = channel === "blue" ? next : rgb.b;
      return anchorHue(rgbToHsv(r, g, b, color.a), color);
    }
  }
}

/**
 * Four numbers, compared with the tolerance the smallest channel step makes
 * meaningless to go below. It is the bindable's `isEqual`: without it every write
 * of a fresh object — which is every write — would report a change and re-render,
 * forever (the defect `arrayEquals` fixes on the slider).
 */
export function colorEquals(a: ColorValue, b: ColorValue): boolean {
  return (
    Math.abs(a.h - b.h) < EPSILON &&
    Math.abs(a.s - b.s) < EPSILON &&
    Math.abs(a.v - b.v) < EPSILON &&
    Math.abs(a.a - b.a) < EPSILON
  );
}

// --- parsing -----------------------------------------------------------------

const HEX_PATTERN = /^#?([0-9a-f]+)$/;
const FUNCTION_PATTERN = /^(rgba?|hsla?|hsba?)\(([^()]*)\)$/;

function parseHex(text: string): ColorValue | null {
  const match = HEX_PATTERN.exec(text);
  if (match === null) return null;
  const digits = match[1] ?? "";
  const size = digits.length;
  if (size !== 3 && size !== 4 && size !== 6 && size !== 8) return null;

  const short = size < 6;
  const width = short ? 1 : 2;
  const read = (index: number): number => {
    const slice = digits.slice(index * width, index * width + width);
    return Number.parseInt(short ? slice + slice : slice, 16);
  };

  const alpha = size === 4 || size === 8 ? read(3) / 255 : 1;
  return rgbToHsv(read(0), read(1), read(2), alpha);
}

interface NumberToken {
  readonly value: number;
  readonly percent: boolean;
}

function readToken(raw: string): NumberToken | null {
  const percent = raw.endsWith("%");
  let body = percent ? raw.slice(0, -1) : raw;
  if (body.endsWith("deg")) body = body.slice(0, -3);
  if (body === "") return null;
  const value = Number(body);
  return Number.isFinite(value) ? { value, percent } : null;
}

/** `50%` is half of whatever the channel's full scale is; a bare number is itself. */
function scaled(token: NumberToken, full: number): number {
  return token.percent ? (token.value / 100) * full : token.value;
}

function parseFunction(text: string): ColorValue | null {
  const match = FUNCTION_PATTERN.exec(text);
  if (match === null) return null;
  const name = match[1] ?? "";
  // Legacy commas, modern spaces and the `/` before an alpha all separate the
  // same four numbers; normalising them is what lets one reader serve both.
  const parts = (match[2] ?? "").replaceAll(",", " ").replaceAll("/", " ").trim().split(/\s+/);
  if (parts.length < 3 || parts.length > 4) return null;

  const tokens: NumberToken[] = [];
  for (const part of parts) {
    const token = readToken(part);
    if (token === null) return null;
    tokens.push(token);
  }

  const [first, second, third, fourth] = tokens as [
    NumberToken,
    NumberToken,
    NumberToken,
    NumberToken | undefined,
  ];
  const alpha = fourth === undefined ? 1 : clamp(scaled(fourth, 1), 0, 1);

  if (name.startsWith("rgb")) {
    return rgbToHsv(scaled(first, 255), scaled(second, 255), scaled(third, 255), alpha);
  }
  if (name.startsWith("hsl")) {
    return hslToHsv(first.value, scaled(second, 100), scaled(third, 100), alpha);
  }
  return {
    h: wrapHue(first.value),
    s: clamp(scaled(second, 100), 0, 100),
    v: clamp(scaled(third, 100), 0, 100),
    a: alpha,
  };
}

/**
 * `null` for anything this module does not read, never a throw: the value comes
 * from a text field as often as from a prop, and a half-typed `#ab` is a normal
 * state of the world rather than an error.
 */
export function parseColor(input: string): ColorValue | null {
  const text = input.trim().toLowerCase();
  if (text === "") return null;
  if (text === "transparent") return { h: 0, s: 0, v: 0, a: 0 };
  return text.includes("(") ? parseFunction(text) : parseHex(text);
}

export function formatColor(color: ColorValue, format: ColorFormat): string {
  const alpha = clamp(color.a, 0, 1);
  const opaque = alpha >= 1;
  const suffix = opaque ? "" : ` / ${round(alpha, 2)}`;

  switch (format) {
    case "hex":
      return toHex(color, !opaque);
    case "rgb": {
      const { r, g, b } = toRgb255(color);
      return `rgb(${r} ${g} ${b}${suffix})`;
    }
    case "hsl": {
      const hsl = hsvToHsl(color);
      return `hsl(${Math.round(hsl.h)} ${Math.round(hsl.s)}% ${Math.round(hsl.l)}%${suffix})`;
    }
    default:
      return `hsb(${Math.round(wrapHue(color.h))} ${Math.round(color.s)}% ${Math.round(color.v)}%${suffix})`;
  }
}

/**
 * Twelve hues and four achromatic answers — what `aria-valuetext` says out loud
 * so a slider reports "hue 210, azure" rather than a bare number. Approximate on
 * purpose: it names a colour, it does not identify one.
 */
const HUE_NAMES: readonly string[] = [
  "red",
  "orange",
  "yellow",
  "chartreuse",
  "green",
  "spring green",
  "cyan",
  "azure",
  "blue",
  "violet",
  "magenta",
  "rose",
];

export function getColorName(color: ColorValue): string {
  if (color.a <= 0) return "transparent";
  if (color.v <= 8) return "black";
  if (color.s <= 8) return color.v >= 92 ? "white" : "gray";
  const name = HUE_NAMES[Math.round(wrapHue(color.h) / 30) % 12] ?? "red";
  if (color.v <= 40) return `dark ${name}`;
  if (color.s <= 40) return `pale ${name}`;
  return name;
}

/**
 * The `Intl` half of the date family: every string a calendar or a segmented
 * field shows, plus the one piece of locale *data* they need — which day the week
 * starts on.
 *
 * Split from `plain-date` rather than folded into it because `date-field` needs
 * the formatter without the grid, and because the two have opposite costs: the
 * arithmetic is free and an `Intl.DateTimeFormat` is the allocation. Hence the
 * module-level cache, which holds no DOM and so cannot leak a document.
 *
 * **`calendar: "gregory"` and `numberingSystem: "latn"` are forced everywhere.**
 * Without them `th-TH` formats 2026 as 2569, `ja-JP-u-ca-japanese` in an imperial
 * era and `ar-EG` in Arabic-Indic digits, while `DateValue.year` stays Gregorian
 * — the display, and worse the segment order `formatToParts` reports, would
 * silently describe a different calendar than the one the machine is counting in.
 * Multi-calendar is out of scope for the v1.
 *
 * **`timeZone: "UTC"` is the default for the same reason `plain-date` builds its
 * dates that way**: the day formatted must be the day stored. `getToday` is the
 * one caller that overrides it, because reading a clock is exactly the operation
 * that has to name its zone.
 *
 * **No weekday table, ever.** The names come off seven known dates. A hand-typed
 * header once read `SUN MON WED THU FRI SAT SUN` — a transcription bug — and anyone transcribing those seven strings would ship a week with
 * no Tuesday.
 */

import { type DateValue, type FirstDayOfWeek, fromParts, toUTCDate } from "./plain-date";

/** The subset of `Intl.DateTimeFormatPart` a segment order is read from. */
export type DateFormatPart = Intl.DateTimeFormatPart;

/** `Intl.Locale.prototype.getWeekInfo` and its historical getter both return this. */
export interface WeekInfo {
  readonly firstDay?: number | undefined;
}

/**
 * The two spellings of week info an `Intl.Locale` may carry. Neither is in the
 * TypeScript lib — one is a normative addition, the other predates it — so the
 * shape is declared here rather than asserted at each call.
 */
export interface WeekInfoLocale {
  readonly getWeekInfo?: (() => WeekInfo) | undefined;
  readonly weekInfo?: WeekInfo | undefined;
}

export type WeekInfoResolver = (locale: string | undefined) => WeekInfoLocale | null;

export interface FirstDayOfWeekOptions {
  /** The last rung: what a runtime carrying neither spelling answers. ISO Monday. */
  readonly fallback?: FirstDayOfWeek | undefined;
  /**
   * Injected by the tests. The CI matrix runs current Chromium, Firefox and
   * WebKit, all three of which have `getWeekInfo`, so the two lower rungs cannot
   * be reached by asserting against an engine — the same arbitration the gamepad
   * loop made when it took an injected runtime instead of a real pad.
   */
  readonly resolve?: WeekInfoResolver | undefined;
}

/** Anything wider than this is a table of locale data, which is what we refuse. */
export type DateLabelWidth = "narrow" | "short" | "long";

const formatters = new Map<string, Intl.DateTimeFormat>();

/** 7 January 2024 is a Sunday, which makes it index 0 of the Sunday-zero week. */
const REFERENCE_SUNDAY = Date.UTC(2024, 0, 7);
const DAY_MS = 86_400_000;

function defaultResolve(locale: string | undefined): WeekInfoLocale | null {
  try {
    return new Intl.Locale(
      locale ?? new Intl.DateTimeFormat().resolvedOptions().locale,
    ) as unknown as WeekInfoLocale;
  } catch {
    return null;
  }
}

export function getDateFormatter(
  locale: string | undefined,
  options: Intl.DateTimeFormatOptions,
): Intl.DateTimeFormat {
  const resolved: Intl.DateTimeFormatOptions = {
    ...options,
    calendar: "gregory",
    numberingSystem: "latn",
    timeZone: options.timeZone ?? "UTC",
  };
  const key = `${locale ?? ""}|${JSON.stringify(resolved)}`;
  const cached = formatters.get(key);
  if (cached !== undefined) return cached;
  const formatter = new Intl.DateTimeFormat(locale, resolved);
  formatters.set(key, formatter);
  return formatter;
}

export function formatDate(
  value: DateValue,
  locale: string | undefined,
  options: Intl.DateTimeFormatOptions,
): string {
  return getDateFormatter(locale, options).format(toUTCDate(value));
}

/**
 * The only honest source of segment order. `en-US` is month/day/year, `de-DE` is
 * day.month.year and `ja-JP` is year/month/day, and the literals between them are
 * part of the answer — a table of patterns would be a fourth calendar to maintain.
 */
export function formatDateToParts(
  value: DateValue,
  locale: string | undefined,
  options: Intl.DateTimeFormatOptions,
): DateFormatPart[] {
  return getDateFormatter(locale, options).formatToParts(toUTCDate(value));
}

/** Seven labels in display order, starting on `firstDayOfWeek`. */
export function getWeekdayLabels(
  locale: string | undefined,
  firstDayOfWeek: FirstDayOfWeek = 1,
  width: DateLabelWidth = "short",
): string[] {
  const formatter = getDateFormatter(locale, { weekday: width });
  const offset = firstDayOfWeek % 7;
  return Array.from({ length: 7 }, (_, index) =>
    formatter.format(REFERENCE_SUNDAY + ((offset + index) % 7) * DAY_MS),
  );
}

/** Twelve labels, January first — the order a month view lays them out in. */
export function getMonthLabels(
  locale: string | undefined,
  width: DateLabelWidth = "long",
): string[] {
  const formatter = getDateFormatter(locale, { month: width });
  return Array.from({ length: 12 }, (_, index) => formatter.format(Date.UTC(2024, index, 1)));
}

function readFirstDay(locale: WeekInfoLocale | null): number | null {
  if (locale === null) return null;
  const info = typeof locale.getWeekInfo === "function" ? locale.getWeekInfo() : locale.weekInfo;
  const firstDay = info?.firstDay;
  return typeof firstDay === "number" ? firstDay : null;
}

/**
 * Three rungs, in this order: the normative `getWeekInfo()`, the historical
 * `weekInfo` getter, then a fallback the consumer injects — Monday by default,
 * which is ISO-8601's answer.
 *
 * Deliberately **not** a region → first-day table. That blob is exactly what the
 * one-dependency rule invites and it rots; all three engines carry the API in
 * 2026, and the residue is covered by the `firstDayOfWeek` prop.
 */
export function resolveFirstDayOfWeek(
  locale: string | undefined,
  options: FirstDayOfWeekOptions = {},
): FirstDayOfWeek {
  const firstDay = readFirstDay((options.resolve ?? defaultResolve)(locale));
  if (firstDay !== null && firstDay >= 1 && firstDay <= 7) return firstDay as FirstDayOfWeek;
  return options.fallback ?? 1;
}

/**
 * The clock, read once and in a zone that is named rather than assumed.
 *
 * A server in UTC and a client in `Pacific/Auckland` are not on the same day, and
 * that is a real hydration divergence, not a theoretical one — which is why the
 * machines freeze this in a ref at init and reconcile on the first client
 * `ENVIRONMENT.SYNC` instead of marking a cell as today during the server render.
 */
export function getToday(timeZone?: string): DateValue {
  const parts = getDateFormatter(undefined, {
    year: "numeric",
    month: "numeric",
    day: "numeric",
    timeZone: timeZone ?? Intl.DateTimeFormat().resolvedOptions().timeZone,
  }).formatToParts(new Date());
  const read = (type: string): number =>
    Number(parts.find((part) => part.type === type)?.value ?? "");
  return fromParts(read("year"), read("month"), read("day"));
}

// `process` is declared locally rather than pulled from @types/node: the core has
// `types: []` and must stay usable in a browser with no bundler, where the global
// does not exist. Bundlers that define NODE_ENV still fold the comparison away.
// Dot access, not a computed key: that is the exact form bundlers substitute.
declare const process: { env?: { NODE_ENV?: string } } | undefined;

export function isDev(): boolean {
  return typeof process === "undefined" || process?.env?.NODE_ENV !== "production";
}

export function arrayEquals(a: readonly unknown[], b: readonly unknown[]): boolean {
  if (a === b) return true;
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (!Object.is(a[i], b[i])) return false;
  }
  return true;
}

export function shallowEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) return false;
  if (Array.isArray(a) || Array.isArray(b)) {
    return Array.isArray(a) && Array.isArray(b) && arrayEquals(a, b);
  }
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  for (const key of keysA) {
    if (!Object.hasOwn(b, key)) return false;
    if (!Object.is((a as Record<string, unknown>)[key], (b as Record<string, unknown>)[key])) {
      return false;
    }
  }
  return true;
}

/**
 * Where a sliding indicator sits, measured rather than derived from an index.
 *
 * An index is a position only where `grid-auto-columns: 1fr` makes it one, and
 * that stops being true the moment the items are sized by their own text, which
 * is every tab list: the same arithmetic would put the pill beside the thing it
 * points at. So the geometry is read, and it is read here — shared with `tabs`,
 * `radio-group` and `toggle-group`, and with the `tab-bar` presentation.
 * `getIndicatorMetrics` is pure and takes boxes in the track's own pixels;
 * `measureIndicator` reads them from the elements, dividing out the scale of an
 * ancestor, and gives way to the caller's layout boxes when a segment is itself
 * scaled, as it is while pressed.
 *
 * Pure, and expressed **logically**: the horizontal branch measures from the
 * start edge of the writing direction, which is what lets the stylesheet consume
 * it as `inset-inline-start` and RTL cost nobody a second rule. `inset-*` rather
 * than `translate` is the other half of that decision — a percentage `translate`
 * resolves against the element's own border box, which WebKit rounds to whole
 * pixels (motion.md amendment).
 */

import type { Direction, Orientation } from "../types";

/** The fields of a `DOMRect` this module reads — a `DOMRect` satisfies it as is. */
export interface IndicatorBox {
  readonly left: number;
  readonly right: number;
  readonly top: number;
  readonly width: number;
  readonly height: number;
}

/** The scroll and border offsets of the track — an `HTMLElement` satisfies it. */
export interface IndicatorScroll {
  readonly scrollLeft: number;
  readonly scrollTop: number;
  readonly clientLeft: number;
  readonly clientTop: number;
}

export interface IndicatorAxis {
  readonly orientation: Orientation;
  readonly dir: Direction;
}

export interface IndicatorMetrics {
  /** Along the main axis, from the track's padding-box start, in CSS pixels. */
  readonly offset: number;
  readonly size: number;
}

/**
 * Relative to the track's **padding box**, scroll included: the indicator is
 * positioned inside that box, so a viewport-relative reading would drift the
 * moment the track scrolled or the page did.
 */
export function getIndicatorMetrics(
  track: IndicatorBox,
  item: IndicatorBox,
  scroll: IndicatorScroll,
  axis: IndicatorAxis,
): IndicatorMetrics {
  if (axis.orientation === "vertical") {
    return {
      offset: item.top - track.top + scroll.scrollTop - scroll.clientTop,
      size: item.height,
    };
  }
  // In RTL the start edge is the right one, and `scrollLeft` counts down from
  // zero there. The mirror is spent here and nowhere else.
  const rtl = axis.dir === "rtl";
  const start = rtl ? track.right - item.right : item.left - track.left;
  return {
    offset: start + (rtl ? -scroll.scrollLeft : scroll.scrollLeft) - scroll.clientLeft,
    size: item.width,
  };
}

/**
 * The border box of an element along one axis, in CSS pixels and with its
 * fraction — `offsetWidth` rounds and the computed size does not. `NaN` for a box
 * with no used size.
 */
function borderBoxSize(style: CSSStyleDeclaration, vertical: boolean): number {
  const size = Number.parseFloat(vertical ? style.height : style.width);
  if (style.boxSizing === "border-box") return size;
  const edges = vertical
    ? [style.paddingTop, style.paddingBottom, style.borderTopWidth, style.borderBottomWidth]
    : [style.paddingLeft, style.paddingRight, style.borderLeftWidth, style.borderRightWidth];
  return edges.reduce((total, edge) => total + Number.parseFloat(edge), size);
}

/**
 * `getIndicatorMetrics` fed from the elements themselves, in the track's own CSS
 * pixels and to a fraction of one. The bounding rects carry every transform on
 * the way up, so the track's rect over its layout size is divided out — which is
 * what lets a group inside a dialog that is still scaling in measure in CSS
 * pixels. `null` when the rects cannot be trusted: the item is itself transformed
 * (a segment is, while it is pressed), or the track has no usable size. The
 * caller reads the layout boxes then.
 */
export function measureIndicator(
  track: HTMLElement,
  item: HTMLElement,
  getStyle: (node: Element) => CSSStyleDeclaration,
  axis: IndicatorAxis,
): IndicatorMetrics | null {
  const vertical = axis.orientation === "vertical";
  const trackStyle = getStyle(track);
  const itemStyle = getStyle(item);
  const outer = track.getBoundingClientRect();
  const ratio = (vertical ? outer.height : outer.width) / borderBoxSize(trackStyle, vertical);
  const transformed = [
    itemStyle.transform,
    itemStyle.scale,
    itemStyle.rotate,
    itemStyle.translate,
  ].some((entry) => entry !== "none");
  if (transformed || !Number.isFinite(ratio) || ratio === 0) return null;

  const inTrack = (box: DOMRect): IndicatorBox => ({
    left: (box.left - outer.left) / ratio,
    right: (box.right - outer.left) / ratio,
    top: (box.top - outer.top) / ratio,
    width: box.width / ratio,
    height: box.height / ratio,
  });
  return getIndicatorMetrics(
    inTrack(outer),
    inTrack(item.getBoundingClientRect()),
    {
      scrollLeft: track.scrollLeft,
      scrollTop: track.scrollTop,
      clientLeft: Number.parseFloat(trackStyle.borderInlineStartWidth),
      clientTop: Number.parseFloat(trackStyle.borderTopWidth),
    },
    axis,
  );
}

export function invariant(condition: unknown, message: string): asserts condition {
  if (!condition) {
    throw new Error(`[standarui] ${message}`);
  }
}

export function warn(condition: unknown, message: string): void {
  if (condition && typeof console !== "undefined") {
    console.warn(`[standarui] ${message}`);
  }
}

/**
 * A civil date — a year, a month and a day — and the arithmetic that goes with
 * it. No hour, no zone, no `Date` in the value: `calendar`, `date-field` and
 * `date-picker` all hold this shape, and it is structurally a subset of
 * `Temporal.PlainDate` (same keys, same 1-based month), so `PlainDate.from(value)`
 * accepts it the day Safari ships Temporal and we can drop the polyfill question
 * entirely.
 *
 * It sits outside `components/` for the same reason `utils/range` does, and with
 * three consumers on day one rather than one — per the CDC §5.1 amendment of
 * 2026-08-28 it therefore carries its own budget line.
 *
 * **Every conversion goes through UTC, and only through UTC.** A local `Date` is
 * the one thing this module refuses: `new Date(2026, 2, 29)` in a zone that skips
 * an hour that night is a different day than the one asked for, and the bug
 * surfaces twice a year in one hemisphere. `getUTC*` cannot drift.
 *
 * **The two-digit-year shim is still in the language.** `Date.UTC(50, 3, 1)` is
 * 1950, not the year 50, and so is every constructor that takes a year argument.
 * `toUTCDate` sets the fields on an epoch date instead, which is the only
 * construction that means what it says across the whole domain.
 *
 * **The bounds are enforced where a value enters, not on every step.** `fromParts`
 * clamps and `fromISO` refuses, because those are the props and the form field;
 * `addDays` and `addMonths` answer faithfully, because arithmetic that silently
 * clamped would make a month grid repeat a cell rather than overflow.
 */

/** Month is 1-based — the way a human writes it, and the way `Temporal` does. */
export interface DateValue {
  readonly year: number;
  readonly month: number;
  readonly day: number;
}

/** ISO-8601 numbering: 1 is Monday, 7 is Sunday. What `getWeekInfo` reports. */
export type FirstDayOfWeek = 1 | 2 | 3 | 4 | 5 | 6 | 7;

export interface MonthGridOptions {
  readonly firstDayOfWeek?: FirstDayOfWeek | undefined;
  /**
   * Six rows whatever the month. Without it a surface changes height between
   * February and August, and no stylesheet can reserve for a row it cannot count.
   */
  readonly fixedWeeks?: boolean | undefined;
}

/**
 * `toISO` writes `YYYY-MM-DD` and defines no extended `±YYYYYY` form; ICU picks
 * an era of its own for year 0 and below, and a form field is read by servers
 * that parse four digits. Three reasons, one domain.
 *
 * Exported because a year segment is a `spinbutton` and has to declare its
 * `aria-valuemin`/`aria-valuemax` — the alternative is the same two literals
 * written again somewhere that cannot see this file.
 */
export const MIN_DATE_YEAR = 1;
export const MAX_DATE_YEAR = 9999;

const MONTH_LENGTHS: readonly number[] = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

function clampInt(value: number, min: number, max: number): number {
  if (!Number.isFinite(value)) return min;
  return Math.min(Math.max(Math.trunc(value), min), max);
}

function toOrdinal(value: DateValue): number {
  return value.year * 10000 + value.month * 100 + value.day;
}

export function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

export function daysInMonth(year: number, month: number): number {
  const index = clampInt(month, 1, 12);
  if (index === 2) return isLeapYear(year) ? 29 : 28;
  return MONTH_LENGTHS[index - 1] ?? 31;
}

/** The way a prop becomes a value: out of range is clamped, never thrown. */
export function fromParts(year: number, month: number, day: number): DateValue {
  const y = clampInt(year, MIN_DATE_YEAR, MAX_DATE_YEAR);
  const m = clampInt(month, 1, 12);
  return { year: y, month: m, day: clampInt(day, 1, daysInMonth(y, m)) };
}

/** Midnight UTC on that day — the bridge to `Intl` and to any `Date` API. */
export function toUTCDate(value: DateValue): Date {
  const date = new Date(0);
  date.setUTCFullYear(value.year, value.month - 1, value.day);
  return date;
}

/** Reads what the `Date` says, bounds included: it is arithmetic, not a prop. */
export function fromUTCDate(date: Date): DateValue {
  return { year: date.getUTCFullYear(), month: date.getUTCMonth() + 1, day: date.getUTCDate() };
}

export function addDays(value: DateValue, days: number): DateValue {
  const date = toUTCDate(value);
  date.setUTCDate(date.getUTCDate() + days);
  return fromUTCDate(date);
}

/**
 * The clamp is the whole point: 31 January plus one month is the 28th or the
 * 29th of February, never the 2nd or 3rd of March.
 */
export function addMonths(value: DateValue, months: number): DateValue {
  const total = value.year * 12 + (value.month - 1) + months;
  const year = Math.floor(total / 12);
  const month = (((total % 12) + 12) % 12) + 1;
  return { year, month, day: Math.min(value.day, daysInMonth(year, month)) };
}

/** Through the months, so 29 February plus a year lands on the 28th. */
export function addYears(value: DateValue, years: number): DateValue {
  return addMonths(value, years * 12);
}

/** Negative, zero or positive — on the ordinal, so no `Date` is allocated. */
export function compareDates(a: DateValue, b: DateValue): number {
  return toOrdinal(a) - toOrdinal(b);
}

export function clampDate(
  value: DateValue,
  min?: DateValue | null,
  max?: DateValue | null,
): DateValue {
  if (min !== null && min !== undefined && compareDates(value, min) < 0) return min;
  if (max !== null && max !== undefined && compareDates(value, max) > 0) return max;
  return value;
}

export function startOfMonth(value: DateValue): DateValue {
  return { year: value.year, month: value.month, day: 1 };
}

export function endOfMonth(value: DateValue): DateValue {
  return { year: value.year, month: value.month, day: daysInMonth(value.year, value.month) };
}

/** 0 is Sunday — the numbering `Date.prototype.getUTCDay` already speaks. */
export function getDayOfWeek(value: DateValue): number {
  return toUTCDate(value).getUTCDay();
}

/**
 * The column a date lands in, 0…6. `firstDayOfWeek` is ISO and `% 7` is what
 * turns it into the Sunday-zero numbering above — 7 (Sunday) becomes 0.
 */
export function getWeekdayIndex(value: DateValue, firstDayOfWeek: FirstDayOfWeek = 1): number {
  return (getDayOfWeek(value) - (firstDayOfWeek % 7) + 7) % 7;
}

/**
 * A month, flattened into whole weeks: the days before the 1st and after the
 * last are the real neighbouring dates, not holes. A cell with no date is
 * unaddressable and breaks the APG grid count — `outsideDays: "hidden"` is the
 * stylesheet's business.
 *
 * Four rows, five or six depending on where the month starts; six always under
 * `fixedWeeks`.
 */
export function getMonthGrid(
  year: number,
  month: number,
  options: MonthGridOptions = {},
): DateValue[] {
  const first = fromParts(year, month, 1);
  const lead = getWeekdayIndex(first, options.firstDayOfWeek ?? 1);
  const weeks =
    options.fixedWeeks === true ? 6 : Math.ceil((lead + daysInMonth(first.year, first.month)) / 7);
  const cells: DateValue[] = [];
  // One `Date` walked forward rather than one per cell: this runs on every month
  // change, and the memo above it keys on four values that all change together.
  const cursor = toUTCDate(first);
  cursor.setUTCDate(cursor.getUTCDate() - lead);
  for (let index = 0; index < weeks * 7; index++) {
    cells.push(fromUTCDate(cursor));
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }
  return cells;
}

/**
 * The ISO-8601 week of the year, 1…53 — the number a calendar puts in its
 * `weekNumber` column.
 *
 * ISO numbers a week by the year its **Thursday** falls in, which is why the walk
 * below goes to that Thursday first: the last days of December belong to week 1
 * of the year after about three times a decade, and a naive "days since 1 January
 * divided by seven" reports 53 for them. `firstDayOfWeek` deliberately plays no
 * part — the number is ISO's whatever day the grid starts on, and a locale that
 * lays its week out from Sunday still calls that week the same one.
 */
export function getWeekNumber(value: DateValue): number {
  const thursday = toUTCDate(addDays(value, 3 - ((getDayOfWeek(value) + 6) % 7)));
  // 4 January is in week 1 by definition, so its own Thursday anchors the count.
  const fourth: DateValue = { year: thursday.getUTCFullYear(), month: 1, day: 4 };
  const anchor = toUTCDate(addDays(fourth, 3 - ((getDayOfWeek(fourth) + 6) % 7)));
  return 1 + Math.round((thursday.getTime() - anchor.getTime()) / (7 * 86_400_000));
}

export function toISO(value: DateValue): string {
  const year = String(value.year).padStart(4, "0");
  const month = String(value.month).padStart(2, "0");
  return `${year}-${month}-${String(value.day).padStart(2, "0")}`;
}

/**
 * Strict, and `null` rather than a clamp: a form or a prop that carries
 * `2026-02-30` is a bug in the consumer, and inventing the 28th for them would
 * hide it. Only the four-digit form is accepted — the extended `±YYYYYY` form is
 * outside the domain, not merely unsupported.
 */
export function fromISO(input: string | null | undefined): DateValue | null {
  const match = typeof input === "string" ? ISO_DATE.exec(input) : null;
  if (match === null) return null;
  const year = Number(match[1] ?? "");
  const month = Number(match[2] ?? "");
  const day = Number(match[3] ?? "");
  if (year < MIN_DATE_YEAR || year > MAX_DATE_YEAR || month < 1 || month > 12) return null;
  if (day < 1 || day > daysInMonth(year, month)) return null;
  return { year, month, day };
}

/**
 * The arithmetic of a bounded numeric range, as pure functions. Nothing here
 * reads a document, a service or a prop accessor — which is what lets the snap,
 * the multi-thumb constraint and the point→percent conversion be tested in the
 * `unit` project, with no page anywhere.
 *
 * It sits outside `components/` because `slider` is the first consumer, not the
 * only one: `range-slider` is the same arithmetic with two thumbs already
 * handled below, and any scrubber or rating control lands on `constrainValue`
 * and `getPercentFromPoint` unchanged. Per the CDC §5.1 amendment of 2026-08-28,
 * a shared layer with a single consumer carries its own budget line rather than
 * disappearing from every component's — see `scripts/size-budget.ts`.
 *
 * Two of these carry the traps the pattern is famous for.
 *
 * **The snap has to round twice.** `Math.round((v - min) / step) * step + min` is
 * the textbook formula and it produces `0.30000000000000004` for `step: 0.1`,
 * which then reaches `aria-valuenow` and a screen reader reads it out. The second
 * rounding is to the precision the inputs themselves declare.
 *
 * **The vertical axis has no writing order.** `getPercentFromPoint` inverts it
 * always, because 0 % sits at the bottom whatever the direction — independently
 * of the RTL inversion, which only ever touches the horizontal one.
 */

import type { Direction, Orientation, Rect } from "../types";

/** Explicit positions, a count of evenly spaced ticks, or one tick per step. */
export type RangeMarks = readonly number[] | number | "step";

/** Everything the constraint arithmetic needs, and nothing else. */
export interface RangeBounds {
  readonly min: number;
  readonly max: number;
  readonly step: number;
  readonly minStepsBetweenThumbs: number;
}

export interface RangePointOptions {
  readonly rect: Rect;
  readonly orientation: Orientation;
  readonly dir: Direction;
  /** Thumb extent along the axis — 0 when the thumb is centred on the value. */
  readonly thumbSize: number;
}

/** `marks: "step"` on a tiny step is a mistake, not a design. */
const MAX_MARKS = 256;

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

function decimalCount(value: number): number {
  const dot = String(value).indexOf(".");
  return dot === -1 ? 0 : String(value).length - dot - 1;
}

export function roundToPrecision(value: number, decimals: number): number {
  if (decimals <= 0) return Math.round(value);
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

/** Nearest multiple of `step` counted from `min`, then rounded back to sanity. */
export function snapToStep(value: number, min: number, step: number): number {
  if (!(step > 0)) return value;
  const snapped = Math.round((value - min) / step) * step + min;
  return roundToPrecision(snapped, Math.max(decimalCount(step), decimalCount(min)));
}

/**
 * Clamp, snap, clamp. The second clamp is not redundant: snapping a value that
 * sits just under a `max` which is not itself on the step grid pushes it over.
 */
export function constrainValue(value: number, range: RangeBounds): number {
  const snapped = snapToStep(clamp(value, range.min, range.max), range.min, range.step);
  return clamp(snapped, range.min, range.max);
}

/**
 * The one normalisation the props go through. A scalar is an ergonomic shorthand
 * for a one-thumb control; the context never sees it.
 */
export function toValueArray(
  input: number | readonly number[] | undefined,
  fallback = 0,
): number[] {
  if (input === undefined) return [fallback];
  return typeof input === "number" ? [input] : [...input];
}

/** Constrains every thumb, then pushes the array back into ascending order. */
export function normalizeValues(values: readonly number[], range: RangeBounds): number[] {
  const result = values.map((value) => constrainValue(value, range));
  const spacing = range.minStepsBetweenThumbs * range.step;
  for (let index = 1; index < result.length; index++) {
    const floor = (result[index - 1] ?? range.min) + spacing;
    if ((result[index] ?? range.min) < floor) result[index] = clamp(floor, range.min, range.max);
  }
  return result;
}

/**
 * Writing one thumb, bounded by its neighbours. With a single thumb the
 * neighbours are `min` and `max` and the whole thing collapses to a clamp — which
 * is why `range-slider` costs nothing extra later.
 */
export function setValueAtIndex(
  values: readonly number[],
  index: number,
  next: number,
  range: RangeBounds,
): number[] {
  const result = [...values];
  if (index < 0 || index >= result.length) return result;
  const spacing = range.minStepsBetweenThumbs * range.step;
  const last = result.length - 1;
  const low = index === 0 ? range.min : (result[index - 1] ?? range.min) + spacing;
  const high = index === last ? range.max : (result[index + 1] ?? range.max) - spacing;
  result[index] = clamp(constrainValue(next, range), Math.min(low, high), Math.max(low, high));
  return result;
}

/** 0…1, clamped: a controlled value outside the range still paints inside it. */
export function toPercent(value: number, min: number, max: number): number {
  if (max <= min) return 0;
  return clamp((value - min) / (max - min), 0, 1);
}

export function fromPercent(percent: number, min: number, max: number): number {
  return min + percent * (max - min);
}

export function resolveLargeStep(
  requested: number | undefined,
  min: number,
  max: number,
  step: number,
): number {
  if (requested !== undefined && requested > 0) return Math.max(requested, step);
  return Math.max(snapToStep((max - min) / 10, 0, step), step);
}

/**
 * Viewport point → 0…1 along the control. Two inversions, and they are
 * independent: RTL flips the horizontal axis, and the vertical axis is flipped
 * always, because 0 % sits at the bottom whatever the writing direction.
 */
export function getPercentFromPoint(x: number, y: number, options: RangePointOptions): number {
  const { rect, orientation, dir, thumbSize } = options;
  const vertical = orientation === "vertical";
  // A contained thumb: its centre travels between the two half-thumb insets, so
  // the usable track is shorter than the control by exactly one thumb.
  const travel = Math.max((vertical ? rect.height : rect.width) - thumbSize, 0);
  if (travel === 0) return 0;
  const ratio = ((vertical ? y - rect.y : x - rect.x) - thumbSize / 2) / travel;
  return clamp(vertical || dir === "rtl" ? 1 - ratio : ratio, 0, 1);
}

export function resolveMarks(
  marks: RangeMarks | undefined,
  min: number,
  max: number,
  step: number,
): number[] {
  if (marks === undefined) return [];
  if (Array.isArray(marks)) return [...marks];

  const stepped = marks === "step";
  const total = stepped ? Math.floor((max - min) / step) + 1 : (marks as number);
  if (total < 2) return total < 1 ? [] : [min];
  const count = Math.min(total, MAX_MARKS);
  const gap = stepped ? step : (max - min) / (count - 1);
  // Capped: an evenly spaced gap is rarely a round number, and `10 ** 16` is past
  // the point where the rounding trick stops rounding anything.
  const decimals = Math.min(Math.max(decimalCount(gap), decimalCount(min)), 6);
  return Array.from({ length: count }, (_, index) => roundToPrecision(min + index * gap, decimals));
}

export function toKebabCase(value: string): string {
  // Two passes, in this order: an acronym run ("XI") has to split from the
  // capitalized word it leads into before the lowercase-to-uppercase pass runs,
  // or the run's own internal boundary (upper-to-upper) is invisible to it.
  return value
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1-$2")
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .toLowerCase();
}
